INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C1','kor',6,2,'u4',1,'낱말의 세 갈래 — 고유어는 우리말에 처음부터 있던 낱말이나 그것을 바탕으로 만들어진 낱말, 한자어는 한자로 이루어진 낱말, 외래어는 다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말이며, 세 갈래가 어울려 우리말을 이룬다',ARRAY['6국04 문법(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C2','kor',6,2,'u4',1,'우리말을 바르게 쓴다는 것 — 고유어만 쓰거나 한자어·외래어를 몰아내는 것이 아니라, 듣는 사람이 알아들을 수 있게, 낱말의 뜻에 맞게, 바꿀 수 있는 말은 쉬운 우리말로 바꾸어 쓰고, 누구에게 어디에서 말하느냐에 따라 상황에 맞게 골라 쓰는 것',ARRAY['6국04 문법(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C3','kor',6,2,'u4',1,'말이 잘 통하지 않을 때 — 지나치게 줄인 말(아는 사람끼리만 통함)·뜻을 알기 어려운 새말(뜻이 서로 다르게 통함)·기분을 상하게 하는 말(뜻은 통해도 마음이 다침)·굳이 어렵게 쓴 외국어(쉬운 우리말을 두고 알아듣기 어려움)는 되묻기·대화에서 밀려나기·다툼을 낳는다',ARRAY['6국04 문법(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C4','kor',6,2,'u4',2,'국어사전으로 갈래 가리기 — 낱말 뒤에 아무것도 붙지 않고 한글 표기만 있으면 고유어, 한자가 함께 있으면 한자어, 영어 등의 외국어가 함께 있으면 외래어이며, 헷갈리는 낱말은 소리나 모양으로 짐작하지 말고 사전에서 확인한다(종이 사전·스마트 기기 사전 모두 같은 방법)',ARRAY['6국04 문법(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C5','kor',6,2,'u4',2,'고유어의 두 모습과 가치 — 고유어는 처음부터 있던 낱말(이슬·호미)과 그것을 바탕으로 만들어진 낱말(나들이·마중물)이 있어 지금도 새로 만들어질 수 있고, 우리말의 기본 바탕을 이루며, 뜻을 쉽게 짐작할 수 있고 느낌을 살려 표현할 수 있고(싱긋·껄껄) 우리 문화와 정서를 담는다',ARRAY['6국04 문법(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C6','kor',6,2,'u4',2,'갈래에 등수 없음 · 다듬은 말 — 세 갈래는 하는 일이 다를 뿐 좋고 나쁨이 없으며, 쉬운 우리말이 있는데도 굳이 어렵게 쓴 말은 다듬고(노견→갓길·익일→다음 날·회람→돌려보기·다운로드→내려받기) 바꿀 말이 마땅치 않거나 바꾸면 오히려 통하지 않는 말(컴퓨터·버스·학교·수학)은 그대로 쓴다 — 다듬기의 목적은 몰아내기가 아니라 누구나 알아듣게 하기',ARRAY['6국04 문법(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C7','kor',6,2,'u4',2,'고유어로 이루어진 관용 표현 — 둘 이상의 낱말이 어울려 새로운 뜻을 만드는 표현(손이 크다=씀씀이가 넉넉하다 · 입이 짧다=음식을 심하게 가리거나 적게 먹다 · 낯을 가리다=낯선 사람을 어려워하다)으로, 낱말 뜻을 하나씩 더해서는 뜻이 나오지 않으며 우리 문화와 정서를 담는다',ARRAY['6국04 문법(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C8','kor',6,2,'u4',4,'고유어를 활용한 사례 찾기 — 동네·길·가게·음식 이름에는 고유어를 살려 지은 것이 많으며(너른들·나루터길·새참·수제비), 여러 낱말로 이루어진 이름은 낱말을 나누어(나루터 + 길) 그 낱말이 고유어인지 사전에서 확인한다',ARRAY['6국01 듣기·말하기(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C9','kor',6,2,'u4',4,'조사 계획과 정리 · 확인과 짐작 가르기 — 조사 대상·범위(손이 닿는 곳으로 좁게)·방법(국어사전·믿을 만한 누리집·어른께 여쭙기)을 먼저 정하고, 유형·사례·고유어·고유어의 뜻 네 칸으로 정리하며, 사전에서 찾은 것·짐작한 것·아직 확인하지 못한 것을 갈라 말하고 지어내지 않는다',ARRAY['6국01 듣기·말하기(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C10','kor',6,2,'u4',4,'매체를 활용한 발표와 듣기 — 알릴 내용을 정한 뒤 그에 맞는 매체(사진·그림·지도·표·종이 자료)를 고르고, 출처가 믿을 만한가·양이 시간에 알맞은가·매체가 도움이 되는가를 점검하며, 발표하는 사람은 유형·사례·뜻을 차례대로 말하고 출처를 밝히고, 듣는 사람은 정리하며 듣고 궁금한 점을 까닭과 함께 묻는다(묻고 답하기까지가 발표)',ARRAY['6국01 듣기·말하기(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C11','kor',6,2,'u4',6,'우리말을 지키기 위한 노력 — 말은 저절로 남지 않으며, 우리말을 마음껏 쓰지 못하던 때에도 흩어진 낱말과 고장마다 다른 말까지 모아 우리말 사전을 만들려던 사람들이 있었고 그 기록이 오늘 국어사전의 바탕이 되었다 — 사전에서 확인하기·쉬운 말로 바꾸기·고장 말을 여쭈어 적기·다른 고장 말을 웃음거리로 삼지 않기도 지키는 일',ARRAY['6국04 문법(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C12','kor',6,2,'u4',6,'생략된 내용 추론하며 읽기 — 글쓴이가 적지 않은 부분을 글의 단서(인물의 말과 행동·때와 곳·되풀이되거나 눈에 띄는 부분)와 내가 가진 경험·지식으로 메우는 일이며, 까닭은 반드시 글 안에 있어야 하고(마음대로 상상하기와 다름), 글에 적힌 것과 추론한 것을 가르고, 처음 보는 낱말은 앞뒤 문맥으로 뜻을 짐작한다',ARRAY['6국02 읽기(초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C13','kor',6,2,'u4',6,'표준어와 방언 — 표준어는 온 나라 사람이 두루 통하게 쓰도록 정한 말로 사는 곳이 달라도 서로 통하게 해 주고, 방언은 어느 고장에서 주로 쓰는 표준어가 아닌 말로 그 고장의 정과 역사를 담아 전하며(부엌-정지 · 무-무시 · 김치-짐치), 둘 사이에 등수는 없고 공식적인 자리에서는 표준어로, 고장 사람과는 고장 말로 상황에 맞게 쓴다',ARRAY['6국04 문법(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C14','kor',6,2,'u4',8,'언어생활 점검하기 — 여러 사람에게 전하는 글일수록 누구나 알아듣게 써야 하며, 굳이 외국어로 쓴 말·지나치게 줄인 말·기분을 상하게 하는 말·즐겨 쓰는 고유어를 스스로 표시해 우리 반의 실태로 정리하고, 점검은 친구를 흠잡는 일이 아니라 먼저 내가 쓴 말부터 적고 함께 고치려는 일이다',ARRAY['6국04 문법(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C15','kor',6,2,'u4',8,'실천 다짐문 쓰기와 고쳐 쓰기 — 목적·구체적인 실천 약속(언제·어디에서·무엇을)·전하고 싶은 말·날짜와 쓴 사람 네 부분을 갖추고, 크게 말하는 다짐보다 지킬 수 있는 다짐을 쓰며, 친구 다짐문은 잘 쓴 부분 먼저·고칠 점은 내용에서·바꾸어 볼 문장과 함께 말하고, 나누고 실천한 뒤 되돌아본다',ARRAY['6국03 쓰기(초안)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C16','kor',6,2,'u4',11,'우리말 지킴이 활동 — 알릴 내용에 맞는 방법(알림 영상·인쇄물·만화·우리말 일기·지킴이 도전)을 고르고, 주제·내용·역할·시간을 정해 계획하며, 홍보 문구는 읽는 사람이 알아들을 수 있고 할 일이 보이게 쓰고(어려운 외국어·탓하는 말·꾸밈에 가려진 내용 금지), 하루 행사로 끝내지 않고 이어서 실천한다',ARRAY['6국03 쓰기(초안)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C17','kor',6,2,'u4',11,'교과 학습에 자주 나오는 낱말 — 증발(액체가 그 표면에서 기체로 변하는 현상)·지형(땅의 생긴 모양)·분포(일정한 범위에 흩어져 퍼져 있음)·관측(자연 현상을 살펴 재거나 헤아리는 일)은 모두 한자어이며, 뜻만 외우기보다 문장으로 한 번 써 보면 오래 남는다(기초 다지기)',ARRAY['6국04 문법(초안)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X01','kor',6,'u4',ARRAY['K6-2-u4-C1','K6-2-u4-C4','K6-2-u4-C8']::text[],'낱말의 갈래를 헷갈린다(한자어·외래어를 자주 쓰거나 익숙하다는 까닭으로 고유어로 여기는 등)','처음부터 있던 말? 한자? 다른 나라에서 온 말?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X02','kor',6,'u4',ARRAY['K6-2-u4-C2','K6-2-u4-C6','K6-2-u4-C16']::text[],'우리말을 바르게 쓰는 것을 고유어만 쓰는 것, 한자어와 외래어를 몰아내는 것으로 여긴다','알아들을 수 있게 · 뜻에 맞게 · 바꿀 수 있는 말만 쉽게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X03','kor',6,'u4',ARRAY['K6-2-u4-C2','K6-2-u4-C3','K6-2-u4-C14']::text[],'어려운 말·외국어·줄인 말을 많이 쓰면 더 많이 알거나 멋있어 보인다고 여겨, 듣는 사람이 알아듣지 못하는 문제를 보지 않는다','말은 뜻을 주고받으려고 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X04','kor',6,'u4',ARRAY['K6-2-u4-C3','K6-2-u4-C14']::text[],'말이 잘 통하지 않는 네 경우와 그 결과를 헷갈리거나, 뜻만 통하면 마음이 다쳐도 괜찮다고 여긴다','줄인 말 · 새말 · 기분 상하는 말 · 어려운 외국어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X05','kor',6,'u4',ARRAY['K6-2-u4-C4']::text[],'국어사전의 표시를 보지 않고 소리나 글자 모양으로 갈래를 짐작한다','낱말 뒤에 무엇이 붙어 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X06','kor',6,'u4',ARRAY['K6-2-u4-C5']::text[],'고유어를 옛날에만 쓰던 말로 여기거나, 고유어를 바탕으로 새로 만든 낱말은 고유어가 아니라고 여긴다','처음부터 있던 말 + 그것으로 만든 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X07','kor',6,'u4',ARRAY['K6-2-u4-C5','K6-2-u4-C6','K6-2-u4-C13']::text[],'낱말의 갈래나 표준어·방언에 등수를 매겨 고유어(표준어)는 훌륭한 말, 다른 말은 못한 말로 여긴다','하는 일이 다를 뿐, 등수는 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X08','kor',6,'u4',ARRAY['K6-2-u4-C6']::text[],'다듬기의 목적을 글자 수 줄이기나 모든 한자어·외래어 바꾸기로 여겨, 바꿀 말이 마땅치 않은 말까지 바꾸려 한다','다듬기 = 누구나 알아듣게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X09','kor',6,'u4',ARRAY['K6-2-u4-C7']::text[],'관용 표현을 낱말 뜻을 하나씩 더해 글자 그대로 풀이한다','둘 이상이 어울려 새로운 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X10','kor',6,'u4',ARRAY['K6-2-u4-C8']::text[],'이름을 낱말로 나누어 보지 않거나, 외국어·한자어로 지은 이름을 고유어 활용 사례로 든다','이름을 낱말로 나누고 사전에서 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X11','kor',6,'u4',ARRAY['K6-2-u4-C9']::text[],'조사 대상과 범위를 너무 넓게 잡거나 방법을 정하지 않아 뜻까지 알아볼 시간이 없다','손이 닿는 곳으로 좁게, 방법 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X12','kor',6,'u4',ARRAY['K6-2-u4-C9','K6-2-u4-C10']::text[],'확인한 것·짐작한 것·모르는 것을 섞어 지어내 말하거나, 출처를 밝히지 않고 친구 말을 그대로 옮긴다','「찾은 뜻」·「짐작」·「아직 확인 못 함」 가르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X13','kor',6,'u4',ARRAY['K6-2-u4-C10','K6-2-u4-C16']::text[],'알릴 내용보다 매체나 꾸밈을 먼저 정하거나, 화려하고 많은 자료가 좋은 자료라고 여긴다','내용 먼저, 매체와 꾸밈은 그다음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X14','kor',6,'u4',ARRAY['K6-2-u4-C10']::text[],'듣는 사람의 할 일(정리하며 듣기·까닭 있는 질문)을 하지 않거나 묻고 답하기를 발표가 아니라고 여긴다','궁금한 점 + 그것이 궁금한 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X15','kor',6,'u4',ARRAY['K6-2-u4-C11']::text[],'말은 쓰는 사람이 있으면 저절로 남는다고 여기거나, 사전 만들기를 낱말을 모으는 일로만 보고 말을 지키는 일과 잇지 못한다','적어 두고 이어 주어야 남아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X16','kor',6,'u4',ARRAY['K6-2-u4-C12']::text[],'추론을 글에 없는 일을 마음대로 상상하는 것으로 여기거나, 까닭 없이 「그냥 그럴 것 같아서」라고 말한다','글의 어느 부분을 보고 그렇게 생각했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X17','kor',6,'u4',ARRAY['K6-2-u4-C12']::text[],'글에 그대로 적힌 것과 단서로 추론한 것을 가르지 못하거나, 글에 적혀 있지 않으면 아무것도 알 수 없다고 여긴다','적힌 것 → 단서 → 메운 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X18','kor',6,'u4',ARRAY['K6-2-u4-C12','K6-2-u4-C5']::text[],'처음 보는 낱말의 뜻을 앞뒤 문맥을 살피지 않고 글자 모양이나 느낌만으로 짐작한다','앞뒤 말에서 실마리 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X19','kor',6,'u4',ARRAY['K6-2-u4-C13','K6-2-u4-C11']::text[],'방언을 고쳐야 할 틀린 말·배우지 못한 사람의 말·웃음거리로 여기거나, 표준어와 방언의 뜻을 헷갈린다','방언도 소중한 우리말 — 쓰이는 자리가 다를 뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X20','kor',6,'u4',ARRAY['K6-2-u4-C13','K6-2-u4-C2']::text[],'상황과 듣는 사람을 살피지 않고 어디에서나 한 가지 말만 쓰려 한다(공식적인 자리에서도 고장 말만, 고장 사람과도 표준어만)','누구에게 · 어디에서?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X21','kor',6,'u4',ARRAY['K6-2-u4-C14']::text[],'언어생활 점검을 친구를 흠잡거나 누가 더 많이 썼는지 세어 견주는 일로 여긴다','내가 쓴 말부터, 우리 반의 일로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X22','kor',6,'u4',ARRAY['K6-2-u4-C15']::text[],'실천 다짐문의 네 부분(목적·실천 약속·전하고 싶은 말·날짜와 쓴 사람)을 빠뜨리거나 하는 일을 헷갈린다','무엇을 위해 · 무엇을 · 부탁 · 누가 언제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X23','kor',6,'u4',ARRAY['K6-2-u4-C15','K6-2-u4-C16']::text[],'「열심히」·「하나도」·「다들」처럼 무엇을 할지 없거나 지킬 수 없을 만큼 크거나 내가 할 일이 없는 다짐을 좋은 다짐으로 여긴다','언제 · 어디에서 · 무엇을 — 내가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X24','kor',6,'u4',ARRAY['K6-2-u4-C15']::text[],'고쳐 쓸 점을 글씨·종이 같은 겉모습에서 찾거나, 잘 쓴 부분은 말하지 않고 흠만 말한다(또는 반대로 고칠 점을 말하지 않는다)','잘 쓴 곳 먼저, 고칠 점은 내용에서, 바꿀 문장과 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X25','kor',6,'u4',ARRAY['K6-2-u4-C16']::text[],'우리말 홍보물을 어려운 외국어 문구·누군가를 탓하는 말·꾸밈으로 채우거나 역할·계획 없이 꾸미기부터 한다','알릴 것이 한눈에, 할 일이 보이게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X26','kor',6,'u4',ARRAY['K6-2-u4-C16','K6-2-u4-C15']::text[],'홍보물을 만들거나 다짐문을 쓴 날 하루로 실천이 끝났다고 여긴다','행사가 아니라 실천 — 이어서 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X27','kor',6,'u4',ARRAY['K6-2-u4-C16']::text[],'알릴 내용과 맞지 않는 활동 방법을 고른다(여러 번 보게 할 낱말을 한 번 틀고 마는 영상으로 등)','이 방법이 잘 살리는 점은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X28','kor',6,'u4',ARRAY['K6-2-u4-C17']::text[],'교과 학습 낱말(증발·지형·분포·관측)의 뜻을 서로 헷갈리거나 뜻만 외우고 쓰임을 모른다','낱말을 넣어 문장으로 써 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#1','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',1,'mc','auto','「고유어」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X19']::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"mc","stem":"「고유어」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리말에 처음부터 있던 낱말이나 그것을 바탕으로 만들어진 낱말","correct":true},{"t":"한자로 이루어진 낱말","mis":"K6-2-u4-X01"},{"t":"다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말","mis":"K6-2-u4-X01"},{"t":"어느 고장에서만 주로 쓰는 낱말","mis":"K6-2-u4-X19"}],"explanation":["한자로 이루어진 낱말은 한자어예요.","다른 나라에서 들어온 낱말은 외래어예요.","처음부터 있던 말과 그것으로 만든 말이 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#2','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',1,'sa','auto','다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C1","difficulty":1,"kind":"sa","stem":"다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["외래어"],"explanation":["고유어는 처음부터 있던 말이에요.","한자어는 한자로 된 말이에요.","다른 나라에서 들어와 널리 쓰이면 외래어예요."],"mis":"K6-2-u4-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#3','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',1,'ox','auto','우리말을 바르게 쓴다는 것은 고유어만 쓰는 것이에요.',ARRAY['K6-2-u4-X02']::text[],false,'{"seq":3,"concept":"K6-2-u4-C2","difficulty":1,"kind":"ox","stem":"우리말을 바르게 쓴다는 것은 고유어만 쓰는 것이에요.","answer":"X","reason_options":[{"t":"듣는 사람이 알아들을 수 있게, 뜻에 맞게 쓰는 것이기 때문에","correct":true},{"t":"한자어와 외래어는 우리말을 해치기 때문에","mis":"K6-2-u4-X02"}],"mis":"K6-2-u4-X02","explanation":["우리말에는 세 갈래가 모두 들어 있어요.","바르게 쓰기는 알아들을 수 있게, 뜻에 맞게 쓰는 것이에요.","다른 갈래를 몰아내는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#4','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C3',1,'mc','auto','지나치게 줄인 말을 쓰면 어떤 일이 생길 수 있나요?',ARRAY['K6-2-u4-X03','K6-2-u4-X04']::text[],false,'{"seq":4,"concept":"K6-2-u4-C3","difficulty":1,"kind":"mc","stem":"지나치게 줄인 말을 쓰면 어떤 일이 생길 수 있나요?","options":[{"t":"아는 사람끼리만 통해서 옆 사람이 알아듣지 못한다","correct":true},{"t":"누구나 더 빨리 알아듣는다","mis":"K6-2-u4-X03"},{"t":"낱말의 뜻이 저절로 바뀐다","mis":"K6-2-u4-X04"},{"t":"아무 일도 생기지 않는다","mis":"K6-2-u4-X04"}],"explanation":["줄인 말은 짧아서 편해 보여요.","그러나 아는 사람끼리만 통해요.","함께 있는 사람이 대화에서 밀려나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#5','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',2,'mc','auto','할머니가 말한 「해거름」은 어떤 때를 가리키나요?',ARRAY['K6-2-u4-X18']::text[],false,'{"seq":5,"concept":"K6-2-u4-C1","difficulty":2,"kind":"mc","stem":"할머니가 말한 「해거름」은 어떤 때를 가리키나요?","options":[{"t":"해가 서쪽으로 넘어갈 무렵","correct":true},{"t":"해가 막 떠오르는 이른 아침","mis":"K6-2-u4-X18"},{"t":"해가 지고 한참 지난 깊은 밤","mis":"K6-2-u4-X18"},{"t":"해가 하늘 한가운데 있는 낮","mis":"K6-2-u4-X18"}],"explanation":["할머니가 「산 너머로 넘어가려고 붉어질 때」라고 다시 말해 주었어요.","해솔이도 「저녁이 되기 조금 전」이라고 짐작했어요.","앞뒤 말을 살피면 처음 듣는 낱말도 뜻을 짐작할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"해솔아, 해거름 전에 텃밭 좀 둘러보고 오렴."},{"who":"해솔","text":"네? 해거름이요? 그게 언제인데요?"},{"who":"할머니","text":"저 해가 산 너머로 넘어가려고 붉어질 때 있잖니. 그때 말이다."},{"who":"해솔","text":"아, 저녁이 되기 조금 전이요? 처음 들어 본 말이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#6','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',2,'match','auto','낱말과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C1","difficulty":2,"kind":"match","stem":"낱말과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"나들이","r":"고유어"},{"l":"체육","r":"한자어"},{"l":"버튼","r":"외래어"}],"mis":"K6-2-u4-X01","explanation":["나들이는 처음부터 있던 우리말이에요.","체육은 한자로 된 말이에요.","버튼은 다른 나라에서 들어와 널리 쓰이는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#7','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',2,'mc','auto','우리말을 바르게 사용하는 사람의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X03','K6-2-u4-X19']::text[],false,'{"seq":7,"concept":"K6-2-u4-C2","difficulty":2,"kind":"mc","stem":"우리말을 바르게 사용하는 사람의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람이 알아들을 수 있는 말로 뜻에 맞게 쓴다","correct":true},{"t":"한자어와 외래어는 하나도 쓰지 않는다","mis":"K6-2-u4-X02"},{"t":"어려운 말을 많이 써서 많이 아는 것처럼 보인다","mis":"K6-2-u4-X03"},{"t":"고장의 말을 쓰는 친구를 틀렸다고 고쳐 준다","mis":"K6-2-u4-X19"}],"explanation":["말은 뜻을 주고받으려고 써요.","알아들을 수 있게, 뜻에 맞게 쓰는 것이 바르게 쓰는 거예요.","다른 갈래나 고장 말을 몰아내는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#8','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C3',2,'mc','auto','기분을 상하게 하는 말이 문제가 되는 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X04']::text[],false,'{"seq":8,"concept":"K6-2-u4-C3","difficulty":2,"kind":"mc","stem":"기분을 상하게 하는 말이 문제가 되는 까닭은 어느 것인가요?","options":[{"t":"뜻은 통해도 듣는 사람의 마음이 다치기 때문에","correct":true},{"t":"뜻이 통하니 아무 문제가 없기 때문에","mis":"K6-2-u4-X04"},{"t":"아는 사람끼리만 통하기 때문에","mis":"K6-2-u4-X04"},{"t":"국어사전에 실려 있지 않기 때문에","mis":"K6-2-u4-X04"}],"explanation":["기분을 상하게 하는 말은 뜻은 잘 통해요.","그래도 듣는 사람의 마음이 다쳐요.","아는 사람끼리만 통하는 것은 줄인 말의 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#9','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',2,'ox','auto','「체육」은 고유어예요.',ARRAY['K6-2-u4-X01']::text[],false,'{"seq":9,"concept":"K6-2-u4-C1","difficulty":2,"kind":"ox","stem":"「체육」은 고유어예요.","answer":"X","reason_options":[{"t":"한자로 이루어진 한자어이기 때문에","correct":true},{"t":"우리가 날마다 쓰는 말이기 때문에","mis":"K6-2-u4-X01"}],"mis":"K6-2-u4-X01","explanation":["날마다 쓴다고 고유어가 되는 것은 아니에요.","체육은 한자로 이루어진 말이에요.","그래서 한자어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#10','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',3,'error','auto','이 단원의 약속에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X07','K6-2-u4-X02']::text[],false,'{"seq":10,"concept":"K6-2-u4-C2","difficulty":3,"kind":"error","stem":"이 단원의 약속에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「고유어를 쓰는 사람이 우리말을 더 잘 쓰는 사람이야.」","correct":true,"mis_target":"K6-2-u4-X07"},{"t":"서하 — 「바꿀 수 있는 말은 쉬운 우리말로 바꾸어 쓰면 좋아.」","mis":"K6-2-u4-X02"},{"t":"윤아 — 「우리말에는 고유어 · 한자어 · 외래어가 모두 들어 있어.」","mis":"K6-2-u4-X02"}],"explanation":["서하와 윤아는 약속을 바르게 말했어요.","도윤은 갈래에 등수를 매겼어요.","고유어를 쓴 사람이 더 낫다고 여기는 것은 약속과 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#1','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',2,'mc','auto','「굳이 어렵게 쓴 외국어」에 해당하는 것은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X19','K6-2-u4-X01']::text[],false,'{"seq":1,"concept":"K6-2-u4-C3","difficulty":2,"kind":"mc","stem":"「굳이 어렵게 쓴 외국어」에 해당하는 것은 어느 것인가요?","options":[{"t":"쉬운 우리말이 있는데도 외국어를 그대로 쓴 말","correct":true},{"t":"바꿀 말이 마땅히 없어 널리 쓰는 외래어","mis":"K6-2-u4-X08"},{"t":"어느 고장에서 주로 쓰는 말","mis":"K6-2-u4-X19"},{"t":"오래전부터 쓰던 고유어","mis":"K6-2-u4-X01"}],"explanation":["버스처럼 바꿀 말이 없는 외래어는 그대로 써요.","문제는 쉬운 우리말이 있는데도 어렵게 쓴 말이에요.","그러면 알아듣기 어려워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#2','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C11',2,'sa','auto','우리말을 마음껏 쓰지 못하던 때, 흩어진 낱말을 모아 우리말 무엇을 만들려고 애쓴 사람들이 있었나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C11","difficulty":2,"kind":"sa","stem":"우리말을 마음껏 쓰지 못하던 때, 흩어진 낱말을 모아 우리말 무엇을 만들려고 애쓴 사람들이 있었나요? 두 글자로 쓰세요.","answer":["사전"],"explanation":["온 나라에서 쓰이는 낱말을 모아 적었어요.","고장마다 다른 말도 함께 모았어요.","그 기록이 오늘 국어사전의 바탕이 되었어요."],"mis":"K6-2-u4-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#3','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C2',3,'mc','auto','해솔이와 할머니의 대화에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X03','K6-2-u4-X06']::text[],false,'{"seq":3,"concept":"K6-2-u4-C2","difficulty":3,"kind":"mc","stem":"해솔이와 할머니의 대화에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"처음 듣는 고유어도 앞뒤 말로 뜻을 짐작할 수 있다","correct":true},{"t":"「해거름」은 틀린 말이라 쓰면 안 된다","mis":"K6-2-u4-X19"},{"t":"할머니는 일부러 어려운 말을 골라 썼다","mis":"K6-2-u4-X03"},{"t":"고유어는 옛날 사람만 쓰는 말이다","mis":"K6-2-u4-X06"}],"explanation":["할머니가 다시 풀어 말해 주었어요.","해솔이는 앞뒤 말로 뜻을 짐작했어요.","해거름은 지금도 쓰는 우리말이에요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"해솔아, 해거름 전에 텃밭 좀 둘러보고 오렴."},{"who":"해솔","text":"네? 해거름이요? 그게 언제인데요?"},{"who":"할머니","text":"저 해가 산 너머로 넘어가려고 붉어질 때 있잖니. 그때 말이다."},{"who":"해솔","text":"아, 저녁이 되기 조금 전이요? 처음 들어 본 말이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#4','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',3,'mc','auto','새로 전학 온 친구가 우리 반 아이들끼리 쓰는 줄인 말을 못 알아들어 대화에 끼지 못했어요. 무엇이 문제인가요?',ARRAY['K6-2-u4-X03','K6-2-u4-X04']::text[],false,'{"seq":4,"concept":"K6-2-u4-C3","difficulty":3,"kind":"mc","stem":"새로 전학 온 친구가 우리 반 아이들끼리 쓰는 줄인 말을 못 알아들어 대화에 끼지 못했어요. 무엇이 문제인가요?","options":[{"t":"아는 사람끼리만 통하는 말을 써서 함께 있는 사람이 대화에서 밀려났다","correct":true},{"t":"전학 온 친구가 우리말을 잘 몰라서","mis":"K6-2-u4-X03"},{"t":"줄인 말은 사전에 없어 모두 틀린 말이라서","mis":"K6-2-u4-X04"},{"t":"대화하는 목소리가 작아서","mis":"K6-2-u4-X04"}],"explanation":["문제는 친구가 아니라 말에 있어요.","줄인 말은 아는 사람끼리만 통해요.","그래서 함께 있는 사람이 밀려나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#5','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C11',3,'ox','auto','우리말 사전을 만들려던 사람들은 서울에서 쓰는 말만 모았어요.',ARRAY['K6-2-u4-X19']::text[],false,'{"seq":5,"concept":"K6-2-u4-C11","difficulty":3,"kind":"ox","stem":"우리말 사전을 만들려던 사람들은 서울에서 쓰는 말만 모았어요.","answer":"X","reason_options":[{"t":"고장마다 다르게 쓰는 말도 함께 모았기 때문에","correct":true},{"t":"서울 말만 바른 우리말이기 때문에","mis":"K6-2-u4-X19"}],"mis":"K6-2-u4-X19","explanation":["서울에서 쓰는 말만 모으지 않았어요.","고장마다 다르게 쓰는 말도 모았어요.","고장 말도 소중한 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#6','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',3,'match','auto','말이 잘 통하지 않는 경우와 생기는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C3","difficulty":3,"kind":"match","stem":"말이 잘 통하지 않는 경우와 생기는 일을 알맞게 이으세요.","pairs":[{"l":"지나치게 줄인 말","r":"아는 사람끼리만 통한다"},{"l":"뜻을 알기 어려운 새말","r":"뜻이 서로 다르게 통한다"},{"l":"기분을 상하게 하는 말","r":"뜻은 통해도 마음이 다친다"},{"l":"굳이 어렵게 쓴 외국어","r":"쉬운 말을 두고 알아듣기 어려워진다"}],"mis":"K6-2-u4-X04","explanation":["줄인 말은 끼리끼리만 통해요.","새말은 금방 생겼다 사라져 뜻이 엇갈려요.","기분 상하는 말은 마음을, 어려운 외국어는 알아듣기를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#7','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C1',3,'error','auto','낱말의 갈래를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X05']::text[],false,'{"seq":7,"concept":"K6-2-u4-C1","difficulty":3,"kind":"error","stem":"낱말의 갈래를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「‘버스’는 우리가 날마다 타니까 고유어야.」","correct":true,"mis_target":"K6-2-u4-X01"},{"t":"이안 — 「‘나들이’는 사전에 한글 표기만 있으니 고유어야.」","mis":"K6-2-u4-X05"},{"t":"채윤 — 「‘체육’은 사전에 한자가 함께 있으니 한자어야.」","mis":"K6-2-u4-X05"}],"explanation":["이안과 채윤은 사전 표시로 갈래를 가렸어요.","하율은 자주 쓴다는 까닭으로 갈래를 정했어요.","버스는 다른 나라에서 들어온 외래어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#8','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C2',4,'mc','auto','이 단원의 약속에 가장 가깝게 말한 것은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X02','K6-2-u4-X03']::text[],false,'{"seq":8,"concept":"K6-2-u4-C2","difficulty":4,"kind":"mc","stem":"이 단원의 약속에 가장 가깝게 말한 것은 어느 것인가요?","options":[{"t":"「‘다운로드’는 ‘내려받기’로 바꾸어도 잘 통하니 바꾸어 쓰고, ‘버스’처럼 바꿀 말이 마땅치 않은 말은 그대로 쓰자.」","correct":true},{"t":"「‘버스’도 고유어로 바꾸어야 우리말을 지킬 수 있어.」","mis":"K6-2-u4-X08"},{"t":"「‘체육’ 같은 한자어는 쓰지 않는 것이 바른 거야.」","mis":"K6-2-u4-X02"},{"t":"「어려운 외국어를 섞어 써야 발표가 멋있어.」","mis":"K6-2-u4-X03"}],"explanation":["바꿀 수 있는 말은 쉬운 우리말로 바꾸어요.","바꿀 말이 마땅치 않은 말은 그대로 써요.","목적은 누구나 알아듣게 하는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#9','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C2',4,'essay','teacher','「우리말을 바르게 쓴다는 것은 고유어만 쓰는 것이다.」라는 말이 왜 알맞지 않은지 쓰고, 우리말을 바르게 쓴다는 것이 무엇인지 세 가지로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C2","difficulty":4,"kind":"essay","stem":"「우리말을 바르게 쓴다는 것은 고유어만 쓰는 것이다.」라는 말이 왜 알맞지 않은지 쓰고, 우리말을 바르게 쓴다는 것이 무엇인지 세 가지로 쓰세요.","answer_guide":{"answer":"예: 우리말에는 고유어 · 한자어 · 외래어가 모두 들어 있고, 채소나 버스처럼 다른 갈래의 낱말이 없으면 말할 수 없는 것도 많다. 그래서 고유어만 쓰는 것이 바르게 쓰는 것은 아니다. 바르게 쓴다는 것은 듣는 사람이 알아들을 수 있게 쓰는 것, 낱말의 뜻에 맞게 쓰는 것, 바꿀 수 있는 말은 쉬운 우리말로 바꾸어 쓰는 것이다.","scoring_points":["세 갈래가 함께 우리말을 이룬다는 점을 썼는가","고유어만 쓰는 것이 바르게 쓰는 것이 아닌 까닭을 썼는가","바르게 쓰기의 세 가지를 썼는가"]},"explanation":["우리말에는 세 갈래가 모두 있어요.","몰아내기가 아니라 알아듣게 쓰기예요.","뜻에 맞게, 바꿀 수 있는 말은 쉽게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#10','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',4,'essay','teacher','말이 잘 통하지 않는 경우를 두 가지 골라 그때 생기는 일을 쓰고, 그런 일이 생기지 않게 하려면 어떻게 말하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C3","difficulty":4,"kind":"essay","stem":"말이 잘 통하지 않는 경우를 두 가지 골라 그때 생기는 일을 쓰고, 그런 일이 생기지 않게 하려면 어떻게 말하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 지나치게 줄인 말을 쓰면 아는 사람끼리만 통해서 함께 있는 사람이 대화에서 밀려난다. 굳이 어렵게 쓴 외국어를 쓰면 쉬운 우리말이 있는데도 듣는 사람이 알아듣지 못해 되묻게 된다. 그러니 듣는 사람이 누구인지 살피고, 줄인 말은 풀어서, 어려운 외국어는 쉬운 우리말로 바꾸어 말한다.","scoring_points":["말이 잘 통하지 않는 경우를 두 가지 바르게 골랐는가","각 경우에 생기는 일을 썼는가","듣는 사람을 살펴 고쳐 말하는 방법을 썼는가"]},"explanation":["네 경우를 떠올려요.","그때 누가 어떻게 곤란한지 써요.","듣는 사람의 처지에서 고쳐 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#1','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C4',1,'mc','auto','국어사전에서 낱말 뒤에 한자가 함께 있으면 그 낱말은 어떤 갈래인가요?',ARRAY['K6-2-u4-X05','K6-2-u4-X19']::text[],false,'{"seq":1,"concept":"K6-2-u4-C4","difficulty":1,"kind":"mc","stem":"국어사전에서 낱말 뒤에 한자가 함께 있으면 그 낱말은 어떤 갈래인가요?","options":[{"t":"한자어","correct":true},{"t":"고유어","mis":"K6-2-u4-X05"},{"t":"외래어","mis":"K6-2-u4-X05"},{"t":"방언","mis":"K6-2-u4-X19"}],"explanation":["아무것도 붙지 않으면 고유어예요.","외국어가 함께 있으면 외래어예요.","한자가 함께 있으면 한자어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#2','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',1,'sa','auto','펌프에서 물이 나오지 않을 때 물을 끌어올리려고 위에서 붓는 물을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C5","difficulty":1,"kind":"sa","stem":"펌프에서 물이 나오지 않을 때 물을 끌어올리려고 위에서 붓는 물을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["마중물"],"explanation":["물을 마중 나간다는 말에서 왔어요.","두 낱말을 이어 보면 뜻에 가까이 갈 수 있어요.","그래서 고유어는 뜻을 짐작하기 쉬워요."],"mis":"K6-2-u4-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#3','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',1,'ox','auto','고유어는 지금도 새로 만들어질 수 있어요.',ARRAY['K6-2-u4-X06']::text[],false,'{"seq":3,"concept":"K6-2-u4-C5","difficulty":1,"kind":"ox","stem":"고유어는 지금도 새로 만들어질 수 있어요.","answer":"O","reason_options":[{"t":"고유어를 이어 붙여 새 낱말을 만들 수 있기 때문에","correct":true},{"t":"고유어는 옛날에 있던 낱말만을 말하기 때문에","mis":"K6-2-u4-X06"}],"mis":"K6-2-u4-X06","explanation":["고유어에는 처음부터 있던 낱말이 있어요.","그것을 바탕으로 만든 낱말도 있어요.","그래서 지금도 새로 만들어질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#4','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C6',1,'mc','auto','「노견」을 쉬운 우리말로 다듬은 말은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X03']::text[],false,'{"seq":4,"concept":"K6-2-u4-C6","difficulty":1,"kind":"mc","stem":"「노견」을 쉬운 우리말로 다듬은 말은 어느 것인가요?","options":[{"t":"갓길","correct":true},{"t":"노변","mis":"K6-2-u4-X08"},{"t":"사이드 로드","mis":"K6-2-u4-X03"},{"t":"고속 도로","mis":"K6-2-u4-X08"}],"explanation":["노견은 길의 가장자리를 말해요.","갓길이라고 하면 뜻이 바로 보여요.","그래서 누구나 알아들을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#5','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',2,'mc','auto','이 글에서 고유어를 살펴보아야 하는 까닭으로 든 것은 어느 것인가요?',ARRAY['K6-2-u4-X07','K6-2-u4-X06','K6-2-u4-X01']::text[],false,'{"seq":5,"concept":"K6-2-u4-C5","difficulty":2,"kind":"mc","stem":"이 글에서 고유어를 살펴보아야 하는 까닭으로 든 것은 어느 것인가요?","options":[{"t":"고유어가 우리말의 기본 바탕을 이루기 때문에","correct":true},{"t":"다른 갈래의 낱말보다 훌륭한 말이기 때문에","mis":"K6-2-u4-X07"},{"t":"옛날에만 쓰던 말이라 이제는 쓰지 않기 때문에","mis":"K6-2-u4-X06"},{"t":"낱말의 수가 가장 적기 때문에","mis":"K6-2-u4-X01"}],"explanation":["글의 첫 문장에 까닭이 있어요.","고유어는 우리말의 기본 바탕이에요.","다른 갈래보다 훌륭하다는 말은 없어요."],"asset":{"type":"passage","lines":["고유어는 우리말의 기본 바탕을 이룬다.","오랫동안 많은 사람이 써 온 낱말이라 살아온 모습과 느낌이 함께 담겨 있다.","첫째, 고유어는 뜻을 쉽게 짐작할 수 있다. 「마중물」은 물을 마중 나간다는 말에서 왔다.","둘째, 고유어는 느낌을 살려 표현할 수 있다.","같은 웃음이라도 「싱긋」과 「껄껄」은 다른 모습을 떠올리게 한다.","셋째, 고유어로 이루어진 표현에는 우리 문화와 정서가 담겨 있다."],"title":"고유어에는 어떤 가치가 있을까요?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#6','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C4',2,'mc','auto','별하의 글에 나온 낱말 가운데 고유어가 아닌 것은 어느 것인가요?',ARRAY['K6-2-u4-X01']::text[],false,'{"seq":6,"concept":"K6-2-u4-C4","difficulty":2,"kind":"mc","stem":"별하의 글에 나온 낱말 가운데 고유어가 아닌 것은 어느 것인가요?","options":[{"t":"채소","correct":true},{"t":"이슬","mis":"K6-2-u4-X01"},{"t":"호미","mis":"K6-2-u4-X01"},{"t":"두둑","mis":"K6-2-u4-X01"}],"explanation":["이슬 · 호미 · 두둑은 사전에 한글 표기만 있어요.","채소는 사전에 한자가 함께 있어요.","채소는 한자어예요."],"asset":{"type":"passage","lines":["토요일 아침, 별하는 할머니를 따라 텃밭에 나갔다.","밤새 내린 이슬이 잎마다 맺혀 있었다.","할머니는 호미를 하나 건네주시며 두둑 사이의 풀을 뽑으라고 하셨다.","별하는 채소가 이렇게 촘촘히 심겨 있는 줄 몰랐다.","붉게 익은 토마토를 따서 바구니에 담았다.","일을 마치고 마루에 앉으니 등이 뻐근했다.","할머니가 웃으셨다. 「오늘은 네 덕에 일이 수월했구나.」"],"title":"별하가 토요일 아침에 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#7','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',2,'match','auto','고유어와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u4-C5","difficulty":2,"kind":"match","stem":"고유어와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"여울","r":"물살이 세게 흐르는 얕은 곳"},{"l":"마중물","r":"물을 끌어올리려고 위에서 붓는 물"},{"l":"손사래","r":"아니라고 할 때 손을 펴서 휘젓는 일"}],"mis":"K6-2-u4-X18","explanation":["여울은 물살이 센 얕은 곳이에요.","마중물은 물을 마중 나가는 물이에요.","세 낱말 모두 눈에 보이는 모습을 담고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#8','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C7',2,'mc','auto','「손이 크다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":8,"concept":"K6-2-u4-C7","difficulty":2,"kind":"mc","stem":"「손이 크다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"씀씀이가 넉넉하다","correct":true},{"t":"손의 크기가 남보다 크다","mis":"K6-2-u4-X09"},{"t":"힘이 아주 세다","mis":"K6-2-u4-X09"},{"t":"손재주가 좋다","mis":"K6-2-u4-X09"}],"explanation":["관용 표현은 낱말 뜻을 그대로 더한 것이 아니에요.","둘 이상의 낱말이 어울려 새로운 뜻을 만들어요.","손이 크다는 씀씀이가 넉넉하다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#9','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C6',2,'ox','auto','「컴퓨터」도 고유어로 다듬어 써야 해요.',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":9,"concept":"K6-2-u4-C6","difficulty":2,"kind":"ox","stem":"「컴퓨터」도 고유어로 다듬어 써야 해요.","answer":"X","reason_options":[{"t":"바꿀 말이 마땅히 없어 그대로 쓰는 것이 더 잘 통하기 때문에","correct":true},{"t":"외래어는 모두 우리말로 바꾸어야 하기 때문에","mis":"K6-2-u4-X08"}],"mis":"K6-2-u4-X08","explanation":["다듬는 말은 쉬운 우리말이 이미 있는 말이에요.","컴퓨터는 바꿀 말이 마땅치 않아요.","그대로 쓰는 것이 오히려 잘 통해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#10','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C6',3,'error','auto','낱말의 갈래에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X07','K6-2-u4-X02']::text[],false,'{"seq":10,"concept":"K6-2-u4-C6","difficulty":3,"kind":"error","stem":"낱말의 갈래에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「한자어를 쓰면 우리말을 해치는 거야.」","correct":true,"mis_target":"K6-2-u4-X07"},{"t":"로운 — 「세 갈래가 함께 우리말을 이루고 하는 일이 달라.」","mis":"K6-2-u4-X07"},{"t":"수아 — 「‘채소’나 ‘토마토’가 없으면 별하의 장면을 말할 수 없어.」","mis":"K6-2-u4-X02"}],"explanation":["로운과 수아는 세 갈래가 함께 쓰인다는 것을 알아요.","지안은 한자어를 나쁜 말로 여겼어요.","갈래에는 등수가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#1','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C4',2,'sa','auto','국어사전에서 낱말 뒤에 영어 같은 외국어가 함께 있으면 그 낱말은 어떤 갈래인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C4","difficulty":2,"kind":"sa","stem":"국어사전에서 낱말 뒤에 영어 같은 외국어가 함께 있으면 그 낱말은 어떤 갈래인가요? 세 글자로 쓰세요.","answer":["외래어"],"explanation":["토마토를 찾으면 뒤에 영어가 함께 있어요.","다른 나라에서 들어온 말이라는 표시예요.","그래서 외래어예요."],"mis":"K6-2-u4-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#2','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C5',2,'mc','auto','고유어의 가치 세 가지를 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X07','K6-2-u4-X06']::text[],false,'{"seq":2,"concept":"K6-2-u4-C5","difficulty":2,"kind":"mc","stem":"고유어의 가치 세 가지를 바르게 모은 것은 어느 것인가요?","options":[{"t":"뜻을 쉽게 짐작할 수 있다 · 느낌을 살려 표현할 수 있다 · 우리 문화와 정서가 담겨 있다","correct":true},{"t":"글자 수가 적다 · 외국 사람도 쉽게 안다 · 사전에 없다","mis":"K6-2-u4-X01"},{"t":"다른 갈래보다 훌륭하다 · 한자어를 이긴다 · 등수가 높다","mis":"K6-2-u4-X07"},{"t":"옛날 말이라 귀하다 · 이제는 쓰지 않는다 · 새로 만들 수 없다","mis":"K6-2-u4-X06"}],"explanation":["뜻을 짐작하기 쉬워요.","느낌을 살려 표현해요.","우리 문화와 정서를 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#3','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C5',3,'mc','auto','글쓴이가 「싱긋」과 「껄껄」을 예로 든 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X18','K6-2-u4-X07']::text[],false,'{"seq":3,"concept":"K6-2-u4-C5","difficulty":3,"kind":"mc","stem":"글쓴이가 「싱긋」과 「껄껄」을 예로 든 까닭은 어느 것인가요?","options":[{"t":"고유어가 느낌을 살려 표현할 수 있다는 것을 보여 주려고","correct":true},{"t":"고유어는 뜻을 쉽게 짐작할 수 있다는 것을 보여 주려고","mis":"K6-2-u4-X18"},{"t":"웃음은 고유어로만 말할 수 있다는 것을 보여 주려고","mis":"K6-2-u4-X07"},{"t":"두 낱말의 뜻이 같다는 것을 보여 주려고","mis":"K6-2-u4-X18"}],"explanation":["「둘째」 문단에 나온 예예요.","같은 웃음도 다른 모습을 떠올리게 해요.","느낌을 살리는 가치를 보여 줘요."],"asset":{"type":"passage","lines":["고유어는 우리말의 기본 바탕을 이룬다.","오랫동안 많은 사람이 써 온 낱말이라 살아온 모습과 느낌이 함께 담겨 있다.","첫째, 고유어는 뜻을 쉽게 짐작할 수 있다. 「마중물」은 물을 마중 나간다는 말에서 왔다.","둘째, 고유어는 느낌을 살려 표현할 수 있다.","같은 웃음이라도 「싱긋」과 「껄껄」은 다른 모습을 떠올리게 한다.","셋째, 고유어로 이루어진 표현에는 우리 문화와 정서가 담겨 있다."],"title":"고유어에는 어떤 가치가 있을까요?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#4','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',3,'mc','auto','다듬으면 좋은 말과 그대로 쓰는 말을 바르게 가른 것은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X02','K6-2-u4-X01']::text[],false,'{"seq":4,"concept":"K6-2-u4-C6","difficulty":3,"kind":"mc","stem":"다듬으면 좋은 말과 그대로 쓰는 말을 바르게 가른 것은 어느 것인가요?","options":[{"t":"다듬으면 좋은 말 — 익일 · 회람 / 그대로 쓰는 말 — 버스 · 수학","correct":true},{"t":"다듬으면 좋은 말 — 버스 · 학교 / 그대로 쓰는 말 — 익일 · 회람","mis":"K6-2-u4-X08"},{"t":"다듬으면 좋은 말 — 모든 한자어와 외래어 / 그대로 쓰는 말 — 고유어","mis":"K6-2-u4-X02"},{"t":"다듬으면 좋은 말 — 이슬 · 호미 / 그대로 쓰는 말 — 노견","mis":"K6-2-u4-X01"}],"explanation":["쉬운 우리말이 있는데도 어렵게 쓴 말은 다듬어요.","바꿀 말이 마땅치 않은 말은 그대로 써요.","익일 · 회람은 다음 날 · 돌려보기로 다듬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#5','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C4',3,'ox','auto','「수월하다」는 소리가 한자어 같으니 한자어예요.',ARRAY['K6-2-u4-X05']::text[],false,'{"seq":5,"concept":"K6-2-u4-C4","difficulty":3,"kind":"ox","stem":"「수월하다」는 소리가 한자어 같으니 한자어예요.","answer":"X","reason_options":[{"t":"국어사전에 한자 없이 한글 표기만 있는 고유어이기 때문에","correct":true},{"t":"낱말의 갈래는 소리를 듣고 짐작하면 되기 때문에","mis":"K6-2-u4-X05"}],"mis":"K6-2-u4-X05","explanation":["소리로 갈래를 정하면 틀리기 쉬워요.","사전에서 확인해요.","수월하다는 한글 표기만 있는 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#6','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',3,'match','auto','어려운 말과 쉬운 우리말로 다듬은 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C6","difficulty":3,"kind":"match","stem":"어려운 말과 쉬운 우리말로 다듬은 말을 알맞게 이으세요.","pairs":[{"l":"노견","r":"갓길"},{"l":"익일","r":"다음 날"},{"l":"회람","r":"돌려보기"},{"l":"다운로드","r":"내려받기"}],"mis":"K6-2-u4-X08","explanation":["갓길은 길의 가장자리라는 뜻이 보여요.","다음 날은 언제인지 바로 알 수 있어요.","돌려보기 · 내려받기는 하는 일이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#7','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C7',3,'error','auto','관용 표현의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":7,"concept":"K6-2-u4-C7","difficulty":3,"kind":"error","stem":"관용 표현의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「‘입이 짧다’는 입의 길이가 짧다는 뜻이야.」","correct":true,"mis_target":"K6-2-u4-X09"},{"t":"나은 — 「‘낯을 가리다’는 낯선 사람을 어려워한다는 뜻이야.」","mis":"K6-2-u4-X09"},{"t":"승우 — 「‘손이 크다’는 씀씀이가 넉넉하다는 뜻이야.」","mis":"K6-2-u4-X09"}],"explanation":["나은과 승우는 어울려 생긴 새 뜻을 말했어요.","태오는 낱말 뜻을 그대로 풀었어요.","입이 짧다는 음식을 심하게 가리거나 적게 먹는다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#8','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',4,'mc','auto','어려운 말을 쉬운 우리말로 다듬는 일의 목적으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X08','K6-2-u4-X07']::text[],false,'{"seq":8,"concept":"K6-2-u4-C6","difficulty":4,"kind":"mc","stem":"어려운 말을 쉬운 우리말로 다듬는 일의 목적으로 알맞은 것은 어느 것인가요?","options":[{"t":"누구나 알아들을 수 있게 하는 것","correct":true},{"t":"한자어와 외래어를 우리말에서 몰아내는 것","mis":"K6-2-u4-X02"},{"t":"글자 수를 줄여 빨리 쓰는 것","mis":"K6-2-u4-X08"},{"t":"고유어가 더 훌륭하다는 것을 보이는 것","mis":"K6-2-u4-X07"}],"explanation":["다듬은 말은 뜻이 바로 드러나요.","그래서 누구나 알아들을 수 있어요.","낱말을 몰아내려는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#9','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C5',4,'essay','teacher','별하의 글에서 고유어를 세 개, 고유어가 아닌 낱말을 두 개 찾아 쓰세요. 그리고 고유어가 아닌 낱말도 이 글에 꼭 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C5","difficulty":4,"kind":"essay","stem":"별하의 글에서 고유어를 세 개, 고유어가 아닌 낱말을 두 개 찾아 쓰세요. 그리고 고유어가 아닌 낱말도 이 글에 꼭 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 고유어 — 이슬 · 호미 · 두둑. 고유어가 아닌 낱말 — 채소(한자어) · 토마토(외래어). 채소와 토마토가 없으면 별하가 무엇을 보고 땄는지 그 장면을 말할 수 없다. 세 갈래가 함께 우리말을 이루고 각 갈래가 하는 일이 다르기 때문이다.","scoring_points":["고유어를 세 개 바르게 찾았는가","한자어 · 외래어를 바르게 찾았는가","세 갈래가 함께 쓰이는 까닭을 썼는가"]},"explanation":["사전 표시로 갈래를 가려요.","고유어가 아닌 말도 틀린 말이 아니에요.","갈래에는 등수가 없어요."],"asset":{"type":"passage","lines":["토요일 아침, 별하는 할머니를 따라 텃밭에 나갔다.","밤새 내린 이슬이 잎마다 맺혀 있었다.","할머니는 호미를 하나 건네주시며 두둑 사이의 풀을 뽑으라고 하셨다.","별하는 채소가 이렇게 촘촘히 심겨 있는 줄 몰랐다.","붉게 익은 토마토를 따서 바구니에 담았다.","일을 마치고 마루에 앉으니 등이 뻐근했다.","할머니가 웃으셨다. 「오늘은 네 덕에 일이 수월했구나.」"],"title":"별하가 토요일 아침에 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#10','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',4,'essay','teacher','학교 안내문에 「익일까지 회람 후 반납」이라고 적혀 있어요. 이 문장을 쉬운 우리말로 다듬어 쓰고, 그렇게 다듬은 까닭을 쓰세요. 그리고 같은 안내문의 「컴퓨터실」은 왜 그대로 두어도 되는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C6","difficulty":4,"kind":"essay","stem":"학교 안내문에 「익일까지 회람 후 반납」이라고 적혀 있어요. 이 문장을 쉬운 우리말로 다듬어 쓰고, 그렇게 다듬은 까닭을 쓰세요. 그리고 같은 안내문의 「컴퓨터실」은 왜 그대로 두어도 되는지 쓰세요.","answer_guide":{"answer":"예: 「다음 날까지 돌려본 뒤 돌려주세요.」로 다듬는다. 익일 · 회람은 쉬운 우리말이 있는데도 어렵게 쓴 말이라, 다듬으면 나이가 많은 분이나 동생들도 무엇을 언제까지 해야 하는지 바로 알 수 있다. 컴퓨터는 바꿀 말이 마땅히 없고 바꾸면 오히려 통하지 않으므로 그대로 둔다.","scoring_points":["어려운 말을 쉬운 우리말로 바르게 다듬었는가","누구나 알아듣게 하려는 까닭을 썼는가","그대로 쓰는 말의 까닭을 썼는가"]},"explanation":["뜻이 바로 보이게 다듬어요.","목적은 누구나 알아듣게 하기예요.","바꿀 말이 없는 말은 그대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#1','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C8',1,'mc','auto','고유어를 활용한 이름은 어느 것인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":1,"concept":"K6-2-u4-C8","difficulty":1,"kind":"mc","stem":"고유어를 활용한 이름은 어느 것인가요?","options":[{"t":"너른들 마을","correct":true},{"t":"그린 아파트","mis":"K6-2-u4-X10"},{"t":"제일 상가","mis":"K6-2-u4-X10"},{"t":"센트럴 공원","mis":"K6-2-u4-X10"}],"explanation":["너른들은 넓은 들이라는 고유어로 지은 이름이에요.","그린 · 센트럴은 외국어예요.","제일은 한자어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#2','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',1,'sa','auto','조사한 내용은 유형 · 사례 · 고유어 · 고유어의 ○ 네 칸으로 정리해요. ○에 알맞은 한 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C9","difficulty":1,"kind":"sa","stem":"조사한 내용은 유형 · 사례 · 고유어 · 고유어의 ○ 네 칸으로 정리해요. ○에 알맞은 한 글자를 쓰세요.","answer":["뜻"],"explanation":["유형은 동네 · 길 · 가게 · 음식 이름 가운데 하나예요.","사례와 그 속의 고유어를 적어요.","마지막 칸에는 사전에서 확인한 뜻을 적어요."],"mis":"K6-2-u4-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#3','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',1,'ox','auto','발표 자료는 화려할수록 좋아요.',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":3,"concept":"K6-2-u4-C10","difficulty":1,"kind":"ox","stem":"발표 자료는 화려할수록 좋아요.","answer":"X","reason_options":[{"t":"듣는 사람이 이해하는 데 도움이 되는 자료가 좋기 때문에","correct":true},{"t":"보기 좋은 자료가 내용보다 먼저이기 때문에","mis":"K6-2-u4-X13"}],"mis":"K6-2-u4-X13","explanation":["발표 자료는 꾸미기 대회가 아니에요.","화려하면 내용이 가려질 수 있어요.","이해에 도움이 되는 자료가 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#4','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',1,'mc','auto','이름의 뜻을 알아볼 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":4,"concept":"K6-2-u4-C9","difficulty":1,"kind":"mc","stem":"이름의 뜻을 알아볼 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"국어사전에서 찾고 어른께도 여쭈어 본다","correct":true},{"t":"글자 모양을 보고 짐작해서 정한다","mis":"K6-2-u4-X12"},{"t":"친구가 그렇다고 하면 그대로 적는다","mis":"K6-2-u4-X12"},{"t":"가장 그럴듯한 뜻을 지어 쓴다","mis":"K6-2-u4-X12"}],"explanation":["짐작한 뒤에는 반드시 확인해요.","사전 · 믿을 만한 누리집 · 어른께 여쭙기가 방법이에요.","지어 쓰면 듣는 사람이 잘못 알게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#5','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C8',2,'mc','auto','「나루터길」을 낱말로 바르게 나눈 것은 어느 것인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":5,"concept":"K6-2-u4-C8","difficulty":2,"kind":"mc","stem":"「나루터길」을 낱말로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"나루터 + 길","correct":true},{"t":"나 + 루터길","mis":"K6-2-u4-X10"},{"t":"나루 + 터길","mis":"K6-2-u4-X10"},{"t":"나눌 수 없는 한 낱말","mis":"K6-2-u4-X10"}],"explanation":["여러 낱말로 된 이름은 나누어 살펴요.","나루터는 배가 닿고 떠나는 곳이에요.","길과 이어서 나루터로 가는 길이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#6','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C8',2,'match','auto','이름 속 고유어와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C8","difficulty":2,"kind":"match","stem":"이름 속 고유어와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"너르다","r":"공간이 두루 다 넓다"},{"l":"나루터","r":"배가 닿고 떠나는 곳"},{"l":"새참","r":"일을 하다가 잠시 쉬며 먹는 음식"}],"mis":"K6-2-u4-X10","explanation":["너른들의 「너른」은 너르다에서 왔어요.","나루터는 배가 오가는 곳이에요.","새참은 일하다 쉬며 먹는 음식이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#7','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',2,'mc','auto','「우리 동네 길 이름 속 고유어」를 발표할 때 함께 보여 주면 좋은 매체는 어느 것인가요?',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":7,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"「우리 동네 길 이름 속 고유어」를 발표할 때 함께 보여 주면 좋은 매체는 어느 것인가요?","options":[{"t":"지도와 사진","correct":true},{"t":"글자만 빽빽하게 적은 종이","mis":"K6-2-u4-X13"},{"t":"아주 빠르게 넘기는 화면","mis":"K6-2-u4-X13"},{"t":"가사 없는 배경 음악","mis":"K6-2-u4-X13"}],"explanation":["길 이름은 어디에 있는지 함께 보여야 해요.","지도는 위치와 길의 흐름을 보여 줘요.","사진은 실제 모습을 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#8','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',2,'mc','auto','조사 범위로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X11']::text[],false,'{"seq":8,"concept":"K6-2-u4-C9","difficulty":2,"kind":"mc","stem":"조사 범위로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학교에서 집까지 오는 길에 있는 가게 이름","correct":true},{"t":"우리나라에 있는 모든 가게 이름","mis":"K6-2-u4-X11"},{"t":"세계 여러 나라의 음식 이름","mis":"K6-2-u4-X11"},{"t":"정하지 않고 눈에 띄는 대로","mis":"K6-2-u4-X11"}],"explanation":["범위는 손이 닿는 곳으로 정해요.","범위를 좁게 잡을수록 뜻까지 알아볼 시간이 생겨요.","너무 넓으면 확인할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#9','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',2,'ox','auto','묻고 답하는 시간까지가 발표예요.',ARRAY['K6-2-u4-X14']::text[],false,'{"seq":9,"concept":"K6-2-u4-C10","difficulty":2,"kind":"ox","stem":"묻고 답하는 시간까지가 발표예요.","answer":"O","reason_options":[{"t":"듣는 사람이 궁금한 점을 까닭과 함께 묻고 답하며 이야기가 이어지기 때문에","correct":true},{"t":"발표하는 사람이 말을 마치면 발표가 끝나기 때문에","mis":"K6-2-u4-X14"}],"mis":"K6-2-u4-X14","explanation":["듣는 사람에게도 할 일이 있어요.","궁금한 점을 까닭과 함께 물어요.","묻고 답하기까지가 발표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#10','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',3,'error','auto','조사하다가 뜻을 찾지 못한 이름이 나왔을 때 할 일을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":10,"concept":"K6-2-u4-C9","difficulty":3,"kind":"error","stem":"조사하다가 뜻을 찾지 못한 이름이 나왔을 때 할 일을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시후 — 「모르겠으면 그럴듯한 뜻을 지어서 말하면 돼.」","correct":true,"mis_target":"K6-2-u4-X12"},{"t":"하린 — 「‘아직 확인하지 못했습니다’라고 말하면 돼.」","mis":"K6-2-u4-X12"},{"t":"준서 — 「짐작한 것은 ‘짐작했습니다’라고 밝혀서 말해.」","mis":"K6-2-u4-X12"}],"explanation":["하린과 준서는 확인 · 짐작 · 모름을 갈랐어요.","시후는 모르는 것을 아는 척했어요.","지어내지 말고 아직 확인하지 못했다고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#1','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',2,'sa','auto','발표할 때는 그 내용을 어디에서 알아냈는지 밝혀요. 이것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C10","difficulty":2,"kind":"sa","stem":"발표할 때는 그 내용을 어디에서 알아냈는지 밝혀요. 이것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["출처"],"explanation":["사전인지, 누리집인지, 어른께 여쭌 것인지 말해요.","듣는 사람이 확인할 수 있어요.","그것을 출처라고 해요."],"mis":"K6-2-u4-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#2','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',2,'mc','auto','조사한 이름 여러 개를 한눈에 견주어 보여 주려면 어떤 매체가 알맞나요?',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":2,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"조사한 이름 여러 개를 한눈에 견주어 보여 주려면 어떤 매체가 알맞나요?","options":[{"t":"표","correct":true},{"t":"지도","mis":"K6-2-u4-X13"},{"t":"사진 한 장","mis":"K6-2-u4-X13"},{"t":"소리 내어 읽기만 하기","mis":"K6-2-u4-X13"}],"explanation":["지도는 위치를 보여 줘요.","사진은 실제 모습을 보여 줘요.","여러 사례를 견줄 때는 표가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#3','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C8',3,'mc','auto','「봄뜰 도서관」에서 찾을 수 있는 고유어를 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X10']::text[],false,'{"seq":3,"concept":"K6-2-u4-C8","difficulty":3,"kind":"mc","stem":"「봄뜰 도서관」에서 찾을 수 있는 고유어를 바르게 모은 것은 어느 것인가요?","options":[{"t":"봄 · 뜰","correct":true},{"t":"도서관","mis":"K6-2-u4-X01"},{"t":"봄뜰 도서관 전체","mis":"K6-2-u4-X10"},{"t":"고유어가 없다","mis":"K6-2-u4-X10"}],"explanation":["이름을 낱말로 나누어요 — 봄 · 뜰 · 도서관.","봄과 뜰은 고유어예요.","도서관은 한자어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#4','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C9',3,'mc','auto','짐작한 것을 짐작했다고 바르게 밝힌 말은 어느 것인가요?',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":4,"concept":"K6-2-u4-C9","difficulty":3,"kind":"mc","stem":"짐작한 것을 짐작했다고 바르게 밝힌 말은 어느 것인가요?","options":[{"t":"「‘모퉁이 빵집’은 길이 꺾이는 자리에 있어서 붙인 이름이 아닐까 짐작했습니다.」","correct":true},{"t":"「‘모퉁이 빵집’은 주인이 모퉁이를 좋아해서 지은 이름입니다.」","mis":"K6-2-u4-X12"},{"t":"「잘 모르지만 아마 맞을 겁니다.」","mis":"K6-2-u4-X12"},{"t":"「친구가 알려 준 뜻을 사전에서 찾은 뜻이라고 적었습니다.」","mis":"K6-2-u4-X12"}],"explanation":["짐작은 짐작이라고 밝혀요.","확인하지 않은 것을 사실처럼 말하지 않아요.","친구 말을 사전 뜻이라고 옮기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#5','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',3,'ox','auto','발표할 매체를 먼저 정하고 그다음에 알릴 내용을 끼워 맞추어요.',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":5,"concept":"K6-2-u4-C10","difficulty":3,"kind":"ox","stem":"발표할 매체를 먼저 정하고 그다음에 알릴 내용을 끼워 맞추어요.","answer":"X","reason_options":[{"t":"알릴 내용을 정한 뒤 그 내용에 맞는 매체를 고르기 때문에","correct":true},{"t":"멋진 매체가 정해져야 내용이 살아나기 때문에","mis":"K6-2-u4-X13"}],"mis":"K6-2-u4-X13","explanation":["내용이 먼저예요.","그 내용을 잘 보여 줄 매체를 골라요.","매체에 내용을 끼워 맞추지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#6','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',3,'match','auto','매체와 그 매체가 알맞은 때를 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C10","difficulty":3,"kind":"match","stem":"매체와 그 매체가 알맞은 때를 이으세요.","pairs":[{"l":"사진 · 그림","r":"실제 모습을 보여 줄 때"},{"l":"지도","r":"위치나 길의 흐름을 보여 줄 때"},{"l":"표","r":"여러 사례를 한눈에 견줄 때"},{"l":"종이 자료","r":"차례대로 자세히 설명할 때"}],"mis":"K6-2-u4-X13","explanation":["사진은 모습, 지도는 위치예요.","표는 견주기예요.","종이 자료는 차례대로 자세히 설명할 때 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#7','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',3,'error','auto','발표 전에 점검할 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X12']::text[],false,'{"seq":7,"concept":"K6-2-u4-C10","difficulty":3,"kind":"error","stem":"발표 전에 점검할 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"유나 — 「우리 모둠 자료가 가장 화려한지 살펴보자.」","correct":true,"mis_target":"K6-2-u4-X13"},{"t":"도하 — 「조사한 자료의 출처가 믿을 만한지 살펴보자.」","mis":"K6-2-u4-X12"},{"t":"은재 — 「자료의 양이 발표 시간에 알맞은지 살펴보자.」","mis":"K6-2-u4-X13"}],"explanation":["출처 · 양 · 매체가 점검할 세 가지예요.","도하와 은재는 그것을 살폈어요.","유나는 꾸밈을 기준으로 삼았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#8','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',4,'mc','auto','「너른들 마을」 발표를 듣고 한 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X14']::text[],false,'{"seq":8,"concept":"K6-2-u4-C10","difficulty":4,"kind":"mc","stem":"「너른들 마을」 발표를 듣고 한 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「‘너른들’이 넓은 들이라는 뜻이라면 지금 그 마을에도 들이 남아 있는지 궁금해요. 이름이 지금 모습과 맞는지 알고 싶어서요.」","correct":true},{"t":"「그냥 궁금해요.」","mis":"K6-2-u4-X14"},{"t":"「우리 모둠이 더 잘했지요?」","mis":"K6-2-u4-X14"},{"t":"「발표가 왜 이렇게 길어요?」","mis":"K6-2-u4-X14"}],"explanation":["발표 내용을 정리하며 들어요.","궁금한 점을 까닭과 함께 물어요.","그래야 이야기가 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#9','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C9',4,'essay','teacher','우리 동네에서 고유어를 활용한 이름을 하나 조사하려고 해요. 조사 대상 · 범위 · 방법을 정해 쓰고, 조사한 내용을 정리할 네 칸에 무엇을 적을지 쓰세요. 뜻을 확인하지 못하면 어떻게 말할지도 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C9","difficulty":4,"kind":"essay","stem":"우리 동네에서 고유어를 활용한 이름을 하나 조사하려고 해요. 조사 대상 · 범위 · 방법을 정해 쓰고, 조사한 내용을 정리할 네 칸에 무엇을 적을지 쓰세요. 뜻을 확인하지 못하면 어떻게 말할지도 쓰세요.","answer_guide":{"answer":"예: 조사 대상 — 가게 이름. 범위 — 학교에서 집까지 오는 길. 방법 — 국어사전에서 찾고 동네 어른께 여쭙기. 네 칸 — 유형(가게 이름) · 사례(실제 가게 이름) · 고유어(이름 속 고유어) · 고유어의 뜻(사전에서 확인한 뜻). 뜻을 찾지 못하면 지어내지 않고 「아직 확인하지 못했습니다」라고 말하고, 짐작한 것은 짐작했다고 밝힌다.","scoring_points":["대상 · 범위 · 방법을 알맞게 정했는가","네 칸을 바르게 썼는가","확인 · 짐작 · 모름을 가르는 방법을 썼는가"]},"explanation":["범위는 손이 닿는 곳으로.","네 칸으로 정리해요.","모르는 것은 모른다고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#10','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',4,'essay','teacher','「우리 동네 가게 이름 속 고유어」를 발표하려고 해요. 어떤 매체를 쓸지와 그 까닭을 쓰고, 발표 전에 점검할 세 가지와 듣는 사람이 할 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C10","difficulty":4,"kind":"essay","stem":"「우리 동네 가게 이름 속 고유어」를 발표하려고 해요. 어떤 매체를 쓸지와 그 까닭을 쓰고, 발표 전에 점검할 세 가지와 듣는 사람이 할 일을 쓰세요.","answer_guide":{"answer":"예: 가게 이름 여러 개를 한눈에 견주도록 표를 쓰고, 가게의 실제 모습을 보여 주려고 사진을 함께 쓴다. 발표 전에 조사한 자료의 출처가 믿을 만한지, 자료의 양이 발표 시간에 알맞은지, 고른 매체가 발표에 도움이 되는지 점검한다. 듣는 사람은 발표 내용을 정리하며 듣고, 궁금한 점을 까닭과 함께 묻는다.","scoring_points":["알릴 내용에 맞는 매체와 까닭을 썼는가","점검할 세 가지를 썼는가","듣는 사람의 할 일을 썼는가"]},"explanation":["내용에 맞는 매체를 골라요.","출처 · 양 · 매체를 점검해요.","듣는 사람도 정리하고 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#1','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C13',1,'mc','auto','「표준어」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X06']::text[],false,'{"seq":1,"concept":"K6-2-u4-C13","difficulty":1,"kind":"mc","stem":"「표준어」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"온 나라 사람이 두루 통하게 쓰도록 정한 말","correct":true},{"t":"어느 고장에서 주로 쓰는 말","mis":"K6-2-u4-X19"},{"t":"옛날에만 쓰던 말","mis":"K6-2-u4-X06"},{"t":"서울 사람만 쓰는 말","mis":"K6-2-u4-X19"}],"explanation":["표준어는 온 나라 사람이 함께 쓰도록 정한 말이에요.","책 · 방송 · 공공 안내에 주로 쓰여요.","고장에서 주로 쓰는 말은 방언이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#2','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C13',1,'sa','auto','어느 고장에서 주로 쓰는, 표준어가 아닌 말을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C13","difficulty":1,"kind":"sa","stem":"어느 고장에서 주로 쓰는, 표준어가 아닌 말을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["방언"],"explanation":["표준어는 두루 통하게 정한 말이에요.","고장에서 주로 쓰는 말이 따로 있어요.","그 말을 방언이라고 해요."],"mis":"K6-2-u4-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#3','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C13',1,'ox','auto','방언은 고쳐야 할 틀린 말이에요.',ARRAY['K6-2-u4-X19']::text[],false,'{"seq":3,"concept":"K6-2-u4-C13","difficulty":1,"kind":"ox","stem":"방언은 고쳐야 할 틀린 말이에요.","answer":"X","reason_options":[{"t":"그 고장의 정과 역사를 담은 소중한 우리말이고 쓰이는 자리가 다를 뿐이기 때문에","correct":true},{"t":"표준어만 진짜 우리말이기 때문에","mis":"K6-2-u4-X19"}],"mis":"K6-2-u4-X19","explanation":["방언도 우리말이에요.","표준어와 쓰이는 자리가 다를 뿐이에요.","둘 사이에 등수는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#4','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C12',1,'mc','auto','「추론」에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17']::text[],false,'{"seq":4,"concept":"K6-2-u4-C12","difficulty":1,"kind":"mc","stem":"「추론」에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"글에 적히지 않은 부분을 글의 단서와 내 경험 · 지식으로 메우는 일","correct":true},{"t":"글에 없는 일을 마음대로 상상하는 일","mis":"K6-2-u4-X16"},{"t":"글에 적힌 것을 그대로 옮겨 적는 일","mis":"K6-2-u4-X17"},{"t":"까닭 없이 그럴 것 같다고 말하는 일","mis":"K6-2-u4-X16"}],"explanation":["글쓴이는 모든 것을 다 적지 않아요.","적히지 않은 부분을 단서로 메워요.","까닭은 반드시 글 안에 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#5','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C12',2,'mc','auto','할머니가 말한 「건사하다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X18']::text[],false,'{"seq":5,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"할머니가 말한 「건사하다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"물건을 잘 거두어 보호함","correct":true},{"t":"필요 없는 것을 골라 버림","mis":"K6-2-u4-X18"},{"t":"여러 사람에게 널리 알림","mis":"K6-2-u4-X18"},{"t":"새것으로 바꾸어 놓음","mis":"K6-2-u4-X18"}],"explanation":["「잘 건사해 두었으니 이만큼 남았지」라고 했어요.","오래된 공책이 남아 있었어요.","그러니 잘 거두어 보호했다는 뜻이에요."],"asset":{"type":"passage","lines":["「겨울마다 회관에 모여 앉아 한 사람이 한 낱말씩 적었단다.","같은 물건을 두고도 집집이 부르는 말이 달라서, 그때마다 둘 다 적어 두었지.」","「이 이름들은요?」 「그 말을 알려 준 사람이지.」","할머니는 「회관 아래 칸에 잘 건사해 두었으니 이만큼 남았지.」라고 덧붙이셨다.","「그런데 요즘은 이 말들을 쓰는 사람이 많이 줄었어.","젊은 사람들이 도시로 나가면서 말도 같이 나갔거든.」","할머니는 공책 뒤쪽 빈 장을 손바닥으로 가만히 쓸어 보이셨다.","그러고는 윤겸이를 한 번 바라보셨다."],"title":"마을 회관의 낡은 공책 (뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#6','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C12',2,'mc','auto','글에 그대로 적혀 있는 것은 어느 것인가요?',ARRAY['K6-2-u4-X17']::text[],false,'{"seq":6,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"글에 그대로 적혀 있는 것은 어느 것인가요?","options":[{"t":"공책 뒤쪽에는 아직 적히지 않은 장이 남아 있다","correct":true},{"t":"공책은 학교 숙제로 만든 것이다","mis":"K6-2-u4-X17"},{"t":"마을에서는 지금도 해마다 낱말을 적는다","mis":"K6-2-u4-X17"},{"t":"윤겸이는 공책을 이어 적기로 마음먹었다","mis":"K6-2-u4-X17"}],"explanation":["글에 적힌 것부터 정확히 붙잡아요.","빈 장이 남아 있었다는 것은 글에 있어요.","나머지는 글에 없는 내용이에요."],"asset":{"type":"passage","lines":["방학 동안 할머니 댁에 머물던 윤겸이는 마을 회관 책꽂이 맨 아래 칸에서","표지가 다 닳은 공책 한 권을 찾아냈다. 겉장에는 「우리 마을 말」이라고 적혀 있었다.","펼쳐 보니 낱말과 뜻이 줄줄이 적혀 있었다. 글씨체가 몇 가지나 되었다.","어떤 낱말 옆에는 이름과 날짜가 나란히 적혀 있었고,","어떤 낱말에는 두 가지 뜻이 나란히 적혀 있었다.","마지막 장을 펴 보니, 뒤쪽 여러 장이 아무것도 적히지 않은 채 남아 있었다."],"title":"마을 회관의 낡은 공책 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#7','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C13',2,'match','auto','표준어와 같은 뜻으로 쓰이는 고장 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u4-C13","difficulty":2,"kind":"match","stem":"표준어와 같은 뜻으로 쓰이는 고장 말을 알맞게 이으세요.","pairs":[{"l":"부엌","r":"정지"},{"l":"무","r":"무시"},{"l":"김치","r":"짐치"}],"mis":"K6-2-u4-X19","explanation":["같은 것을 다르게 부를 뿐이에요.","소리가 비슷하게 남은 말도 있어요.","둘 다 소중한 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#8','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C11',2,'mc','auto','우리말을 마음껏 쓰지 못하던 때에 어떤 노력이 있었나요?',ARRAY['K6-2-u4-X19','K6-2-u4-X15']::text[],false,'{"seq":8,"concept":"K6-2-u4-C11","difficulty":2,"kind":"mc","stem":"우리말을 마음껏 쓰지 못하던 때에 어떤 노력이 있었나요?","options":[{"t":"흩어진 낱말을 모아 우리말 사전을 만들려고 애썼다","correct":true},{"t":"표준어만 남기고 고장 말은 모두 지웠다","mis":"K6-2-u4-X19"},{"t":"외국어로 된 사전을 만들었다","mis":"K6-2-u4-X15"},{"t":"말은 저절로 남으니 아무것도 하지 않았다","mis":"K6-2-u4-X15"}],"explanation":["온 나라의 낱말을 모아 적었어요.","고장마다 다른 말도 함께 모았어요.","그 기록이 오늘 국어사전의 바탕이 되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#9','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C12',2,'ox','auto','추론한 내용은 사람마다 조금씩 다를 수 있어요.',ARRAY['K6-2-u4-X16']::text[],false,'{"seq":9,"concept":"K6-2-u4-C12","difficulty":2,"kind":"ox","stem":"추론한 내용은 사람마다 조금씩 다를 수 있어요.","answer":"O","reason_options":[{"t":"까닭이 글 안에 있다면 단서를 읽는 눈이 조금씩 다를 수 있기 때문에","correct":true},{"t":"추론은 아무렇게나 상상해도 되기 때문에","mis":"K6-2-u4-X16"}],"mis":"K6-2-u4-X16","explanation":["추론은 사람마다 조금씩 다를 수 있어요.","다만 까닭은 글 안에 있어야 해요.","다르면 서로 까닭을 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#10','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C13',3,'error','auto','표준어와 방언에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X20']::text[],false,'{"seq":10,"concept":"K6-2-u4-C13","difficulty":3,"kind":"error","stem":"표준어와 방언에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민재 — 「할머니가 ‘정지’라고 하시면 ‘부엌’이라고 고쳐 드려야 해.」","correct":true,"mis_target":"K6-2-u4-X19"},{"t":"소율 — 「발표처럼 공식적인 자리에서는 표준어로 말해.」","mis":"K6-2-u4-X20"},{"t":"지오 — 「고장 말을 찾을 때는 어느 고장 말인지도 함께 살펴봐.」","mis":"K6-2-u4-X19"}],"explanation":["소율과 지오는 상황과 고장을 살폈어요.","민재는 방언을 고쳐야 할 말로 여겼어요.","고장 사람과는 고장 말로 이야기해도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#1','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',2,'sa','auto','추론할 때 인물의 말과 행동, 일이 일어난 때와 곳처럼 글에서 찾는 실마리를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C12","difficulty":2,"kind":"sa","stem":"추론할 때 인물의 말과 행동, 일이 일어난 때와 곳처럼 글에서 찾는 실마리를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["단서"],"explanation":["추론은 글에서 실마리를 찾는 데서 시작해요.","인물의 말과 행동, 때와 곳이 실마리예요.","그 실마리를 단서라고 해요."],"mis":"K6-2-u4-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#2','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C13',2,'mc','auto','표준어가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X20']::text[],false,'{"seq":2,"concept":"K6-2-u4-C13","difficulty":2,"kind":"mc","stem":"표준어가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"사는 곳이 달라도 서로 통하게 해 준다","correct":true},{"t":"그 고장의 정과 역사를 담아 전한다","mis":"K6-2-u4-X19"},{"t":"고장 말을 없애 준다","mis":"K6-2-u4-X19"},{"t":"어디에서나 한 가지 말만 쓰게 한다","mis":"K6-2-u4-X20"}],"explanation":["표준어는 두루 통하게 해 줘요.","고장의 정과 역사를 담는 것은 방언이에요.","둘은 하는 일이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#3','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',3,'mc','auto','할머니가 공책 뒤쪽 빈 장을 쓸어 보이신 까닭을 추론한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X16']::text[],false,'{"seq":3,"concept":"K6-2-u4-C12","difficulty":3,"kind":"mc","stem":"할머니가 공책 뒤쪽 빈 장을 쓸어 보이신 까닭을 추론한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"윤겸이가 이어서 적어 주기를 바라셨을 것이다","correct":true},{"t":"공책에 쌓인 먼지를 털어 내려 하셨을 것이다","mis":"K6-2-u4-X16"},{"t":"남은 장을 뜯어 내려고 세어 보셨을 것이다","mis":"K6-2-u4-X16"},{"t":"공책을 버리려고 마지막으로 보셨을 것이다","mis":"K6-2-u4-X16"}],"explanation":["앞에서 쓰는 사람이 줄었다고 하셨어요.","빈 장을 쓸어 보이신 뒤 윤겸이를 바라보셨어요.","말과 행동과 시선이 같은 곳을 가리켜요."],"asset":{"type":"passage","lines":["「겨울마다 회관에 모여 앉아 한 사람이 한 낱말씩 적었단다.","같은 물건을 두고도 집집이 부르는 말이 달라서, 그때마다 둘 다 적어 두었지.」","「이 이름들은요?」 「그 말을 알려 준 사람이지.」","할머니는 「회관 아래 칸에 잘 건사해 두었으니 이만큼 남았지.」라고 덧붙이셨다.","「그런데 요즘은 이 말들을 쓰는 사람이 많이 줄었어.","젊은 사람들이 도시로 나가면서 말도 같이 나갔거든.」","할머니는 공책 뒤쪽 빈 장을 손바닥으로 가만히 쓸어 보이셨다.","그러고는 윤겸이를 한 번 바라보셨다."],"title":"마을 회관의 낡은 공책 (뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#4','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',3,'mc','auto','「글씨체가 몇 가지나 되었다」를 단서로 추론할 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17']::text[],false,'{"seq":4,"concept":"K6-2-u4-C12","difficulty":3,"kind":"mc","stem":"「글씨체가 몇 가지나 되었다」를 단서로 추론할 수 있는 것은 어느 것인가요?","options":[{"t":"여러 사람이 함께 적었을 것이다","correct":true},{"t":"공책을 산 가게가 여러 곳이었을 것이다","mis":"K6-2-u4-X16"},{"t":"글씨를 잘 쓰는 사람이 없었을 것이다","mis":"K6-2-u4-X16"},{"t":"공책이 아주 새것일 것이다","mis":"K6-2-u4-X17"}],"explanation":["글씨체가 여럿이면 쓴 사람이 여럿이에요.","뒷부분에서 한 사람이 한 낱말씩 적었다고 해요.","단서와 추론이 맞아떨어져요."],"asset":{"type":"passage","lines":["방학 동안 할머니 댁에 머물던 윤겸이는 마을 회관 책꽂이 맨 아래 칸에서","표지가 다 닳은 공책 한 권을 찾아냈다. 겉장에는 「우리 마을 말」이라고 적혀 있었다.","펼쳐 보니 낱말과 뜻이 줄줄이 적혀 있었다. 글씨체가 몇 가지나 되었다.","어떤 낱말 옆에는 이름과 날짜가 나란히 적혀 있었고,","어떤 낱말에는 두 가지 뜻이 나란히 적혀 있었다.","마지막 장을 펴 보니, 뒤쪽 여러 장이 아무것도 적히지 않은 채 남아 있었다."],"title":"마을 회관의 낡은 공책 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#5','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C11',3,'ox','auto','말은 쓰는 사람이 있으면 저절로 남으니 적어 둘 필요가 없어요.',ARRAY['K6-2-u4-X15']::text[],false,'{"seq":5,"concept":"K6-2-u4-C11","difficulty":3,"kind":"ox","stem":"말은 쓰는 사람이 있으면 저절로 남으니 적어 둘 필요가 없어요.","answer":"X","reason_options":[{"t":"쓰는 사람이 줄면 사라질 수 있어 누군가 적어 두고 이어 주어야 남기 때문에","correct":true},{"t":"말은 한번 생기면 사라지지 않기 때문에","mis":"K6-2-u4-X15"}],"mis":"K6-2-u4-X15","explanation":["말은 저절로 남지 않아요.","쓰는 사람이 줄면 사라질 수 있어요.","적어 두고 이어 준 덕분에 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#6','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',3,'match','auto','글에서 찾은 단서와 추론한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C12","difficulty":3,"kind":"match","stem":"글에서 찾은 단서와 추론한 내용을 알맞게 이으세요.","pairs":[{"l":"글씨체가 여러 가지다","r":"여러 사람이 함께 적었다"},{"l":"한 낱말에 두 가지 뜻이 나란히 적혀 있다","r":"집집이 다르게 쓰는 말을 있는 그대로 남겼다"},{"l":"쓰는 사람이 많이 줄었다고 하셨다","r":"적어 두지 않으면 사라질 수도 있었다"}],"mis":"K6-2-u4-X16","explanation":["단서마다 알 수 있는 것이 달라요.","그 단서 하나로 알 수 있는 것을 골라요.","까닭은 늘 글 안에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#7','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',3,'error','auto','「마을 회관의 낡은 공책」을 읽고 추론했어요. 알맞지 않게 추론한 친구는 누구인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17']::text[],false,'{"seq":7,"concept":"K6-2-u4-C12","difficulty":3,"kind":"error","stem":"「마을 회관의 낡은 공책」을 읽고 추론했어요. 알맞지 않게 추론한 친구는 누구인가요?","options":[{"t":"라희 — 「할머니는 공책이 싫어서 빈 장을 쓸어 보셨을 거야. 그냥 그럴 것 같아.」","correct":true,"mis_target":"K6-2-u4-X16"},{"t":"건우 — 「쓰는 사람이 줄었다는 말 뒤에 윤겸이를 바라보셨으니 이어 적기를 바라셨을 거야.」","mis":"K6-2-u4-X16"},{"t":"다은 — 「이름 옆에 날짜가 있으니 알려 준 사람과 때를 남겼을 거야.」","mis":"K6-2-u4-X17"}],"explanation":["건우와 다은은 글에서 단서를 찾았어요.","라희는 까닭을 글에서 찾지 않았어요.","추론은 마음대로 지어내는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#8','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C13',4,'mc','auto','우리말을 상황에 맞게 쓴 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X20','K6-2-u4-X19']::text[],false,'{"seq":8,"concept":"K6-2-u4-C13","difficulty":4,"kind":"mc","stem":"우리말을 상황에 맞게 쓴 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학급 회의 사회를 볼 때는 표준어로, 할머니 댁 이웃 어른들과 이야기할 때는 그 고장 말로 이야기한다","correct":true},{"t":"어디에서든 표준어만 쓴다","mis":"K6-2-u4-X20"},{"t":"어디에서든 고장 말만 쓴다","mis":"K6-2-u4-X20"},{"t":"고장 말을 쓰는 친구를 따라 하며 웃는다","mis":"K6-2-u4-X19"}],"explanation":["공식적인 자리에서는 표준어로 말해요.","고장 사람과는 고장 말로 정답게 말해요.","자리에 맞게 골라 쓰는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#9','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',4,'essay','teacher','할머니가 공책 뒤쪽 빈 장을 쓸어 보이고 윤겸이를 바라보신 까닭을 추론해 쓰세요. 그렇게 추론한 단서를 글에서 두 가지 찾아 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C12","difficulty":4,"kind":"essay","stem":"할머니가 공책 뒤쪽 빈 장을 쓸어 보이고 윤겸이를 바라보신 까닭을 추론해 쓰세요. 그렇게 추론한 단서를 글에서 두 가지 찾아 쓰세요.","answer_guide":{"answer":"예: 할머니는 윤겸이가 마을 말을 이어서 적어 주기를 바라셨을 것이다. 단서 — 할머니가 요즘은 이 말들을 쓰는 사람이 많이 줄었다고 하셨다. 공책 뒤쪽 빈 장을 쓸어 보이신 뒤 윤겸이를 바라보셨다. 쓰는 사람이 줄어 사라질 수 있는 말을 빈 장에 이어 적어 주기를 바라신 것이다.","scoring_points":["할머니의 마음을 알맞게 추론했는가","글에서 단서를 두 가지 찾았는가","단서와 추론을 이어 설명했는가"]},"explanation":["말 · 행동 · 시선을 이어 봐요.","까닭은 글 안에서 찾아요.","적힌 것과 메운 생각을 갈라 써요."],"asset":{"type":"passage","lines":["「겨울마다 회관에 모여 앉아 한 사람이 한 낱말씩 적었단다.","같은 물건을 두고도 집집이 부르는 말이 달라서, 그때마다 둘 다 적어 두었지.」","「이 이름들은요?」 「그 말을 알려 준 사람이지.」","할머니는 「회관 아래 칸에 잘 건사해 두었으니 이만큼 남았지.」라고 덧붙이셨다.","「그런데 요즘은 이 말들을 쓰는 사람이 많이 줄었어.","젊은 사람들이 도시로 나가면서 말도 같이 나갔거든.」","할머니는 공책 뒤쪽 빈 장을 손바닥으로 가만히 쓸어 보이셨다.","그러고는 윤겸이를 한 번 바라보셨다."],"title":"마을 회관의 낡은 공책 (뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#10','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C13',4,'essay','teacher','표준어와 방언이 각각 하는 일을 쓰고, 방언이 고쳐야 할 틀린 말이 아닌 까닭을 쓰세요. 그리고 우리말을 지키기 위해 내가 할 수 있는 일을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C13","difficulty":4,"kind":"essay","stem":"표준어와 방언이 각각 하는 일을 쓰고, 방언이 고쳐야 할 틀린 말이 아닌 까닭을 쓰세요. 그리고 우리말을 지키기 위해 내가 할 수 있는 일을 두 가지 쓰세요.","answer_guide":{"answer":"예: 표준어는 사는 곳이 달라도 서로 통하게 해 주고, 방언은 그 고장의 정과 역사를 담아 전해 준다. 방언은 쓰이는 자리가 다를 뿐 표준어처럼 소중한 우리말이므로 틀린 말이 아니다. 내가 할 수 있는 일 — 할머니께 고장 말을 여쭈어 적어 두기, 다른 고장의 말을 웃음거리로 삼지 않기.","scoring_points":["표준어와 방언이 하는 일을 각각 썼는가","방언이 틀린 말이 아닌 까닭을 썼는가","실천할 수 있는 일을 두 가지 썼는가"]},"explanation":["표준어는 두루 통하게, 방언은 정과 역사를.","둘 사이에 등수는 없어요.","여쭈어 적기, 웃음거리로 삼지 않기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#1','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',1,'mc','auto','언어생활 점검표를 만드는 목적은 무엇인가요?',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":1,"concept":"K6-2-u4-C14","difficulty":1,"kind":"mc","stem":"언어생활 점검표를 만드는 목적은 무엇인가요?","options":[{"t":"우리 반의 말버릇을 살펴 함께 고치려고","correct":true},{"t":"말을 가장 바르게 쓰는 사람을 뽑으려고","mis":"K6-2-u4-X21"},{"t":"말을 함부로 쓰는 친구를 가려내려고","mis":"K6-2-u4-X21"},{"t":"누가 더 많이 썼는지 세어 견주려고","mis":"K6-2-u4-X21"}],"explanation":["점검은 고치기 위한 것이에요.","누구를 뽑거나 가려내려는 것이 아니에요.","우리 반이 함께 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#2','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',1,'sa','auto','실천 다짐문에서 무엇을 위해 다짐하는지 밝히는 부분을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C15","difficulty":1,"kind":"sa","stem":"실천 다짐문에서 무엇을 위해 다짐하는지 밝히는 부분을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["목적"],"explanation":["다짐문에는 네 부분이 들어가요.","맨 앞에서 무엇을 위해 다짐하는지 밝혀요.","그 부분이 목적이에요."],"mis":"K6-2-u4-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#3','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',1,'ox','auto','언어생활을 점검할 때는 먼저 내가 쓴 말부터 적어요.',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":3,"concept":"K6-2-u4-C14","difficulty":1,"kind":"ox","stem":"언어생활을 점검할 때는 먼저 내가 쓴 말부터 적어요.","answer":"O","reason_options":[{"t":"점검은 친구를 흠잡는 일이 아니라 우리 반이 함께 고치려는 일이기 때문에","correct":true},{"t":"내가 쓴 말이 가장 바르기 때문에","mis":"K6-2-u4-X21"}],"mis":"K6-2-u4-X21","explanation":["점검은 흠잡기가 아니에요.","먼저 내가 쓴 말부터 적어요.","고칠 점은 우리 반의 일로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#4','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',1,'mc','auto','지킬 수 있는 다짐으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X23']::text[],false,'{"seq":4,"concept":"K6-2-u4-C15","difficulty":1,"kind":"mc","stem":"지킬 수 있는 다짐으로 알맞은 것은 어느 것인가요?","options":[{"t":"모둠 활동에서 친구가 못 알아듣는 말을 쓰면 바로 풀어 말하겠습니다","correct":true},{"t":"앞으로 우리말을 아주 열심히 사랑하겠습니다","mis":"K6-2-u4-X23"},{"t":"오늘부터 한자어와 외래어를 하나도 쓰지 않겠습니다","mis":"K6-2-u4-X23"},{"t":"다들 바른 말을 쓰도록 합시다","mis":"K6-2-u4-X23"}],"explanation":["언제 무엇을 할지 드러나야 지킬 수 있어요.","「열심히」는 무엇을 할지 없어요.","「하나도」는 지킬 수 없는 크기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#5','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',2,'mc','auto','알림장 · 안내문처럼 여러 사람에게 전하는 글을 쉬운 우리말로 써야 하는 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X02','K6-2-u4-X03']::text[],false,'{"seq":5,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"알림장 · 안내문처럼 여러 사람에게 전하는 글을 쉬운 우리말로 써야 하는 까닭은 어느 것인가요?","options":[{"t":"나이가 많은 분, 우리말을 배우는 중인 분까지 모두 읽는 글이라서","correct":true},{"t":"짧게 써야 종이를 아낄 수 있어서","mis":"K6-2-u4-X08"},{"t":"외국어는 모두 틀린 말이라서","mis":"K6-2-u4-X02"},{"t":"어려운 말을 쓰면 글쓴이가 혼나서","mis":"K6-2-u4-X03"}],"explanation":["여러 사람에게 전하는 글은 누구나 읽어요.","누구나 알아들을 수 있어야 해요.","그래서 쉬운 우리말로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#6','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',2,'match','auto','실천 다짐문의 부분과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C15","difficulty":2,"kind":"match","stem":"실천 다짐문의 부분과 하는 일을 알맞게 이으세요.","pairs":[{"l":"목적","r":"무엇을 위해 다짐하는지 밝혀 준다"},{"l":"구체적인 실천 약속","r":"언제 · 어디에서 · 무엇을 할지 알려 준다"},{"l":"전하고 싶은 말","r":"함께 하자고 부탁한다"},{"l":"날짜와 쓴 사람","r":"누가 언제 한 약속인지 남겨 준다"}],"mis":"K6-2-u4-X22","explanation":["목적은 왜, 실천 약속은 무엇을이에요.","전하고 싶은 말은 함께 하자는 부탁이에요.","날짜와 쓴 사람은 마지막에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#7','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',2,'mc','auto','안내문의 말이 통하지 않을 때 실제로 생기는 일은 어느 것인가요?',ARRAY['K6-2-u4-X04','K6-2-u4-X03']::text[],false,'{"seq":7,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"안내문의 말이 통하지 않을 때 실제로 생기는 일은 어느 것인가요?","options":[{"t":"필요한 도움을 받지 못하고 지나친다","correct":true},{"t":"글을 읽는 속도가 빨라진다","mis":"K6-2-u4-X04"},{"t":"낱말의 뜻이 저절로 바뀐다","mis":"K6-2-u4-X04"},{"t":"모두 그 말을 금방 배우게 된다","mis":"K6-2-u4-X03"}],"explanation":["안내문을 읽고도 무엇을 할지 몰라요.","되묻기를 부끄러워할 수도 있어요.","그래서 필요한 도움을 놓쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#8','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',2,'mc','auto','다인이의 다짐문에 빠진 부분은 어느 것인가요?',ARRAY['K6-2-u4-X22']::text[],false,'{"seq":8,"concept":"K6-2-u4-C15","difficulty":2,"kind":"mc","stem":"다인이의 다짐문에 빠진 부분은 어느 것인가요?","options":[{"t":"날짜와 쓴 사람","correct":true},{"t":"목적","mis":"K6-2-u4-X22"},{"t":"구체적인 실천 약속","mis":"K6-2-u4-X22"},{"t":"전하고 싶은 말","mis":"K6-2-u4-X22"}],"explanation":["둘째 줄에 목적이 있어요.","「하나,」 세 줄이 실천 약속, 마지막 줄이 전하고 싶은 말이에요.","누가 언제 쓴 약속인지가 빠졌어요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","나는 우리말을 아끼고 바르게 쓰기 위해 다음과 같이 다짐합니다.","하나, 모둠 활동에서 친구가 알아듣지 못하는 말을 쓰면 바로 풀어서 다시 말하겠습니다.","하나, 알림장을 쓸 때 쉬운 우리말로 바꿀 수 있는 말은 바꾸어 쓰겠습니다.","하나, 다른 고장의 말을 웃음거리로 삼지 않겠습니다.","친구들도 모르는 말은 되묻고, 어려운 말은 풀어 말해 주세요."],"title":"다인이가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#9','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',2,'ox','auto','「다들 줄인 말을 쓰지 맙시다」는 좋은 실천 약속이에요.',ARRAY['K6-2-u4-X23']::text[],false,'{"seq":9,"concept":"K6-2-u4-C15","difficulty":2,"kind":"ox","stem":"「다들 줄인 말을 쓰지 맙시다」는 좋은 실천 약속이에요.","answer":"X","reason_options":[{"t":"내가 할 일이 드러나지 않아 지키는 사람이 없기 때문에","correct":true},{"t":"여러 사람에게 하는 약속일수록 잘 지켜지기 때문에","mis":"K6-2-u4-X23"}],"mis":"K6-2-u4-X23","explanation":["실천 약속은 내가 할 일이어야 해요.","「다들」에는 내가 할 일이 없어요.","「나는 ~하겠습니다」로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#10','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',3,'error','auto','친구의 다짐문을 읽고 고칠 점을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X24','K6-2-u4-X23','K6-2-u4-X22']::text[],false,'{"seq":10,"concept":"K6-2-u4-C15","difficulty":3,"kind":"error","stem":"친구의 다짐문을 읽고 고칠 점을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"규리 — 「글씨가 반듯하지 않으니 그것부터 고치자.」","correct":true,"mis_target":"K6-2-u4-X24"},{"t":"하진 — 「언제 무엇을 할지가 드러나지 않으니 넣어 보자.」","mis":"K6-2-u4-X23"},{"t":"세나 — 「왜 그렇게 다짐하는지 목적을 덧붙이자.」","mis":"K6-2-u4-X22"}],"explanation":["고칠 점은 내용에서 찾아요.","하진과 세나는 다짐문이 하는 일을 살폈어요.","규리는 겉모습을 보았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#1','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',2,'sa','auto','아는 사람끼리만 통하는 말은 「지나치게 ○○ 말」이에요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C14","difficulty":2,"kind":"sa","stem":"아는 사람끼리만 통하는 말은 「지나치게 ○○ 말」이에요. ○○에 알맞은 두 글자를 쓰세요.","answer":["줄인"],"explanation":["말을 짧게 줄이면 편해 보여요.","그러나 아는 사람끼리만 통해요.","그래서 지나치게 줄인 말을 점검해요."],"mis":"K6-2-u4-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#2','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',2,'mc','auto','모은 것을 우리 반의 실태로 정리할 때 넣지 않는 것은 어느 것인가요?',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":2,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"모은 것을 우리 반의 실태로 정리할 때 넣지 않는 것은 어느 것인가요?","options":[{"t":"말을 가장 많이 틀린 친구의 이름","correct":true},{"t":"많이 쓰는 외국어 표현","mis":"K6-2-u4-X21"},{"t":"많이 쓰는 줄인 말","mis":"K6-2-u4-X21"},{"t":"바꿀 수 있는 쉬운 우리말","mis":"K6-2-u4-X21"}],"explanation":["실태는 우리 반의 모습이에요.","외국어 표현 · 줄인 말 · 어려웠던 말 · 바꿀 말을 정리해요.","친구 이름은 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#3','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',3,'mc','auto','다인이의 다짐 「알림장을 쓸 때 쉬운 우리말로 바꿀 수 있는 말은 바꾸어 쓰겠습니다」가 좋은 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X23','K6-2-u4-X24']::text[],false,'{"seq":3,"concept":"K6-2-u4-C15","difficulty":3,"kind":"mc","stem":"다인이의 다짐 「알림장을 쓸 때 쉬운 우리말로 바꿀 수 있는 말은 바꾸어 쓰겠습니다」가 좋은 까닭은 어느 것인가요?","options":[{"t":"언제 무엇을 할지 드러나 지킬 수 있어서","correct":true},{"t":"크고 멋진 다짐이라서","mis":"K6-2-u4-X23"},{"t":"다른 사람이 할 일을 정해 주어서","mis":"K6-2-u4-X23"},{"t":"글자 수가 많아서","mis":"K6-2-u4-X24"}],"explanation":["「알림장을 쓸 때」가 언제예요.","「바꿀 수 있는 말은 바꾸어 쓰기」가 무엇이에요.","그래서 지킬 수 있어요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","나는 우리말을 아끼고 바르게 쓰기 위해 다음과 같이 다짐합니다.","하나, 모둠 활동에서 친구가 알아듣지 못하는 말을 쓰면 바로 풀어서 다시 말하겠습니다.","하나, 알림장을 쓸 때 쉬운 우리말로 바꿀 수 있는 말은 바꾸어 쓰겠습니다.","하나, 다른 고장의 말을 웃음거리로 삼지 않겠습니다.","친구들도 모르는 말은 되묻고, 어려운 말은 풀어 말해 주세요."],"title":"다인이가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#4','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',3,'mc','auto','친구의 다짐문을 읽고 말해 주는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X24']::text[],false,'{"seq":4,"concept":"K6-2-u4-C15","difficulty":3,"kind":"mc","stem":"친구의 다짐문을 읽고 말해 주는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"잘 쓴 부분을 먼저 말하고, 고칠 점은 내용에서 찾아 바꾸어 볼 문장과 함께 말한다","correct":true},{"t":"고칠 점만 빠짐없이 말한다","mis":"K6-2-u4-X24"},{"t":"글씨와 종이 색부터 말한다","mis":"K6-2-u4-X24"},{"t":"잘 쓴 부분만 말하고 고칠 점은 말하지 않는다","mis":"K6-2-u4-X24"}],"explanation":["잘 쓴 부분 먼저예요.","고칠 점은 내용에서 찾아요.","바꾸어 볼 문장도 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#5','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',3,'ox','auto','점검표를 친구가 잘못 쓴 말의 증거로 내밀어도 돼요.',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":5,"concept":"K6-2-u4-C14","difficulty":3,"kind":"ox","stem":"점검표를 친구가 잘못 쓴 말의 증거로 내밀어도 돼요.","answer":"X","reason_options":[{"t":"점검은 흠잡기가 아니라 우리 반이 함께 고치려는 일이기 때문에","correct":true},{"t":"증거가 있어야 친구가 말을 고치기 때문에","mis":"K6-2-u4-X21"}],"mis":"K6-2-u4-X21","explanation":["점검표는 증거가 아니에요.","함께 고치려고 만든 표예요.","바라는 점을 함께 이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#6','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',3,'match','auto','지키기 어려운 다짐과 그 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C15","difficulty":3,"kind":"match","stem":"지키기 어려운 다짐과 그 까닭을 알맞게 이으세요.","pairs":[{"l":"「앞으로 열심히 하겠다」","r":"무엇을 할지가 없다"},{"l":"「하나도 쓰지 않겠다」","r":"지킬 수 없을 만큼 크다"},{"l":"「다들 그렇게 하자」","r":"내가 할 일이 없다"}],"mis":"K6-2-u4-X23","explanation":["무엇을 할지 있어야 해요.","지킬 수 있는 크기여야 해요.","내가 할 일이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#7','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',3,'error','auto','완성한 다짐문을 나누는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X26']::text[],false,'{"seq":7,"concept":"K6-2-u4-C15","difficulty":3,"kind":"error","stem":"완성한 다짐문을 나누는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태민 — 「다짐문은 써서 서랍에 넣어 두면 끝이야.」","correct":true,"mis_target":"K6-2-u4-X26"},{"t":"아린 — 「학급 알림판에 붙여 오가며 보자.」","mis":"K6-2-u4-X26"},{"t":"정우 — 「다짐문 아래에 이름을 적어 함께 약속하자.」","mis":"K6-2-u4-X26"}],"explanation":["여러 사람과 나눌수록 다짐이 생활로 옮겨져요.","아린과 정우는 나누는 방법을 말했어요.","서랍에 넣으면 다짐이 남지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#8','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',4,'mc','auto','실천한 뒤 스스로 되돌아본 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X26','K6-2-u4-X21','K6-2-u4-X23']::text[],false,'{"seq":8,"concept":"K6-2-u4-C14","difficulty":4,"kind":"mc","stem":"실천한 뒤 스스로 되돌아본 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「알아듣기 쉬운 말로 바꾸어 말한 적이 있었지만 줄인 말을 쓰는 버릇은 남았다. 내일 모둠 활동에서 한 번 더 풀어 말해 보겠다.」","correct":true},{"t":"「한 번 했으니 다 바뀌었다.」","mis":"K6-2-u4-X26"},{"t":"「우리 반에서 줄인 말을 가장 많이 쓴 사람은 내 짝이다.」","mis":"K6-2-u4-X21"},{"t":"「잘 모르겠지만 열심히 했다.」","mis":"K6-2-u4-X23"}],"explanation":["변화한 점과 노력할 점을 함께 봐요.","내일 한 번 더 해 볼 일을 정해요.","되돌아보고 다시 해 보는 것까지가 학습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#9','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',4,'essay','teacher','우리말을 바르게 쓰기 위한 실천 다짐문을 네 부분을 모두 갖추어 쓰세요. 실천 약속은 언제 · 어디에서 · 무엇을 할지 드러나게 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C15","difficulty":4,"kind":"essay","stem":"우리말을 바르게 쓰기 위한 실천 다짐문을 네 부분을 모두 갖추어 쓰세요. 실천 약속은 언제 · 어디에서 · 무엇을 할지 드러나게 두 가지 쓰세요.","answer_guide":{"answer":"예: 목적 — 나는 우리 반 친구들이 서로의 말을 잘 알아들을 수 있도록 다음과 같이 다짐합니다. 실천 약속 — 하나, 나는 모둠 활동에서 줄인 말을 쓰면 바로 풀어서 다시 말하겠습니다. 하나, 나는 학급 알림판에 글을 쓸 때 어려운 외국어를 쉬운 우리말로 바꾸어 쓰겠습니다. 전하고 싶은 말 — 친구들도 모르는 말은 부끄러워하지 말고 되물어 주세요. 날짜와 쓴 사람 — 시월 셋째 주 월요일, 김하늘.","scoring_points":["목적 · 실천 약속 · 전하고 싶은 말 · 날짜와 쓴 사람을 갖추었는가","실천 약속에 언제 · 어디에서 · 무엇을이 드러나는가","내가 지킬 수 있는 크기의 다짐인가"]},"explanation":["네 부분을 빠뜨리지 않아요.","언제 · 어디에서 · 무엇을.","크게 말하기보다 지킬 수 있게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#10','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',4,'essay','teacher','언어생활 점검이 친구를 흠잡는 일이 아닌 까닭을 쓰고, 점검할 때 해야 할 일을 세 가지 쓰세요. 그리고 점검한 것을 우리 반의 실태로 정리할 때 어떤 내용을 넣을지 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C14","difficulty":4,"kind":"essay","stem":"언어생활 점검이 친구를 흠잡는 일이 아닌 까닭을 쓰고, 점검할 때 해야 할 일을 세 가지 쓰세요. 그리고 점검한 것을 우리 반의 실태로 정리할 때 어떤 내용을 넣을지 두 가지 쓰세요.","answer_guide":{"answer":"예: 점검은 우리 반의 말버릇을 살펴 함께 고치려는 일이므로 친구를 흠잡는 일이 아니다. 점검할 때는 먼저 내가 쓴 말부터 적고, 고칠 점을 우리 반의 일로 말하고, 바라는 점을 함께 이야기한다. 실태에는 많이 쓰는 줄인 말과, 그 말을 바꿀 수 있는 쉬운 우리말을 넣는다.","scoring_points":["점검의 목적을 바르게 썼는가","점검할 때 할 일 세 가지를 썼는가","실태로 정리할 내용을 두 가지 썼는가"]},"explanation":["점검은 고치려고 해요.","내가 쓴 말부터, 우리 반의 일로.","친구 이름은 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#1','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',1,'mc','auto','고유어의 뜻을 하나씩 알려 주고 싶을 때 알맞은 활동 방법은 어느 것인가요?',ARRAY['K6-2-u4-X27']::text[],false,'{"seq":1,"concept":"K6-2-u4-C16","difficulty":1,"kind":"mc","stem":"고유어의 뜻을 하나씩 알려 주고 싶을 때 알맞은 활동 방법은 어느 것인가요?","options":[{"t":"복도 알림판에 낱말을 하나씩 붙이는 인쇄물","correct":true},{"t":"한 번만 틀고 마는 짧은 알림 영상","mis":"K6-2-u4-X27"},{"t":"가사 없이 소리만 나오는 배경 음악","mis":"K6-2-u4-X27"},{"t":"말로 한 번 알려 주고 끝내기","mis":"K6-2-u4-X27"}],"explanation":["낱말은 한 번 보고 외워지지 않아요.","여러 번 마주쳐야 해요.","붙여 두는 인쇄물이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#2','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',1,'sa','auto','우리말 지킴이 활동을 계획할 때 주제 · 내용 · 역할 · ○○을 정해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C16","difficulty":1,"kind":"sa","stem":"우리말 지킴이 활동을 계획할 때 주제 · 내용 · 역할 · ○○을 정해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["시간"],"explanation":["무엇을 알릴지가 주제예요.","누가 무엇을 맡을지가 역할이에요.","언제까지 만들고 보여 줄지가 시간이에요."],"mis":"K6-2-u4-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#3','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',1,'ox','auto','우리말을 알리는 홍보물에는 어려운 외국어를 넣어야 눈에 띄어요.',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":3,"concept":"K6-2-u4-C16","difficulty":1,"kind":"ox","stem":"우리말을 알리는 홍보물에는 어려운 외국어를 넣어야 눈에 띄어요.","answer":"X","reason_options":[{"t":"알리려는 우리말과 앞뒤가 맞지 않고 읽는 사람이 알아듣기 어렵기 때문에","correct":true},{"t":"눈에 띄는 것이 알아듣는 것보다 중요하기 때문에","mis":"K6-2-u4-X25"}],"mis":"K6-2-u4-X25","explanation":["우리말을 알리는 홍보물이에요.","문구가 어려우면 앞뒤가 맞지 않아요.","읽는 사람이 알아들을 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#4','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C17',1,'mc','auto','「증발」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X28']::text[],false,'{"seq":4,"concept":"K6-2-u4-C17","difficulty":1,"kind":"mc","stem":"「증발」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"액체가 그 표면에서 기체로 변하는 현상","correct":true},{"t":"땅의 생긴 모양","mis":"K6-2-u4-X28"},{"t":"일정한 범위에 흩어져 퍼져 있음","mis":"K6-2-u4-X28"},{"t":"자연 현상을 살펴 재거나 헤아리는 일","mis":"K6-2-u4-X28"}],"explanation":["땅의 생긴 모양은 지형이에요.","흩어져 퍼져 있음은 분포예요.","살펴 재거나 헤아리는 일은 관측이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#5','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',2,'mc','auto','두 홍보 문구 가운데 더 알맞은 것과 그 까닭으로 바른 것은 어느 것인가요?',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":5,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"두 홍보 문구 가운데 더 알맞은 것과 그 까닭으로 바른 것은 어느 것인가요?","options":[{"t":"두 번째 — 읽는 사람이 무엇을 하면 되는지 바로 알 수 있어서","correct":true},{"t":"첫 번째 — 외국어가 섞여 멋있어서","mis":"K6-2-u4-X25"},{"t":"첫 번째 — 글자 수가 적어서","mis":"K6-2-u4-X25"},{"t":"두 번째 — 물음표가 있어서","mis":"K6-2-u4-X25"}],"explanation":["첫 번째 문구는 우리말을 알리면서 정작 어려워요.","두 번째 문구는 할 일이 보여요.","물음표 때문이 아니라 내용 때문이에요."],"asset":{"type":"passage","lines":["첫 번째 문구 — 「우리말 클린 데이에 조인해 주세요!」","두 번째 문구 — 「오늘 한 번, 쉬운 우리말로 바꾸어 말해 볼까요?」"],"title":"우리말 홍보 문구 두 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#6','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',2,'match','auto','활동 방법과 그 방법이 잘 살리는 점을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C16","difficulty":2,"kind":"match","stem":"활동 방법과 그 방법이 잘 살리는 점을 이으세요.","pairs":[{"l":"알림 영상","r":"움직임과 목소리를 함께 전할 수 있다"},{"l":"인쇄물","r":"한자리에 붙여 두고 여러 번 보게 할 수 있다"},{"l":"만화","r":"짧은 이야기로 쉽게 이해시킬 수 있다"}],"mis":"K6-2-u4-X27","explanation":["영상은 움직임과 목소리예요.","인쇄물은 오래 붙여 두기예요.","만화는 짧은 이야기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#7','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',2,'mc','auto','우리말 홍보물에 들어갈 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X13']::text[],false,'{"seq":7,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"우리말 홍보물에 들어갈 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"보는 사람이 오늘 해 볼 수 있는 행동","correct":true},{"t":"말을 잘못 쓴 친구의 이름","mis":"K6-2-u4-X25"},{"t":"우리 모둠이 얼마나 애썼는지 적은 내용","mis":"K6-2-u4-X25"},{"t":"알릴 내용을 가리는 꾸밈 그림","mis":"K6-2-u4-X13"}],"explanation":["보는 사람이 무엇을 알게 될지 생각해요.","무엇을 하게 될지도 생각해요.","누구를 탓하거나 자랑하는 내용은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#8','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C17',2,'match','auto','교과 학습에 자주 나오는 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u4-C17","difficulty":2,"kind":"match","stem":"교과 학습에 자주 나오는 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"지형","r":"땅의 생긴 모양"},{"l":"분포","r":"일정한 범위에 흩어져 퍼져 있음"},{"l":"관측","r":"자연 현상을 살펴 재거나 헤아리는 일"}],"mis":"K6-2-u4-X28","explanation":["지형은 사회 · 과학에서 자주 만나요.","분포는 흩어져 퍼진 모습이에요.","관측은 살펴 재는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#9','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',2,'ox','auto','홍보물을 만든 날에만 우리말을 아껴도 실천했다고 할 수 있어요.',ARRAY['K6-2-u4-X26']::text[],false,'{"seq":9,"concept":"K6-2-u4-C16","difficulty":2,"kind":"ox","stem":"홍보물을 만든 날에만 우리말을 아껴도 실천했다고 할 수 있어요.","answer":"X","reason_options":[{"t":"하루로 끝나면 행사일 뿐이고 이어서 해야 실천이 되기 때문에","correct":true},{"t":"홍보물을 만드는 일이 실천의 전부이기 때문에","mis":"K6-2-u4-X26"}],"mis":"K6-2-u4-X26","explanation":["하루로 끝나면 다짐이 남지 않아요.","우리말 일기 · 지킴이 도전처럼 이어서 해요.","그래야 실천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#10','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',3,'error','auto','우리말 지킴이 활동을 계획하며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":10,"concept":"K6-2-u4-C16","difficulty":3,"kind":"error","stem":"우리말 지킴이 활동을 계획하며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서준 — 「역할은 만들면서 정하고, 꾸미기부터 시작하자.」","correct":true,"mis_target":"K6-2-u4-X25"},{"t":"이서 — 「역할을 먼저 나누어 빠지는 사람이 없게 하자.」","mis":"K6-2-u4-X25"},{"t":"하준 — 「언제까지 만들고 언제 보여 줄지 정하자.」","mis":"K6-2-u4-X25"}],"explanation":["계획은 주제 · 내용 · 역할 · 시간이에요.","이서와 하준은 계획을 먼저 세웠어요.","서준은 꾸밈을 앞세웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#1','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C17',2,'sa','auto','「땅의 생긴 모양」을 뜻하는 낱말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C17","difficulty":2,"kind":"sa","stem":"「땅의 생긴 모양」을 뜻하는 낱말을 두 글자로 쓰세요.","answer":["지형"],"explanation":["교과서에서 자주 만나는 한자어예요.","「이 고장은 지형이 험하다」처럼 써요.","정답은 지형이에요."],"mis":"K6-2-u4-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#2','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',2,'mc','auto','하루에 한 낱말씩 새로 안 우리말을 적는 활동은 어느 것인가요?',ARRAY['K6-2-u4-X27']::text[],false,'{"seq":2,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"하루에 한 낱말씩 새로 안 우리말을 적는 활동은 어느 것인가요?","options":[{"t":"우리말 일기","correct":true},{"t":"지킴이 도전","mis":"K6-2-u4-X27"},{"t":"교실 말 고치기","mis":"K6-2-u4-X27"},{"t":"알림 영상","mis":"K6-2-u4-X27"}],"explanation":["지킴이 도전은 한 주 동안 다짐 하나 지키기예요.","교실 말 고치기는 알림 글부터 바꾸기예요.","한 낱말씩 적는 것은 우리말 일기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#3','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',3,'mc','auto','고유어로 지은 가게 이름이 많다는 것을 짧은 이야기로 동생들에게 쉽게 알리고 싶어요. 알맞은 방법은 어느 것인가요?',ARRAY['K6-2-u4-X27','K6-2-u4-X13']::text[],false,'{"seq":3,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"고유어로 지은 가게 이름이 많다는 것을 짧은 이야기로 동생들에게 쉽게 알리고 싶어요. 알맞은 방법은 어느 것인가요?","options":[{"t":"만화","correct":true},{"t":"표","mis":"K6-2-u4-X27"},{"t":"글자만 빽빽한 인쇄물","mis":"K6-2-u4-X13"},{"t":"가사 없는 배경 음악","mis":"K6-2-u4-X27"}],"explanation":["동생들에게는 쉽게 전해야 해요.","짧은 이야기로 전하기에는 만화가 알맞아요.","알릴 내용에 따라 방법을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#4','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',3,'mc','auto','친구 모둠이 만든 것을 볼 때 보는 사람이 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X24','K6-2-u4-X14']::text[],false,'{"seq":4,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"친구 모둠이 만든 것을 볼 때 보는 사람이 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"알릴 내용이 잘 드러났는지 살피고 느낀 점과 보충할 점을 까닭과 함께 말한다","correct":true},{"t":"가장 화려한 모둠을 뽑는다","mis":"K6-2-u4-X13"},{"t":"잘못된 점만 찾아 말한다","mis":"K6-2-u4-X24"},{"t":"아무 말도 하지 않는다","mis":"K6-2-u4-X14"}],"explanation":["먼저 알릴 내용이 드러났는지 봐요.","느낀 점과 보충할 점을 말해요.","까닭과 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#5','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C17',3,'ox','auto','교과 낱말은 뜻만 외우는 것보다 문장으로 한 번 써 보는 것이 오래 남아요.',ARRAY['K6-2-u4-X28']::text[],false,'{"seq":5,"concept":"K6-2-u4-C17","difficulty":3,"kind":"ox","stem":"교과 낱말은 뜻만 외우는 것보다 문장으로 한 번 써 보는 것이 오래 남아요.","answer":"O","reason_options":[{"t":"낱말이 쓰이는 자리를 함께 익히기 때문에","correct":true},{"t":"문장으로 쓰면 뜻을 몰라도 되기 때문에","mis":"K6-2-u4-X28"}],"mis":"K6-2-u4-X28","explanation":["뜻만 외우면 금방 잊어요.","문장으로 쓰면 쓰이는 자리가 남아요.","다른 과목 공부도 쉬워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#6','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',3,'match','auto','하루로 끝내지 않는 활동과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C16","difficulty":3,"kind":"match","stem":"하루로 끝내지 않는 활동과 하는 일을 알맞게 이으세요.","pairs":[{"l":"우리말 일기","r":"하루에 한 낱말씩 새로 안 우리말 적기"},{"l":"지킴이 도전","r":"한 주 동안 정한 다짐 하나 지키기"},{"l":"교실 말 고치기","r":"우리 반 알림 글부터 쉬운 우리말로 바꾸기"}],"mis":"K6-2-u4-X26","explanation":["일기는 날마다 한 낱말이에요.","도전은 한 주 동안 다짐 하나예요.","교실 말 고치기는 알림 글부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#7','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',3,'error','auto','홍보 문구를 고르며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X13']::text[],false,'{"seq":7,"concept":"K6-2-u4-C16","difficulty":3,"kind":"error","stem":"홍보 문구를 고르며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"예준 — 「‘외래어를 쓰는 사람은 우리말을 해칩니다’가 가장 세서 좋아.」","correct":true,"mis_target":"K6-2-u4-X25"},{"t":"채아 — 「‘모르는 말은 되묻고, 어려운 말은 풀어 말해요’는 할 일이 보여.」","mis":"K6-2-u4-X25"},{"t":"시아 — 「알릴 내용이 한눈에 보이는지 먼저 살펴보자.」","mis":"K6-2-u4-X13"}],"explanation":["채아와 시아는 읽는 사람의 할 일과 내용을 보았어요.","예준은 누군가를 탓하는 문구를 골랐어요.","탓하는 말은 홍보 문구로 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#8','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C17',4,'mc','auto','「날마다 같은 시각에 하늘을 ○○해 기록했다.」에서 ○○에 가장 알맞은 낱말은 어느 것인가요?',ARRAY['K6-2-u4-X28']::text[],false,'{"seq":8,"concept":"K6-2-u4-C17","difficulty":4,"kind":"mc","stem":"「날마다 같은 시각에 하늘을 ○○해 기록했다.」에서 ○○에 가장 알맞은 낱말은 어느 것인가요?","options":[{"t":"관측","correct":true},{"t":"증발","mis":"K6-2-u4-X28"},{"t":"지형","mis":"K6-2-u4-X28"},{"t":"분포","mis":"K6-2-u4-X28"}],"explanation":["하늘을 살펴 재거나 헤아리는 일이에요.","날마다 같은 시각에 기록했어요.","그래서 관측이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#9','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',4,'essay','teacher','우리 반에서 할 우리말 지킴이 활동을 계획하세요. 알릴 내용과 그에 맞는 방법을 고른 까닭, 주제 · 내용 · 역할 · 시간, 홍보 문구 한 줄, 하루로 끝내지 않고 이어 할 일을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C16","difficulty":4,"kind":"essay","stem":"우리 반에서 할 우리말 지킴이 활동을 계획하세요. 알릴 내용과 그에 맞는 방법을 고른 까닭, 주제 · 내용 · 역할 · 시간, 홍보 문구 한 줄, 하루로 끝내지 않고 이어 할 일을 쓰세요.","answer_guide":{"answer":"예: 알릴 내용 — 쉬운 우리말로 다듬은 말. 방법 — 복도 알림판 인쇄물(여러 번 보게 할 수 있어서). 주제 — 쉬운 우리말로 바꾸어 말하기. 내용 — 다운로드 → 내려받기처럼 다듬은 말 짝. 역할 — 둘은 낱말 찾기, 둘은 글씨 쓰기. 시간 — 수요일까지 만들고 목요일에 붙이기. 문구 — 「오늘 한 번, 쉬운 우리말로 바꾸어 말해 볼까요?」 이어 할 일 — 붙인 뒤 한 주 동안 지킴이 도전.","scoring_points":["알릴 내용에 맞는 방법과 까닭을 썼는가","주제 · 내용 · 역할 · 시간을 모두 정했는가","알아들을 수 있는 문구와 이어 할 일을 썼는가"]},"explanation":["내용에 맞는 방법을 골라요.","역할을 먼저 나누어요.","하루로 끝내지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#10','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C17',4,'essay','teacher','증발 · 지형 · 분포 · 관측 가운데 두 낱말을 골라 각각의 뜻을 쓰고, 그 낱말을 넣어 문장을 하나씩 만드세요. 그리고 네 낱말이 어떤 갈래의 낱말인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C17","difficulty":4,"kind":"essay","stem":"증발 · 지형 · 분포 · 관측 가운데 두 낱말을 골라 각각의 뜻을 쓰고, 그 낱말을 넣어 문장을 하나씩 만드세요. 그리고 네 낱말이 어떤 갈래의 낱말인지 쓰세요.","answer_guide":{"answer":"예: 증발 — 액체가 그 표면에서 기체로 변하는 현상. 문장 — 「햇볕에 둔 물이 증발해서 컵이 비었다.」 분포 — 일정한 범위에 흩어져 퍼져 있음. 문장 — 「우리 동네에는 놀이터가 고르게 분포해 있다.」 네 낱말은 모두 한자로 이루어진 한자어이다.","scoring_points":["두 낱말의 뜻을 바르게 썼는가","낱말을 넣어 뜻에 맞는 문장을 만들었는가","네 낱말이 한자어라는 것을 썼는가"]},"explanation":["뜻을 정확히 알아 둬요.","문장으로 써 보면 오래 남아요.","모두 한자어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#1','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C1',1,'mc','auto','「호미」는 어떤 갈래의 낱말인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X19']::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"mc","stem":"「호미」는 어떤 갈래의 낱말인가요?","options":[{"t":"고유어","correct":true},{"t":"한자어","mis":"K6-2-u4-X01"},{"t":"외래어","mis":"K6-2-u4-X01"},{"t":"방언","mis":"K6-2-u4-X19"}],"explanation":["호미는 사전에 한글 표기만 있어요.","처음부터 우리말에 있던 낱말이에요.","그래서 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#2','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C2',1,'mc','auto','우리말을 바르게 쓰는 것이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u4-X02']::text[],false,'{"seq":2,"concept":"K6-2-u4-C2","difficulty":1,"kind":"mc","stem":"우리말을 바르게 쓰는 것이 아닌 것은 어느 것인가요?","options":[{"t":"한자어와 외래어를 하나도 쓰지 않는 것","correct":true},{"t":"듣는 사람이 알아들을 수 있게 쓰는 것","mis":"K6-2-u4-X02"},{"t":"낱말의 뜻에 맞게 쓰는 것","mis":"K6-2-u4-X02"},{"t":"바꿀 수 있는 말은 쉬운 우리말로 쓰는 것","mis":"K6-2-u4-X02"}],"explanation":["알아들을 수 있게 쓰기는 바르게 쓰기예요.","뜻에 맞게, 바꿀 수 있는 말은 쉽게도 그래요.","다른 갈래를 몰아내는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#3','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C3',1,'mc','auto','「뜻을 알기 어려운 새말」을 쓰면 생기는 문제로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X04']::text[],false,'{"seq":3,"concept":"K6-2-u4-C3","difficulty":1,"kind":"mc","stem":"「뜻을 알기 어려운 새말」을 쓰면 생기는 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"금방 생겼다 사라져서 뜻이 서로 다르게 통한다","correct":true},{"t":"뜻은 통해도 마음이 다친다","mis":"K6-2-u4-X04"},{"t":"쉬운 우리말이 있는데도 어렵게 쓴 것이다","mis":"K6-2-u4-X04"},{"t":"사전에 오래 실려 있어 낡았다","mis":"K6-2-u4-X04"}],"explanation":["새말은 금방 생겼다 사라져요.","사람마다 뜻을 다르게 알아요.","그래서 서로 다르게 통해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#4','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C4',1,'mc','auto','국어사전에서 「토마토(tomato)」처럼 낱말 뒤에 외국어가 함께 있으면 어떤 갈래인가요?',ARRAY['K6-2-u4-X05','K6-2-u4-X19']::text[],false,'{"seq":4,"concept":"K6-2-u4-C4","difficulty":1,"kind":"mc","stem":"국어사전에서 「토마토(tomato)」처럼 낱말 뒤에 외국어가 함께 있으면 어떤 갈래인가요?","options":[{"t":"외래어","correct":true},{"t":"고유어","mis":"K6-2-u4-X05"},{"t":"한자어","mis":"K6-2-u4-X05"},{"t":"방언","mis":"K6-2-u4-X19"}],"explanation":["한글 표기만 있으면 고유어예요.","한자가 있으면 한자어예요.","외국어가 있으면 외래어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#5','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C6',1,'mc','auto','「익일」을 쉬운 우리말로 다듬은 말은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X03']::text[],false,'{"seq":5,"concept":"K6-2-u4-C6","difficulty":1,"kind":"mc","stem":"「익일」을 쉬운 우리말로 다듬은 말은 어느 것인가요?","options":[{"t":"다음 날","correct":true},{"t":"명일","mis":"K6-2-u4-X08"},{"t":"넥스트 데이","mis":"K6-2-u4-X03"},{"t":"지난날","mis":"K6-2-u4-X08"}],"explanation":["익일은 그다음 날이라는 뜻이에요.","「다음 날」이라고 하면 바로 알 수 있어요.","다른 어려운 말로 바꾸면 다듬은 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#6','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C8',1,'mc','auto','고유어를 활용한 사례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":6,"concept":"K6-2-u4-C8","difficulty":1,"kind":"mc","stem":"고유어를 활용한 사례로 알맞은 것은 어느 것인가요?","options":[{"t":"나루터길","correct":true},{"t":"센트럴 로드","mis":"K6-2-u4-X10"},{"t":"제일 빌딩","mis":"K6-2-u4-X10"},{"t":"스카이 아파트","mis":"K6-2-u4-X10"}],"explanation":["나루터길은 나루터 + 길로 나눌 수 있어요.","둘 다 고유어예요.","나머지는 외국어나 한자어로 지은 이름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#7','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C11',1,'mc','auto','우리말 사전을 만드는 일이 「함께 쓰는 말을 지키는 일」이었던 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X15','K6-2-u4-X19']::text[],false,'{"seq":7,"concept":"K6-2-u4-C11","difficulty":1,"kind":"mc","stem":"우리말 사전을 만드는 일이 「함께 쓰는 말을 지키는 일」이었던 까닭은 어느 것인가요?","options":[{"t":"흩어진 말을 모아 남겨 오늘 국어사전의 바탕이 되었기 때문에","correct":true},{"t":"외국어를 모두 우리말로 바꾸었기 때문에","mis":"K6-2-u4-X15"},{"t":"고장 말을 모두 지웠기 때문에","mis":"K6-2-u4-X19"},{"t":"낱말 수를 줄였기 때문에","mis":"K6-2-u4-X15"}],"explanation":["마음껏 쓰지 못하던 때에도 말을 모았어요.","고장 말까지 모아 남겼어요.","그 기록이 오늘 국어사전의 바탕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#8','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C15',1,'mc','auto','실천 다짐문의 네 부분에 들어가지 않는 것은 어느 것인가요?',ARRAY['K6-2-u4-X22']::text[],false,'{"seq":8,"concept":"K6-2-u4-C15","difficulty":1,"kind":"mc","stem":"실천 다짐문의 네 부분에 들어가지 않는 것은 어느 것인가요?","options":[{"t":"내가 받고 싶은 칭찬","correct":true},{"t":"목적","mis":"K6-2-u4-X22"},{"t":"구체적인 실천 약속","mis":"K6-2-u4-X22"},{"t":"날짜와 쓴 사람","mis":"K6-2-u4-X22"}],"explanation":["다짐문에는 목적과 실천 약속이 들어가요.","전하고 싶은 말, 날짜와 쓴 사람도 들어가요.","받고 싶은 칭찬은 들어가지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#9','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C8',2,'mc','auto','시우네 모둠이 고유어를 활용한 사례로 잘못 든 것은 어느 것인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":9,"concept":"K6-2-u4-C8","difficulty":2,"kind":"mc","stem":"시우네 모둠이 고유어를 활용한 사례로 잘못 든 것은 어느 것인가요?","options":[{"t":"스마일 마트","correct":true},{"t":"솔바람길","mis":"K6-2-u4-X10"},{"t":"한아름 꽃집","mis":"K6-2-u4-X10"},{"t":"솔바람길과 한아름 꽃집 모두","mis":"K6-2-u4-X10"}],"explanation":["솔 · 바람 · 길, 한아름은 고유어예요.","스마일은 영어예요.","그래서 고유어 사례가 아니에요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#10','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C10',2,'mc','auto','시우네 모둠이 「솔바람길」을 발표할 때 함께 보여 주면 좋은 매체는 어느 것인가요?',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":10,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"시우네 모둠이 「솔바람길」을 발표할 때 함께 보여 주면 좋은 매체는 어느 것인가요?","options":[{"t":"길이 어디에 있는지 보여 주는 지도와 길 사진","correct":true},{"t":"글자만 빽빽하게 적은 종이","mis":"K6-2-u4-X13"},{"t":"반짝이 장식을 붙인 표지","mis":"K6-2-u4-X13"},{"t":"발표 내내 틀어 둔 배경 음악","mis":"K6-2-u4-X13"}],"explanation":["길 이름은 위치와 함께 보여 줘요.","지도는 길의 흐름을 보여 줘요.","사진은 실제 모습을 보여 줘요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#11','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C12',2,'mc','auto','서윤이 이야기에서 「정구지」가 가리키는 것은 무엇일까요?',ARRAY['K6-2-u4-X18']::text[],false,'{"seq":11,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"서윤이 이야기에서 「정구지」가 가리키는 것은 무엇일까요?","options":[{"t":"바구니에 담긴 초록 채소","correct":true},{"t":"서랍 속 가위","mis":"K6-2-u4-X18"},{"t":"손때 묻은 수첩","mis":"K6-2-u4-X18"},{"t":"연필 한 자루","mis":"K6-2-u4-X18"}],"explanation":["외할머니는 정구지를 씻어 오라고 하셨어요.","서윤이는 바구니의 초록 채소를 보았어요.","앞뒤 말이 채소를 가리켜요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#12','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C12',2,'mc','auto','서윤이 이야기에 그대로 적혀 있는 것은 어느 것인가요?',ARRAY['K6-2-u4-X17']::text[],false,'{"seq":12,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"서윤이 이야기에 그대로 적혀 있는 것은 어느 것인가요?","options":[{"t":"수첩 맨 끝 장에 「다음은 누가?」라고 적혀 있었다","correct":true},{"t":"외할머니는 수첩을 서윤이에게 물려주겠다고 말씀하셨다","mis":"K6-2-u4-X17"},{"t":"서윤이는 수첩을 이어 적기로 마음먹었다","mis":"K6-2-u4-X17"},{"t":"수첩에는 다른 고장의 말도 적혀 있었다","mis":"K6-2-u4-X17"}],"explanation":["「다음은 누가?」는 글에 적혀 있어요.","물려주겠다는 말씀은 글에 없어요.","서윤이의 마음도 글에 적혀 있지 않아요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#13','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C15',2,'mc','auto','지후의 다짐문에서 빠진 부분은 어느 것인가요?',ARRAY['K6-2-u4-X22']::text[],false,'{"seq":13,"concept":"K6-2-u4-C15","difficulty":2,"kind":"mc","stem":"지후의 다짐문에서 빠진 부분은 어느 것인가요?","options":[{"t":"목적","correct":true},{"t":"구체적인 실천 약속","mis":"K6-2-u4-X22"},{"t":"전하고 싶은 말","mis":"K6-2-u4-X22"},{"t":"날짜와 쓴 사람","mis":"K6-2-u4-X22"}],"explanation":["「하나,」 네 줄이 실천 약속이에요.","「모두 함께 …」가 전하고 싶은 말, 마지막 줄이 날짜와 쓴 사람이에요.","무엇을 위해 다짐하는지가 빠졌어요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#14','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C16',2,'mc','auto','하람이네 홍보 문구를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":14,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"하람이네 홍보 문구를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「쉬운 우리말로 한 번 바꾸어 말해 볼까요?」","correct":true},{"t":"「굿 워드 챌린지 스타트!」","mis":"K6-2-u4-X25"},{"t":"「우리말 안 쓰는 사람, 반성하세요!」","mis":"K6-2-u4-X25"},{"t":"「우리말, 우리말, 우리말!」","mis":"K6-2-u4-X25"}],"explanation":["우리말을 알리는 문구는 쉬운 우리말로 써요.","누군가를 탓하지 않아요.","읽는 사람의 할 일이 보이게 써요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#15','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C5',2,'match','auto','시에 나온 고유어와 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-2-u4-C5","difficulty":2,"kind":"match","stem":"시에 나온 고유어와 뜻을 알맞게 이으세요.","pairs":[{"l":"오솔길","r":"폭이 좁고 호젓한 길"},{"l":"어스름","r":"조금 어둑한 상태, 또는 그런 때"},{"l":"잔물결","r":"자잘하게 이는 물결"}],"mis":"K6-2-u4-X18","explanation":["오솔길은 좁고 호젓한 길이에요.","어스름은 조금 어둑한 때예요.","잔물결은 자잘한 물결이에요."],"asset":{"type":"passage","lines":["밤새 내린 비에 / 개울이 불었다.","어제는 없던 여울이 / 돌 사이로 소리를 낸다.","오솔길 풀잎마다 / 이슬이 조롱조롱.","어스름에 잠겼던 마을이 / 천천히 깨어난다.","바람 한 줄기에 / 잔물결이 반짝인다.","이름을 알고 보니 / 모두 다르게 보인다."],"title":"시 「비 그친 아침」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#16','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C17',2,'mc','auto','「이 고장은 ○○이 험해 길이 굽어 있다.」에서 ○○에 알맞은 낱말은 어느 것인가요?',ARRAY['K6-2-u4-X28']::text[],false,'{"seq":16,"concept":"K6-2-u4-C17","difficulty":2,"kind":"mc","stem":"「이 고장은 ○○이 험해 길이 굽어 있다.」에서 ○○에 알맞은 낱말은 어느 것인가요?","options":[{"t":"지형","correct":true},{"t":"증발","mis":"K6-2-u4-X28"},{"t":"분포","mis":"K6-2-u4-X28"},{"t":"관측","mis":"K6-2-u4-X28"}],"explanation":["험하다는 것은 땅의 모양이에요.","땅의 생긴 모양은 지형이에요.","그래서 길이 굽어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#17','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C9',3,'error','auto','시우네 발표 자료를 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X12','K6-2-u4-X10']::text[],false,'{"seq":17,"concept":"K6-2-u4-C9","difficulty":3,"kind":"error","stem":"시우네 발표 자료를 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"보람 — 「‘다온 마을’은 뜻이 그럴듯하니 그대로 발표해도 돼.」","correct":true,"mis_target":"K6-2-u4-X12"},{"t":"지민 — 「‘스마일 마트’는 고유어가 아니니 다른 사례로 바꾸자.」","mis":"K6-2-u4-X10"},{"t":"현우 — 「‘솔바람길’은 낱말을 나누어 확인한 좋은 사례야.」","mis":"K6-2-u4-X10"}],"explanation":["지민과 현우는 갈래와 확인을 살폈어요.","보람은 출처 없는 뜻을 그대로 쓰자고 했어요.","그럴듯하다고 확인한 것은 아니에요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#18','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C12',3,'mc','auto','외할머니가 연필을 서윤이 쪽으로 밀어 주신 까닭을 추론한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X16']::text[],false,'{"seq":18,"concept":"K6-2-u4-C12","difficulty":3,"kind":"mc","stem":"외할머니가 연필을 서윤이 쪽으로 밀어 주신 까닭을 추론한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서윤이가 수첩에 동네 말을 이어 적어 주기를 바라셨을 것이다","correct":true},{"t":"책상 위 연필을 치우려 하셨을 것이다","mis":"K6-2-u4-X16"},{"t":"그림을 그려 보라고 하셨을 것이다","mis":"K6-2-u4-X16"},{"t":"수첩이 낡아 버리라고 하셨을 것이다","mis":"K6-2-u4-X16"}],"explanation":["끝 장에 「다음은 누가?」가 적혀 있었어요.","그 위에 연필을 올려 밀어 주셨어요.","두 단서가 같은 곳을 가리켜요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#19','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C15',3,'error','auto','지후의 다짐문을 읽고 말해 주었어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X24','K6-2-u4-X22']::text[],false,'{"seq":19,"concept":"K6-2-u4-C15","difficulty":3,"kind":"error","stem":"지후의 다짐문을 읽고 말해 주었어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"예서 — 「글씨가 비뚤어진 줄부터 다시 쓰자.」","correct":true,"mis_target":"K6-2-u4-X24"},{"t":"은호 — 「넷째 줄은 언제 무엇을 할지 있어서 좋아.」","mis":"K6-2-u4-X24"},{"t":"가온 — 「무엇을 위해 다짐하는지 목적 줄을 맨 앞에 넣자.」","mis":"K6-2-u4-X22"}],"explanation":["은호는 잘 쓴 부분을 먼저 말했어요.","가온은 빠진 부분을 내용에서 찾았어요.","예서는 겉모습을 보았어요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#20','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C16',3,'error','auto','하람이네 계획을 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X26']::text[],false,'{"seq":20,"concept":"K6-2-u4-C16","difficulty":3,"kind":"error","stem":"하람이네 계획을 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"소은 — 「알림판을 반짝이 종이로 가득 꾸미면 홍보는 다 된 거야.」","correct":true,"mis_target":"K6-2-u4-X25"},{"t":"윤호 — 「바꾸면 좋은 말 다섯 쌍이 한눈에 보이게 크게 쓰자.」","mis":"K6-2-u4-X25"},{"t":"해나 — 「붙인 뒤에도 한 주 동안 지킴이 도전을 이어 가자.」","mis":"K6-2-u4-X26"}],"explanation":["윤호는 알릴 내용을 앞세웠어요.","해나는 하루로 끝내지 않으려 했어요.","소은은 꾸밈을 홍보의 전부로 여겼어요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#21','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C13',3,'mc','auto','서윤이가 다른 고장 친구들 앞에서 방학 이야기를 발표할 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X20']::text[],false,'{"seq":21,"concept":"K6-2-u4-C13","difficulty":3,"kind":"mc","stem":"서윤이가 다른 고장 친구들 앞에서 방학 이야기를 발표할 때 알맞은 방법은 어느 것인가요?","options":[{"t":"「정구지」 같은 고장 말을 소개하며 표준어 「부추」로 뜻을 함께 말한다","correct":true},{"t":"고장 말은 틀린 말이니 빼고 말한다","mis":"K6-2-u4-X19"},{"t":"친구들이 모를 고장 말로만 말한다","mis":"K6-2-u4-X20"},{"t":"외할머니 말투를 흉내 내어 웃음거리로 삼는다","mis":"K6-2-u4-X19"}],"explanation":["발표는 여러 사람이 듣는 자리예요.","고장 말도 소중하니 소개할 수 있어요.","표준어로 뜻을 함께 말하면 모두 알아들어요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#22','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C2',3,'mc','auto','이 단원의 제목이 「소중한 우리말」인 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X19']::text[],false,'{"seq":22,"concept":"K6-2-u4-C2","difficulty":3,"kind":"mc","stem":"이 단원의 제목이 「소중한 우리말」인 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리말에는 세 갈래도, 표준어도, 고장 말도 모두 들어 있어 모두 소중하기 때문에","correct":true},{"t":"고유어만 소중한 말이기 때문에","mis":"K6-2-u4-X02"},{"t":"표준어만 소중한 말이기 때문에","mis":"K6-2-u4-X19"},{"t":"외래어를 몰아내야 하기 때문에","mis":"K6-2-u4-X02"}],"explanation":["첫 시간의 약속을 떠올려요.","세 갈래와 표준어 · 고장 말이 모두 우리말이에요.","그래서 모두 소중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#23','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C9',4,'mc','auto','시우네 발표 자료를 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X10','K6-2-u4-X12','K6-2-u4-X01']::text[],false,'{"seq":23,"concept":"K6-2-u4-C9","difficulty":4,"kind":"mc","stem":"시우네 발표 자료를 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"솔바람길 · 한아름 꽃집은 낱말을 나누고 확인한 곳까지 밝혀 좋지만, 다온 마을은 확인인지 짐작인지 밝혀야 하고 스마일 마트는 고유어 사례로 바꾸어야 한다","correct":true},{"t":"네 사례 모두 이름이 예뻐 잘 조사했다","mis":"K6-2-u4-X10"},{"t":"다온 마을 하나가 확인되지 않았으니 발표 전체를 믿을 수 없다","mis":"K6-2-u4-X12"},{"t":"스마일 마트는 영어 사전에서 확인했으니 고유어 사례로 괜찮다","mis":"K6-2-u4-X01"}],"explanation":["잘된 점을 먼저 짚어요.","확인 · 짐작을 가르고 갈래를 살펴요.","고칠 자리만 고치면 돼요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#24','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C9',4,'essay','teacher','시우네 발표 자료를 잘한 점과 고칠 점으로 나누어 평가하고, 고칠 점을 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C9","difficulty":4,"kind":"essay","stem":"시우네 발표 자료를 잘한 점과 고칠 점으로 나누어 평가하고, 고칠 점을 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 솔바람길은 솔 · 바람 · 길로 낱말을 나누어 고유어를 찾았고, 솔바람길과 한아름 꽃집은 뜻을 어디에서 확인했는지 밝혔다. 고칠 점 — 다온 마을은 뜻의 출처가 없어 확인한 것인지 짐작한 것인지 알 수 없다. 스마일 마트의 스마일은 영어라 고유어 사례가 아니다. 고칠 방법 — 다온 마을은 사전에서 찾고 동네 어른께 여쭈어 보고, 그래도 모르면 「아직 확인하지 못했습니다」라고 밝힌다. 스마일 마트는 고유어가 들어간 다른 가게 이름으로 바꾼다.","scoring_points":["잘한 점을 먼저 썼는가","확인 · 짐작과 갈래를 기준으로 고칠 점을 썼는가","고칠 방법을 구체적으로 썼는가"]},"explanation":["잘한 점부터 써요.","확인과 짐작, 갈래를 살펴요.","고칠 방법까지 써요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#25','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C5',4,'essay','teacher','「비 그친 아침」에서 고유어를 두 개 골라 뜻을 쓰고, 그 낱말이 어떤 장면을 떠올리게 하는지 쓰세요. 그리고 이 시와 이어서 고유어의 가치를 한 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C5","difficulty":4,"kind":"essay","stem":"「비 그친 아침」에서 고유어를 두 개 골라 뜻을 쓰고, 그 낱말이 어떤 장면을 떠올리게 하는지 쓰세요. 그리고 이 시와 이어서 고유어의 가치를 한 가지 쓰세요.","answer_guide":{"answer":"예: 여울 — 물살이 세게 흐르는 얕은 곳. 비에 불어난 개울물이 돌 사이로 소리를 내며 빠르게 흐르는 장면이 떠오른다. 잔물결 — 자잘하게 이는 물결. 바람이 불자 개울 위가 작게 반짝이는 장면이 떠오른다. 고유어는 눈에 보이는 모습과 느낌을 그대로 담고 있어서, 뜻을 알면 장면이 또렷이 보인다.","scoring_points":["고유어 두 개의 뜻을 바르게 썼는가","낱말이 떠올리게 하는 장면을 썼는가","고유어의 가치를 시와 이어 썼는가"]},"explanation":["뜻을 알면 장면이 보여요.","고유어는 느낌을 살려요.","시의 마지막 줄을 떠올려요."],"asset":{"type":"passage","lines":["밤새 내린 비에 / 개울이 불었다.","어제는 없던 여울이 / 돌 사이로 소리를 낸다.","오솔길 풀잎마다 / 이슬이 조롱조롱.","어스름에 잠겼던 마을이 / 천천히 깨어난다.","바람 한 줄기에 / 잔물결이 반짝인다.","이름을 알고 보니 / 모두 다르게 보인다."],"title":"시 「비 그친 아침」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#1','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C1',1,'sa','auto','한자로 이루어진 낱말을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"sa","stem":"한자로 이루어진 낱말을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["한자어"],"explanation":["처음부터 있던 말은 고유어예요.","다른 나라에서 온 말은 외래어예요.","한자로 이루어진 말은 한자어예요."],"mis":"K6-2-u4-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#2','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C2',1,'ox','auto','어려운 말을 많이 쓸수록 우리말을 잘 쓰는 거예요.',ARRAY['K6-2-u4-X03']::text[],false,'{"seq":2,"concept":"K6-2-u4-C2","difficulty":1,"kind":"ox","stem":"어려운 말을 많이 쓸수록 우리말을 잘 쓰는 거예요.","answer":"X","reason_options":[{"t":"듣는 사람이 알아들을 수 있게 쓰는 것이 바르게 쓰는 것이기 때문에","correct":true},{"t":"어려운 말을 쓰면 많이 아는 것처럼 보이기 때문에","mis":"K6-2-u4-X03"}],"mis":"K6-2-u4-X03","explanation":["어려운 말은 듣는 사람을 막아요.","말은 뜻을 주고받으려고 써요.","알아들을 수 있게 쓰는 것이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#3','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C3',1,'ox','auto','뜻만 통하면 기분을 상하게 하는 말을 써도 괜찮아요.',ARRAY['K6-2-u4-X04']::text[],false,'{"seq":3,"concept":"K6-2-u4-C3","difficulty":1,"kind":"ox","stem":"뜻만 통하면 기분을 상하게 하는 말을 써도 괜찮아요.","answer":"X","reason_options":[{"t":"뜻은 통해도 듣는 사람의 마음이 다치기 때문에","correct":true},{"t":"말은 뜻만 전하면 되기 때문에","mis":"K6-2-u4-X04"}],"mis":"K6-2-u4-X04","explanation":["말은 뜻만 전하는 것이 아니에요.","마음도 함께 전해져요.","기분 상하는 말은 마음을 다치게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#4','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C4',1,'sa','auto','갈래가 헷갈리는 낱말은 짐작하지 말고 무엇에서 확인하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u4-C4","difficulty":1,"kind":"sa","stem":"갈래가 헷갈리는 낱말은 짐작하지 말고 무엇에서 확인하나요? 네 글자로 쓰세요.","answer":["국어사전"],"explanation":["소리나 모양으로 짐작하면 틀리기 쉬워요.","종이 사전이든 스마트 기기 사전이든 좋아요.","국어사전에서 확인해요."],"mis":"K6-2-u4-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#5','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C6',1,'sa','auto','「다운로드」를 쉬운 우리말로 다듬은 말을 네 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u4-C6","difficulty":1,"kind":"sa","stem":"「다운로드」를 쉬운 우리말로 다듬은 말을 네 글자로 쓰세요.","answer":["내려받기"],"explanation":["다운로드는 무엇을 내려받는 일이에요.","「내려받기」라고 하면 동작이 그려져요.","누구나 알아들을 수 있어요."],"mis":"K6-2-u4-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#6','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C9',1,'sa','auto','조사 계획에서는 조사 대상 · 조사 범위 · 조사 ○○을 정해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C9","difficulty":1,"kind":"sa","stem":"조사 계획에서는 조사 대상 · 조사 범위 · 조사 ○○을 정해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["방법"],"explanation":["무엇을 조사할지가 대상이에요.","어디까지 조사할지가 범위예요.","어떻게 조사할지가 방법이에요."],"mis":"K6-2-u4-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#7','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C12',1,'sa','auto','글쓴이가 적지 않은 부분을 단서와 경험으로 메우는 일을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u4-C12","difficulty":1,"kind":"sa","stem":"글쓴이가 적지 않은 부분을 단서와 경험으로 메우는 일을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["추론"],"explanation":["글쓴이는 모든 것을 다 적지 않아요.","단서와 경험 · 지식으로 메워요.","그것을 추론이라고 해요."],"mis":"K6-2-u4-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#8','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C17',1,'sa','auto','「일정한 범위에 흩어져 퍼져 있음」을 뜻하는 낱말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u4-C17","difficulty":1,"kind":"sa","stem":"「일정한 범위에 흩어져 퍼져 있음」을 뜻하는 낱말을 두 글자로 쓰세요.","answer":["분포"],"explanation":["지형은 땅의 생긴 모양이에요.","관측은 살펴 재는 일이에요.","흩어져 퍼져 있음은 분포예요."],"mis":"K6-2-u4-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#9','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C9',2,'mc','auto','시우네 표에서 뜻을 어디에서 확인했는지 밝히지 않은 사례는 어느 것인가요?',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":9,"concept":"K6-2-u4-C9","difficulty":2,"kind":"mc","stem":"시우네 표에서 뜻을 어디에서 확인했는지 밝히지 않은 사례는 어느 것인가요?","options":[{"t":"다온 마을","correct":true},{"t":"솔바람길","mis":"K6-2-u4-X12"},{"t":"한아름 꽃집","mis":"K6-2-u4-X12"},{"t":"스마일 마트","mis":"K6-2-u4-X12"}],"explanation":["솔바람길 · 한아름 꽃집은 확인한 곳을 밝혔어요.","스마일 마트도 확인한 곳을 적었어요.","다온 마을만 출처가 없어요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#10','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C8',2,'ox','auto','시우네 모둠은 「솔바람길」을 솔 · 바람 · 길로 나누어 살펴 고유어를 찾았어요.',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":10,"concept":"K6-2-u4-C8","difficulty":2,"kind":"ox","stem":"시우네 모둠은 「솔바람길」을 솔 · 바람 · 길로 나누어 살펴 고유어를 찾았어요.","answer":"O","reason_options":[{"t":"여러 낱말로 이루어진 이름은 낱말을 나누어 살펴야 하기 때문에","correct":true},{"t":"이름은 나누지 않고 통째로 보아야 하기 때문에","mis":"K6-2-u4-X10"}],"mis":"K6-2-u4-X10","explanation":["이름을 낱말로 나누었어요.","솔 · 바람 · 길은 모두 고유어예요.","그래서 좋은 사례예요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#11','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C12',2,'mc','auto','외할머니가 말한 「갈무리하다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X18']::text[],false,'{"seq":11,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"외할머니가 말한 「갈무리하다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"물건을 잘 정리하여 간수함","correct":true},{"t":"물건을 버림","mis":"K6-2-u4-X18"},{"t":"물건을 새로 사 옴","mis":"K6-2-u4-X18"},{"t":"물건을 남에게 빌려줌","mis":"K6-2-u4-X18"}],"explanation":["「잘 갈무리해 두었더니 아직 멀쩡하구나」라고 하셨어요.","오래된 수첩이 멀쩡히 남았어요.","잘 정리하여 간수했다는 뜻이에요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#12','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C13',2,'mc','auto','외할머니가 「정구지」 · 「가새」라고 하신 말에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X16']::text[],false,'{"seq":12,"concept":"K6-2-u4-C13","difficulty":2,"kind":"mc","stem":"외할머니가 「정구지」 · 「가새」라고 하신 말에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 고장에서 쓰는 말로, 고장 사람끼리 정답게 쓰는 소중한 우리말이다","correct":true},{"t":"고쳐 드려야 할 틀린 말이다","mis":"K6-2-u4-X19"},{"t":"배우지 못해서 쓰시는 말이다","mis":"K6-2-u4-X19"},{"t":"서윤이를 놀리려고 지어낸 말이다","mis":"K6-2-u4-X16"}],"explanation":["방언은 틀린 말이 아니에요.","그 고장의 정과 역사가 담겨 있어요.","쓰이는 자리가 다를 뿐이에요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#13','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C15',2,'mc','auto','지후의 다짐 가운데 지킬 수 있는 다짐은 어느 것인가요?',ARRAY['K6-2-u4-X23']::text[],false,'{"seq":13,"concept":"K6-2-u4-C15","difficulty":2,"kind":"mc","stem":"지후의 다짐 가운데 지킬 수 있는 다짐은 어느 것인가요?","options":[{"t":"쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠다는 다짐","correct":true},{"t":"우리말을 아주 열심히 사랑하겠다는 다짐","mis":"K6-2-u4-X23"},{"t":"외래어를 하나도 쓰지 않겠다는 다짐","mis":"K6-2-u4-X23"},{"t":"다들 줄인 말을 쓰지 말자는 다짐","mis":"K6-2-u4-X23"}],"explanation":["언제 · 무엇을 할지가 드러나야 해요.","「쉬는 시간에」 · 「풀어 주기」가 드러나요.","나머지는 막연하거나 너무 크거나 내 일이 없어요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#14','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C16',2,'mc','auto','하람이네가 인쇄물을 고른 것이 알맞은 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X27','K6-2-u4-X13']::text[],false,'{"seq":14,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"하람이네가 인쇄물을 고른 것이 알맞은 까닭은 어느 것인가요?","options":[{"t":"바꾸면 좋은 말을 붙여 두고 여러 번 보게 할 수 있어서","correct":true},{"t":"움직임과 목소리를 전할 수 있어서","mis":"K6-2-u4-X27"},{"t":"짧은 이야기로 이해시킬 수 있어서","mis":"K6-2-u4-X27"},{"t":"가장 화려하게 꾸밀 수 있어서","mis":"K6-2-u4-X13"}],"explanation":["바꾸면 좋은 말은 여러 번 보아야 익어요.","인쇄물은 한자리에 붙여 둘 수 있어요.","알릴 내용과 방법이 잘 맞아요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#15','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C5',2,'mc','auto','시의 마지막 「이름을 알고 보니 / 모두 다르게 보인다」에 담긴 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X06','K6-2-u4-X16']::text[],false,'{"seq":15,"concept":"K6-2-u4-C5","difficulty":2,"kind":"mc","stem":"시의 마지막 「이름을 알고 보니 / 모두 다르게 보인다」에 담긴 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"고유어의 뜻을 알면 장면이 더 또렷이 보인다","correct":true},{"t":"이름은 몰라도 아무 상관이 없다","mis":"K6-2-u4-X06"},{"t":"비가 그치자 사물의 모양이 바뀌었다","mis":"K6-2-u4-X16"},{"t":"사물에 새 이름을 지어 주었다","mis":"K6-2-u4-X16"}],"explanation":["여울 · 오솔길 · 잔물결에는 장면이 담겨 있어요.","뜻을 알면 그 장면이 보여요.","고유어가 느낌과 장면을 살려요."],"asset":{"type":"passage","lines":["밤새 내린 비에 / 개울이 불었다.","어제는 없던 여울이 / 돌 사이로 소리를 낸다.","오솔길 풀잎마다 / 이슬이 조롱조롱.","어스름에 잠겼던 마을이 / 천천히 깨어난다.","바람 한 줄기에 / 잔물결이 반짝인다.","이름을 알고 보니 / 모두 다르게 보인다."],"title":"시 「비 그친 아침」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#16','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C13',2,'mc','auto','전교 방송으로 학교 행사를 안내할 때 알맞은 말은 어느 것인가요?',ARRAY['K6-2-u4-X20','K6-2-u4-X03']::text[],false,'{"seq":16,"concept":"K6-2-u4-C13","difficulty":2,"kind":"mc","stem":"전교 방송으로 학교 행사를 안내할 때 알맞은 말은 어느 것인가요?","options":[{"t":"온 학교 사람이 두루 알아듣도록 표준어로 말한다","correct":true},{"t":"내가 사는 고장 말로만 말한다","mis":"K6-2-u4-X20"},{"t":"줄인 말로 짧게 말한다","mis":"K6-2-u4-X03"},{"t":"외국어를 섞어 멋있게 말한다","mis":"K6-2-u4-X03"}],"explanation":["전교 방송은 공식적인 자리예요.","모두가 알아들어야 해요.","그래서 표준어로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#17','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C10',3,'mc','auto','시우네가 표와 지도를 함께 쓰려고 해요. 각 매체를 쓰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":17,"concept":"K6-2-u4-C10","difficulty":3,"kind":"mc","stem":"시우네가 표와 지도를 함께 쓰려고 해요. 각 매체를 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"표로 네 사례를 한눈에 견주고, 지도로 길과 동네가 어디에 있는지 보여 준다","correct":true},{"t":"표는 화려하게, 지도는 크게 꾸며 눈길을 끈다","mis":"K6-2-u4-X13"},{"t":"표와 지도에 자료를 최대한 많이 넣는다","mis":"K6-2-u4-X13"},{"t":"매체는 아무것이나 골라 내용을 끼워 넣는다","mis":"K6-2-u4-X13"}],"explanation":["표는 견주기에 알맞아요.","지도는 위치를 보여 줘요.","알릴 내용에 맞추어 매체를 골라요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#18','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C12',3,'error','auto','서윤이 이야기를 읽고 추론했어요. 알맞지 않게 추론한 친구는 누구인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X18']::text[],false,'{"seq":18,"concept":"K6-2-u4-C12","difficulty":3,"kind":"error","stem":"서윤이 이야기를 읽고 추론했어요. 알맞지 않게 추론한 친구는 누구인가요?","options":[{"t":"주원 — 「외할머니는 서윤이가 수첩을 팔기를 바라셨을 거야. 그냥 그럴 것 같아.」","correct":true,"mis_target":"K6-2-u4-X16"},{"t":"나린 — 「끝 장의 ‘다음은 누가?’와 연필을 이어 보면 이어 적기를 바라신 거야.」","mis":"K6-2-u4-X16"},{"t":"도겸 — 「씻어 오라고 하셨고 바구니에 채소가 있으니 정구지는 채소 이름일 거야.」","mis":"K6-2-u4-X18"}],"explanation":["나린과 도겸은 글에서 단서를 찾았어요.","주원은 까닭이 글에 없어요.","추론은 마음대로 지어내는 것이 아니에요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#19','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C15',3,'mc','auto','지후의 「앞으로 우리말을 아주 열심히 사랑하겠습니다」를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X23']::text[],false,'{"seq":19,"concept":"K6-2-u4-C15","difficulty":3,"kind":"mc","stem":"지후의 「앞으로 우리말을 아주 열심히 사랑하겠습니다」를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「나는 알림장을 쓸 때 쉬운 우리말로 바꿀 수 있는 말을 하나씩 바꾸어 쓰겠습니다.」","correct":true},{"t":"「나는 우리말을 정말 정말 사랑하겠습니다.」","mis":"K6-2-u4-X23"},{"t":"「나는 영원히 우리말만 쓰겠습니다.」","mis":"K6-2-u4-X23"},{"t":"「우리 모두 우리말을 사랑합시다.」","mis":"K6-2-u4-X23"}],"explanation":["「열심히」에는 무엇을 할지가 없어요.","언제 · 무엇을 할지 넣어 고쳐요.","지킬 수 있는 크기로 써요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#20','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C16',3,'mc','auto','하람이네 계획에서 잘된 점은 어느 것인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X26']::text[],false,'{"seq":20,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"하람이네 계획에서 잘된 점은 어느 것인가요?","options":[{"t":"알릴 내용(바꾸면 좋은 말)과 방법(오래 붙여 두는 인쇄물)이 잘 맞는다","correct":true},{"t":"문구에 외국어가 있어 눈에 띈다","mis":"K6-2-u4-X25"},{"t":"하루 만에 끝나 부담이 없다","mis":"K6-2-u4-X26"},{"t":"역할을 정하지 않아 자유롭다","mis":"K6-2-u4-X25"}],"explanation":["잘된 점을 먼저 찾아요.","내용과 방법이 잘 맞아요.","문구 · 역할 · 시간은 고칠 점이에요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#21','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C11',3,'ox','auto','고장 말을 어른께 여쭈어 적어 두는 것도 우리말을 지키는 일이에요.',ARRAY['K6-2-u4-X15']::text[],false,'{"seq":21,"concept":"K6-2-u4-C11","difficulty":3,"kind":"ox","stem":"고장 말을 어른께 여쭈어 적어 두는 것도 우리말을 지키는 일이에요.","answer":"O","reason_options":[{"t":"적어 두지 않으면 쓰는 사람이 줄면서 사라질 수 있기 때문에","correct":true},{"t":"표준어만 지키면 되기 때문에","mis":"K6-2-u4-X15"}],"mis":"K6-2-u4-X15","explanation":["말은 저절로 남지 않아요.","쓰는 사람이 줄면 사라질 수 있어요.","적어 두는 것이 지키는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#22','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C2',3,'ox','auto','듣는 사람이 누구든 늘 같은 말로만 말하는 것이 상황에 맞게 쓰는 거예요.',ARRAY['K6-2-u4-X20']::text[],false,'{"seq":22,"concept":"K6-2-u4-C2","difficulty":3,"kind":"ox","stem":"듣는 사람이 누구든 늘 같은 말로만 말하는 것이 상황에 맞게 쓰는 거예요.","answer":"X","reason_options":[{"t":"누구에게 어디에서 말하느냐에 따라 골라 써야 하기 때문에","correct":true},{"t":"말은 한 가지로 통일해야 하기 때문에","mis":"K6-2-u4-X20"}],"mis":"K6-2-u4-X20","explanation":["말은 누구에게, 어디에서 하느냐에 따라 달라져요.","공식적인 자리에서는 표준어로 말해요.","고장 사람과는 고장 말로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#23','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C12',4,'mc','auto','서윤이 이야기에서 외할머니의 마음을 추론한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17','K6-2-u4-X19']::text[],false,'{"seq":23,"concept":"K6-2-u4-C12","difficulty":4,"kind":"mc","stem":"서윤이 이야기에서 외할머니의 마음을 추론한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓰는 사람이 줄어 사라질 수 있는 동네 말을 서윤이가 이어 적어 주기를 바라셨다 — 갈무리해 둔 수첩, 끝 장의 물음, 밀어 준 연필이 단서다","correct":true},{"t":"서윤이에게 연필을 선물하고 싶으셨을 뿐이다","mis":"K6-2-u4-X16"},{"t":"글에 적혀 있지 않으니 아무것도 알 수 없다","mis":"K6-2-u4-X17"},{"t":"표준어를 몰라서 수첩에 적어 두셨다","mis":"K6-2-u4-X19"}],"explanation":["단서를 여러 개 모아요.","수첩 · 물음 · 연필이 같은 곳을 가리켜요.","글에 없는 마음도 단서로 메울 수 있어요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#24','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C12',4,'essay','teacher','서윤이 이야기에서 외할머니가 서윤이에게 바라신 것을 추론해 쓰고, 그렇게 추론한 단서를 두 가지 쓰세요. 그리고 서윤이가 「정구지」의 뜻을 짐작할 수 있었던 단서도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C12","difficulty":4,"kind":"essay","stem":"서윤이 이야기에서 외할머니가 서윤이에게 바라신 것을 추론해 쓰고, 그렇게 추론한 단서를 두 가지 쓰세요. 그리고 서윤이가 「정구지」의 뜻을 짐작할 수 있었던 단서도 쓰세요.","answer_guide":{"answer":"예: 외할머니는 서윤이가 동네 말을 수첩에 이어 적어 주기를 바라셨을 것이다. 단서 — 수첩 맨 끝 장에 「다음은 누가?」라고 적혀 있었다. 외할머니가 연필을 수첩 위에 올려 서윤이 쪽으로 밀어 주셨다. 정구지의 단서 — 외할머니가 정구지를 씻어 오라고 하셨고, 바구니에 초록 채소가 담겨 있었다.","scoring_points":["외할머니의 바람을 알맞게 추론했는가","글에서 단서를 두 가지 찾았는가","낱말 뜻을 짐작한 문맥 단서를 썼는가"]},"explanation":["적힌 것과 메운 생각을 갈라요.","까닭은 글 안에서 찾아요.","앞뒤 말과 장면이 낱말의 단서예요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#25','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C13',4,'essay','teacher','표준어와 방언이 각각 하는 일을 쓰고, 표준어로 말해야 할 상황과 고장 말로 말해도 좋은 상황을 하나씩 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C13","difficulty":4,"kind":"essay","stem":"표준어와 방언이 각각 하는 일을 쓰고, 표준어로 말해야 할 상황과 고장 말로 말해도 좋은 상황을 하나씩 들어 쓰세요.","answer_guide":{"answer":"예: 표준어는 사는 곳이 달라도 서로 통하게 해 주고, 방언은 그 고장의 정과 역사를 담아 전해 준다. 표준어로 말해야 할 상황 — 전교 방송으로 학교 행사를 안내할 때. 고장 말로 말해도 좋은 상황 — 외할머니 댁에서 이웃 어른들과 이야기를 나눌 때.","scoring_points":["표준어와 방언이 하는 일을 각각 썼는가","표준어로 말할 상황을 알맞게 들었는가","고장 말로 말해도 좋은 상황을 알맞게 들었는가"]},"explanation":["표준어는 두루 통하게.","방언은 정과 역사를.","누구에게 · 어디에서 말하는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#1','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C1',1,'ox','auto','「토마토」는 외래어예요.',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"ox","stem":"「토마토」는 외래어예요.","answer":"O","reason_options":[{"t":"다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말이기 때문에","correct":true},{"t":"고유어로 바꾸어 써야 하는 낱말이기 때문에","mis":"K6-2-u4-X08"}],"mis":"K6-2-u4-X08","explanation":["토마토는 다른 나라에서 들어온 말이에요.","우리 생활에서 널리 쓰여요.","그래서 외래어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#2','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C2',1,'sa','auto','말은 뜻을 주고받으려고 써요. 그래서 바르게 쓴다는 것은 듣는 사람이 ○○○○ 수 있게 쓰는 것이에요. ○○○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C2","difficulty":1,"kind":"sa","stem":"말은 뜻을 주고받으려고 써요. 그래서 바르게 쓴다는 것은 듣는 사람이 ○○○○ 수 있게 쓰는 것이에요. ○○○○에 알맞은 말을 쓰세요.","answer":["알아들을"],"explanation":["말이 통해야 뜻을 주고받아요.","듣는 사람의 처지에서 생각해요.","알아들을 수 있게 쓰는 것이 바르게 쓰기예요."],"mis":"K6-2-u4-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#3','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C14',1,'mc','auto','언어생활 점검표에서 늘려 가고 싶은 말은 어느 것인가요?',ARRAY['K6-2-u4-X03','K6-2-u4-X04']::text[],false,'{"seq":3,"concept":"K6-2-u4-C14","difficulty":1,"kind":"mc","stem":"언어생활 점검표에서 늘려 가고 싶은 말은 어느 것인가요?","options":[{"t":"즐겨 쓰는 고유어","correct":true},{"t":"굳이 외국어로 쓴 말","mis":"K6-2-u4-X03"},{"t":"지나치게 줄인 말","mis":"K6-2-u4-X03"},{"t":"기분을 상하게 하는 말","mis":"K6-2-u4-X04"}],"explanation":["외국어 · 줄인 말 · 기분 상하는 말은 줄여 갈 말이에요.","즐겨 쓰는 고유어는 늘려 갈 말이에요.","점검표에 함께 표시해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#4','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C5',1,'ox','auto','「눈썰미」처럼 고유어를 이어 붙여 만든 낱말도 고유어예요.',ARRAY['K6-2-u4-X06']::text[],false,'{"seq":4,"concept":"K6-2-u4-C5","difficulty":1,"kind":"ox","stem":"「눈썰미」처럼 고유어를 이어 붙여 만든 낱말도 고유어예요.","answer":"O","reason_options":[{"t":"고유어를 바탕으로 만들어진 낱말도 고유어이기 때문에","correct":true},{"t":"처음부터 있던 낱말만 고유어이기 때문에","mis":"K6-2-u4-X06"}],"mis":"K6-2-u4-X06","explanation":["고유어에는 두 모습이 있어요.","처음부터 있던 낱말과 그것으로 만든 낱말이에요.","눈썰미는 만든 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#5','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C7',1,'mc','auto','「낯을 가리다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":5,"concept":"K6-2-u4-C7","difficulty":1,"kind":"mc","stem":"「낯을 가리다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"낯선 사람을 어려워하다","correct":true},{"t":"얼굴을 손으로 가리다","mis":"K6-2-u4-X09"},{"t":"음식을 가려 먹다","mis":"K6-2-u4-X09"},{"t":"부끄러워 화를 내다","mis":"K6-2-u4-X09"}],"explanation":["관용 표현은 낱말 뜻을 그대로 더하지 않아요.","두 낱말이 어울려 새 뜻을 만들어요.","낯을 가리다는 낯선 사람을 어려워한다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#6','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C10',1,'ox','auto','발표 자료는 정해진 시간에 전할 수 있는 만큼만 담아요.',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":6,"concept":"K6-2-u4-C10","difficulty":1,"kind":"ox","stem":"발표 자료는 정해진 시간에 전할 수 있는 만큼만 담아요.","answer":"O","reason_options":[{"t":"너무 많으면 듣는 사람이 이해하기 어렵기 때문에","correct":true},{"t":"자료가 많을수록 좋은 발표이기 때문에","mis":"K6-2-u4-X13"}],"mis":"K6-2-u4-X13","explanation":["발표 시간은 정해져 있어요.","너무 많으면 전하지 못해요.","이해에 도움이 되는 만큼 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#7','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C13',1,'ox','auto','표준어와 방언 사이에도 등수는 없어요.',ARRAY['K6-2-u4-X19']::text[],false,'{"seq":7,"concept":"K6-2-u4-C13","difficulty":1,"kind":"ox","stem":"표준어와 방언 사이에도 등수는 없어요.","answer":"O","reason_options":[{"t":"둘 다 소중한 우리말이고 쓰이는 자리가 다를 뿐이기 때문에","correct":true},{"t":"표준어가 더 바른 말이기 때문에","mis":"K6-2-u4-X19"}],"mis":"K6-2-u4-X19","explanation":["갈래에 등수가 없듯이 표준어와 방언도 그래요.","쓰이는 자리가 다를 뿐이에요.","둘 다 소중한 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#8','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C16',1,'ox','auto','우리말 홍보물에는 알릴 내용이 먼저이고 꾸밈은 그다음이에요.',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":8,"concept":"K6-2-u4-C16","difficulty":1,"kind":"ox","stem":"우리말 홍보물에는 알릴 내용이 먼저이고 꾸밈은 그다음이에요.","answer":"O","reason_options":[{"t":"보는 사람이 무엇을 알게 되고 무엇을 할지가 드러나야 하기 때문에","correct":true},{"t":"꾸밈이 화려해야 사람들이 내용을 읽기 때문에","mis":"K6-2-u4-X25"}],"mis":"K6-2-u4-X25","explanation":["꾸미는 데 시간을 다 쓰면 내용이 가려져요.","알릴 것이 한눈에 보여야 해요.","꾸밈은 그다음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#9','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C9',2,'ox','auto','시우네 모둠은 「다온 마을」의 뜻을 「짐작했습니다」나 「아직 확인하지 못했습니다」라고 밝혀야 해요.',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":9,"concept":"K6-2-u4-C9","difficulty":2,"kind":"ox","stem":"시우네 모둠은 「다온 마을」의 뜻을 「짐작했습니다」나 「아직 확인하지 못했습니다」라고 밝혀야 해요.","answer":"O","reason_options":[{"t":"확인한 것과 짐작한 것을 섞으면 듣는 사람이 잘못 알 수 있기 때문에","correct":true},{"t":"그럴듯한 뜻이면 확인한 것처럼 말해도 되기 때문에","mis":"K6-2-u4-X12"}],"mis":"K6-2-u4-X12","explanation":["다온 마을의 뜻에는 출처가 없어요.","확인한 것처럼 말하면 안 돼요.","짐작이면 짐작이라고 밝혀요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#10','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C10',2,'mc','auto','시우네 발표를 듣고 한 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X14']::text[],false,'{"seq":10,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"시우네 발표를 듣고 한 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「‘솔바람길’에 지금도 소나무가 많은지 궁금해요. 이름의 뜻이 지금 모습과 맞는지 알고 싶어서요.」","correct":true},{"t":"「그냥 물어봤어요.」","mis":"K6-2-u4-X14"},{"t":"「우리 모둠이 더 잘하지 않았나요?」","mis":"K6-2-u4-X14"},{"t":"「발표가 언제 끝나요?」","mis":"K6-2-u4-X14"}],"explanation":["발표 내용을 정리하며 들어요.","궁금한 점과 까닭을 함께 말해요.","그래야 묻고 답하며 이야기가 이어져요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#11','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C13',2,'sa','auto','외할머니가 말한 「가새」는 표준어로 무엇일까요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"K6-2-u4-C13","difficulty":2,"kind":"sa","stem":"외할머니가 말한 「가새」는 표준어로 무엇일까요? 두 글자로 쓰세요.","answer":["가위"],"explanation":["「가새는 저 서랍에 있다」고 하셨어요.","서윤이는 서랍 속 가위를 보았어요.","가새는 가위를 가리키는 고장 말이에요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"},"mis":"K6-2-u4-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#12','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C11',2,'ox','auto','외할머니의 수첩은 우리말을 지키려는 노력과 닮았어요.',ARRAY['K6-2-u4-X15']::text[],false,'{"seq":12,"concept":"K6-2-u4-C11","difficulty":2,"kind":"ox","stem":"외할머니의 수첩은 우리말을 지키려는 노력과 닮았어요.","answer":"O","reason_options":[{"t":"사라질 수 있는 고장 말을 생각날 때마다 모아 적어 두었기 때문에","correct":true},{"t":"수첩이 오래되어 귀한 물건이기 때문에","mis":"K6-2-u4-X15"}],"mis":"K6-2-u4-X15","explanation":["외할머니는 동네 말을 적어 두셨어요.","적어 두어야 말이 남아요.","우리말 사전을 만든 노력과 닮았어요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#13','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C15',2,'ox','auto','지후의 「오늘부터 외래어를 하나도 쓰지 않겠습니다」는 지킬 수 있는 다짐이에요.',ARRAY['K6-2-u4-X02']::text[],false,'{"seq":13,"concept":"K6-2-u4-C15","difficulty":2,"kind":"ox","stem":"지후의 「오늘부터 외래어를 하나도 쓰지 않겠습니다」는 지킬 수 있는 다짐이에요.","answer":"X","reason_options":[{"t":"버스 · 컴퓨터처럼 바꿀 말이 마땅치 않은 외래어도 있어 지킬 수 없는 크기이기 때문에","correct":true},{"t":"외래어를 쓰지 않는 것이 우리말을 지키는 길이기 때문에","mis":"K6-2-u4-X02"}],"mis":"K6-2-u4-X02","explanation":["외래어도 우리말의 한 갈래예요.","바꿀 말이 없는 외래어도 많아요.","지킬 수 없는 크기의 다짐이에요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#14','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C16',2,'ox','auto','하람이네가 역할을 정하지 않고 꾸미기부터 시작한 것은 괜찮아요.',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":14,"concept":"K6-2-u4-C16","difficulty":2,"kind":"ox","stem":"하람이네가 역할을 정하지 않고 꾸미기부터 시작한 것은 괜찮아요.","answer":"X","reason_options":[{"t":"역할을 먼저 나누어야 빠지는 사람 없이 함께할 수 있기 때문에","correct":true},{"t":"꾸미기를 먼저 해야 알릴 내용이 정해지기 때문에","mis":"K6-2-u4-X25"}],"mis":"K6-2-u4-X25","explanation":["계획은 주제 · 내용 · 역할 · 시간이에요.","역할을 먼저 나누어요.","꾸밈은 내용 다음이에요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#15','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C5',2,'sa','auto','「비 그친 아침」에서 물살이 세게 흐르는 얕은 곳을 가리키는 고유어를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"K6-2-u4-C5","difficulty":2,"kind":"sa","stem":"「비 그친 아침」에서 물살이 세게 흐르는 얕은 곳을 가리키는 고유어를 두 글자로 쓰세요.","answer":["여울"],"explanation":["개울이 불어 생긴 곳이에요.","돌 사이로 소리를 내요.","그곳이 여울이에요."],"asset":{"type":"passage","lines":["밤새 내린 비에 / 개울이 불었다.","어제는 없던 여울이 / 돌 사이로 소리를 낸다.","오솔길 풀잎마다 / 이슬이 조롱조롱.","어스름에 잠겼던 마을이 / 천천히 깨어난다.","바람 한 줄기에 / 잔물결이 반짝인다.","이름을 알고 보니 / 모두 다르게 보인다."],"title":"시 「비 그친 아침」"},"mis":"K6-2-u4-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#16','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C17',2,'ox','auto','「증발」 · 「지형」 · 「분포」 · 「관측」은 모두 고유어예요.',ARRAY['K6-2-u4-X01']::text[],false,'{"seq":16,"concept":"K6-2-u4-C17","difficulty":2,"kind":"ox","stem":"「증발」 · 「지형」 · 「분포」 · 「관측」은 모두 고유어예요.","answer":"X","reason_options":[{"t":"모두 한자로 이루어진 한자어이기 때문에","correct":true},{"t":"교과서에 자주 나오기 때문에","mis":"K6-2-u4-X01"}],"mis":"K6-2-u4-X01","explanation":["네 낱말은 모두 한자로 되어 있어요.","그래서 한자어예요.","자주 나온다고 고유어가 되지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#17','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C8',3,'ox','auto','시우네 표에서 고유어를 활용한 사례라고 확실히 말할 수 있는 것은 솔바람길과 한아름 꽃집이에요.',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":17,"concept":"K6-2-u4-C8","difficulty":3,"kind":"ox","stem":"시우네 표에서 고유어를 활용한 사례라고 확실히 말할 수 있는 것은 솔바람길과 한아름 꽃집이에요.","answer":"O","reason_options":[{"t":"두 이름은 낱말을 나누어 고유어를 찾고 확인한 곳까지 밝혔기 때문에","correct":true},{"t":"다온 마을과 스마일 마트도 이름이 예뻐서 모두 고유어 사례이기 때문에","mis":"K6-2-u4-X10"}],"mis":"K6-2-u4-X10","explanation":["솔바람길 · 한아름 꽃집은 확인이 되었어요.","다온 마을은 뜻의 출처가 없어요.","스마일 마트는 고유어가 아니에요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#18','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C12',3,'ox','auto','「다음은 누가?」는 글에 적힌 단서이고, 「서윤이가 이어 적기를 바라셨다」는 추론한 내용이에요.',ARRAY['K6-2-u4-X17']::text[],false,'{"seq":18,"concept":"K6-2-u4-C12","difficulty":3,"kind":"ox","stem":"「다음은 누가?」는 글에 적힌 단서이고, 「서윤이가 이어 적기를 바라셨다」는 추론한 내용이에요.","answer":"O","reason_options":[{"t":"글에 적힌 것과 단서로 메운 생각을 가를 수 있기 때문에","correct":true},{"t":"둘 다 글에 그대로 적혀 있기 때문에","mis":"K6-2-u4-X17"}],"mis":"K6-2-u4-X17","explanation":["「다음은 누가?」는 글에 있어요.","외할머니의 바람은 글에 없어요.","단서로 메운 것이 추론이에요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#19','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C15',3,'ox','auto','지후의 다짐문에는 잘 쓴 부분이 하나도 없어요.',ARRAY['K6-2-u4-X24']::text[],false,'{"seq":19,"concept":"K6-2-u4-C15","difficulty":3,"kind":"ox","stem":"지후의 다짐문에는 잘 쓴 부분이 하나도 없어요.","answer":"X","reason_options":[{"t":"넷째 줄은 지킬 수 있는 다짐이고 날짜와 쓴 사람도 갖추었기 때문에","correct":true},{"t":"고칠 점이 있으면 잘 쓴 부분은 말하지 않아도 되기 때문에","mis":"K6-2-u4-X24"}],"mis":"K6-2-u4-X24","explanation":["잘 쓴 부분을 먼저 찾아요.","넷째 줄과 마지막 줄은 잘 썼어요.","고칠 점은 그다음에 말해요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#20','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C16',3,'ox','auto','하람이네 홍보 문구는 알리려는 내용과 앞뒤가 맞아요.',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":20,"concept":"K6-2-u4-C16","difficulty":3,"kind":"ox","stem":"하람이네 홍보 문구는 알리려는 내용과 앞뒤가 맞아요.","answer":"X","reason_options":[{"t":"쉬운 우리말을 알리면서 문구는 외국어로 썼기 때문에","correct":true},{"t":"외국어를 섞어야 사람들이 관심을 갖기 때문에","mis":"K6-2-u4-X25"}],"mis":"K6-2-u4-X25","explanation":["주제는 쉬운 우리말로 바꾸어 말하기예요.","그런데 문구가 외국어예요.","앞뒤가 맞지 않아요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#21','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C13',3,'error','auto','방언에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X20']::text[],false,'{"seq":21,"concept":"K6-2-u4-C13","difficulty":3,"kind":"error","stem":"방언에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「‘가새’라고 하는 사람은 우리말을 잘못 배운 거야.」","correct":true,"mis_target":"K6-2-u4-X19"},{"t":"리아 — 「다른 고장의 말을 웃음거리로 삼지 말자.」","mis":"K6-2-u4-X19"},{"t":"선우 — 「공식적인 자리에서는 표준어로 말하자.」","mis":"K6-2-u4-X20"}],"explanation":["리아와 선우는 방언과 표준어의 자리를 알아요.","태윤은 방언을 잘못 배운 말로 여겼어요.","방언도 소중한 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#22','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C6',3,'error','auto','다듬은 말에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":22,"concept":"K6-2-u4-C6","difficulty":3,"kind":"error","stem":"다듬은 말에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하온 — 「‘학교’와 ‘수학’도 한자어니까 다듬어서 바꾸어야 해.」","correct":true,"mis_target":"K6-2-u4-X08"},{"t":"지유 — 「‘회람’은 ‘돌려보기’로 다듬으면 뜻이 잘 드러나.」","mis":"K6-2-u4-X08"},{"t":"준후 — 「다듬는 목적은 누구나 알아들을 수 있게 하는 거야.」","mis":"K6-2-u4-X08"}],"explanation":["지유와 준후는 다듬기를 바르게 말했어요.","하온은 모든 한자어를 바꾸려 했어요.","학교 · 수학은 그대로 쓰는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#23','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C15',4,'mc','auto','지후의 다짐문을 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X24','K6-2-u4-X23']::text[],false,'{"seq":23,"concept":"K6-2-u4-C15","difficulty":4,"kind":"mc","stem":"지후의 다짐문을 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"목적 줄을 맨 앞에 넣고, 막연하거나 너무 크거나 내 일이 없는 줄은 언제 · 무엇을 할지 드러나게 고치고, 넷째 줄과 날짜 · 쓴 사람은 살린다","correct":true},{"t":"모두 지우고 처음부터 새로 쓴다","mis":"K6-2-u4-X24"},{"t":"글씨를 반듯하게 쓰고 종이를 바꾼다","mis":"K6-2-u4-X24"},{"t":"「다들」을 「꼭」으로 바꾸어 더 세게 쓴다","mis":"K6-2-u4-X23"}],"explanation":["살릴 것을 먼저 정해요.","빠진 목적을 넣어요.","고칠 줄은 지킬 수 있게 고쳐요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#24','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C15',4,'essay','teacher','지후의 다짐문에서 잘 쓴 부분과 고칠 부분을 하나씩 쓰고, 빠진 부분을 넣어 지킬 수 있는 다짐문으로 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C15","difficulty":4,"kind":"essay","stem":"지후의 다짐문에서 잘 쓴 부분과 고칠 부분을 하나씩 쓰고, 빠진 부분을 넣어 지킬 수 있는 다짐문으로 고쳐 쓰세요.","answer_guide":{"answer":"예: 잘 쓴 부분 — 「쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다」는 언제 무엇을 할지가 드러나 지킬 수 있다. 고칠 부분 — 「다들 줄인 말을 쓰지 맙시다」는 내가 할 일이 없다. 고쳐 쓴 다짐문 — 나는 친구들과 서로 잘 알아듣는 말을 쓰기 위해 다음과 같이 다짐합니다. 하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다. 하나, 나는 모둠 활동에서 줄인 말을 쓰면 바로 풀어서 다시 말하겠습니다. 모두 함께 우리말을 지켜 주세요. 쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후.","scoring_points":["잘 쓴 부분을 먼저 찾았는가","고칠 부분을 내용에서 찾았는가","목적을 넣고 네 부분을 갖추어 지킬 수 있게 고쳐 썼는가"]},"explanation":["잘 쓴 곳 먼저.","빠진 목적을 넣어요.","언제 · 무엇을 · 내가."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#25','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C2',4,'essay','teacher','이 단원에서 배운 말로 「우리말을 바르게 쓴다는 것」을 설명하고, 앞으로 실천할 다짐을 언제 · 어디에서 · 무엇을 할지 넣어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C2","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 말로 「우리말을 바르게 쓴다는 것」을 설명하고, 앞으로 실천할 다짐을 언제 · 어디에서 · 무엇을 할지 넣어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 우리말을 바르게 쓴다는 것은 고유어만 쓰거나 다른 갈래를 몰아내는 것이 아니라, 듣는 사람이 알아들을 수 있게, 뜻에 맞게, 바꿀 수 있는 말은 쉬운 우리말로 바꾸어, 상황에 맞게 골라 쓰는 것이다. 다짐 — 나는 모둠 활동을 할 때 교실에서 친구가 못 알아들은 말을 한 번 더 풀어 말하겠다.","scoring_points":["고유어만 쓰는 것이 아님을 밝혔는가","바르게 쓰기의 뜻을 단원의 말로 설명했는가","언제 · 어디에서 · 무엇을이 담긴 다짐을 썼는가"]},"explanation":["몰아내기가 아니에요.","알아듣게, 뜻에 맞게, 상황에 맞게.","다짐은 지킬 수 있게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#1','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C1',1,'mc','auto','고유어끼리 모은 것은 어느 것인가요?',ARRAY['K6-2-u4-X01']::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"mc","stem":"고유어끼리 모은 것은 어느 것인가요?","options":[{"t":"이슬 · 두둑 · 나들이","correct":true},{"t":"채소 · 체육 · 학교","mis":"K6-2-u4-X01"},{"t":"버튼 · 버스 · 토마토","mis":"K6-2-u4-X01"},{"t":"이슬 · 체육 · 버튼","mis":"K6-2-u4-X01"}],"explanation":["채소 · 체육 · 학교는 한자어예요.","버튼 · 버스 · 토마토는 외래어예요.","이슬 · 두둑 · 나들이가 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#2','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C6',1,'mc','auto','낱말의 세 갈래에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K6-2-u4-X07']::text[],false,'{"seq":2,"concept":"K6-2-u4-C6","difficulty":1,"kind":"mc","stem":"낱말의 세 갈래에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"세 갈래가 함께 우리말을 이루고 하는 일이 다르다","correct":true},{"t":"고유어는 좋은 말, 한자어와 외래어는 나쁜 말이다","mis":"K6-2-u4-X07"},{"t":"외래어가 가장 새롭고 좋은 말이다","mis":"K6-2-u4-X07"},{"t":"한자어가 가장 어려워 훌륭한 말이다","mis":"K6-2-u4-X07"}],"explanation":["갈래에는 등수가 없어요.","각 갈래가 하는 일이 달라요.","세 갈래가 함께 우리말을 이뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#3','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C3',1,'mc','auto','「모둠 회의 어젠다를 셰어할게.」라는 말의 문제로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X04','K6-2-u4-X03']::text[],false,'{"seq":3,"concept":"K6-2-u4-C3","difficulty":1,"kind":"mc","stem":"「모둠 회의 어젠다를 셰어할게.」라는 말의 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"쉬운 우리말이 있는데도 어렵게 쓴 외국어라 알아듣기 어렵다","correct":true},{"t":"지나치게 줄인 말이다","mis":"K6-2-u4-X04"},{"t":"기분을 상하게 하는 말이다","mis":"K6-2-u4-X04"},{"t":"아무 문제가 없다","mis":"K6-2-u4-X03"}],"explanation":["「회의할 거리를 나눌게」라고 해도 통해요.","쉬운 말을 두고 외국어를 썼어요.","그래서 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#4','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C5',1,'mc','auto','고유어의 두 모습을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X06']::text[],false,'{"seq":4,"concept":"K6-2-u4-C5","difficulty":1,"kind":"mc","stem":"고유어의 두 모습을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"처음부터 있던 낱말 — 이슬 · 호미 / 바탕으로 만든 낱말 — 나들이 · 마중물","correct":true},{"t":"처음부터 있던 낱말 — 채소 · 토마토 / 바탕으로 만든 낱말 — 이슬","mis":"K6-2-u4-X01"},{"t":"처음부터 있던 낱말 — 마중물 / 바탕으로 만든 낱말 — 버튼","mis":"K6-2-u4-X01"},{"t":"고유어는 처음부터 있던 낱말 한 가지뿐이다","mis":"K6-2-u4-X06"}],"explanation":["이슬 · 호미는 처음부터 있던 말이에요.","나들이 · 마중물은 이어 붙여 만든 말이에요.","둘 다 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#5','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C7',1,'ox','auto','「입이 짧다」는 음식을 심하게 가리거나 적게 먹는다는 뜻이에요.',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":5,"concept":"K6-2-u4-C7","difficulty":1,"kind":"ox","stem":"「입이 짧다」는 음식을 심하게 가리거나 적게 먹는다는 뜻이에요.","answer":"O","reason_options":[{"t":"둘 이상의 낱말이 어울려 새로운 뜻을 만드는 관용 표현이기 때문에","correct":true},{"t":"입의 생김새를 그대로 말한 것이기 때문에","mis":"K6-2-u4-X09"}],"mis":"K6-2-u4-X09","explanation":["입의 길이를 말하는 것이 아니에요.","두 낱말이 어울려 새 뜻을 만들어요.","관용 표현에는 우리 문화와 정서가 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#6','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C9',1,'mc','auto','「아직 확인하지 못했습니다」라고 말해야 할 때는 언제인가요?',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":6,"concept":"K6-2-u4-C9","difficulty":1,"kind":"mc","stem":"「아직 확인하지 못했습니다」라고 말해야 할 때는 언제인가요?","options":[{"t":"사전과 누리집을 찾아보고 어른께 여쭈어도 뜻을 알지 못했을 때","correct":true},{"t":"사전에서 뜻을 찾았을 때","mis":"K6-2-u4-X12"},{"t":"뜻을 짐작했을 때","mis":"K6-2-u4-X12"},{"t":"친구가 뜻을 알려 주었을 때","mis":"K6-2-u4-X12"}],"explanation":["찾은 뜻은 「찾은 뜻입니다」라고 말해요.","짐작은 「짐작했습니다」라고 말해요.","알아내지 못하면 「아직 확인하지 못했습니다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#7','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C13',1,'match','auto','고장에 따라 쓰는 말과 같은 뜻의 표준어를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u4-C13","difficulty":1,"kind":"match","stem":"고장에 따라 쓰는 말과 같은 뜻의 표준어를 알맞게 이으세요.","pairs":[{"l":"정구지","r":"부추"},{"l":"가새","r":"가위"},{"l":"정지","r":"부엌"}],"mis":"K6-2-u4-X19","explanation":["같은 것을 고장마다 다르게 불러요.","정구지는 부추, 가새는 가위예요.","정지는 부엌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#8','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C14',1,'mc','auto','언어생활을 바르게 점검하는 모습은 어느 것인가요?',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":8,"concept":"K6-2-u4-C14","difficulty":1,"kind":"mc","stem":"언어생활을 바르게 점검하는 모습은 어느 것인가요?","options":[{"t":"내가 쓴 말부터 적고, 고칠 점을 우리 반의 일로 말한다","correct":true},{"t":"친구가 쓴 말을 흉내 내며 적는다","mis":"K6-2-u4-X21"},{"t":"누가 더 많이 썼는지 세어 견준다","mis":"K6-2-u4-X21"},{"t":"점검표를 친구에게 증거처럼 내민다","mis":"K6-2-u4-X21"}],"explanation":["점검은 흠잡기가 아니에요.","내가 쓴 말부터 적어요.","바라는 점을 함께 이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#9','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C8',2,'mc','auto','시우네 표의 「스마일 마트」를 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X10','K6-2-u4-X12','K6-2-u4-X01']::text[],false,'{"seq":9,"concept":"K6-2-u4-C8","difficulty":2,"kind":"mc","stem":"시우네 표의 「스마일 마트」를 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"고유어가 들어간 다른 가게 이름을 찾아 바꾸어 넣는다","correct":true},{"t":"「스마일」을 고유어라고 그대로 둔다","mis":"K6-2-u4-X10"},{"t":"뜻 칸만 지운다","mis":"K6-2-u4-X12"},{"t":"영어 사전에서 확인했으니 그대로 둔다","mis":"K6-2-u4-X01"}],"explanation":["스마일은 고유어가 아니에요.","확인한 곳을 밝혀도 갈래는 바뀌지 않아요.","고유어가 들어간 이름으로 바꾸어요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#10','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C9',2,'mc','auto','시우네가 「한아름」의 뜻을 국어사전에서 확인한 것이 좋은 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X14','K6-2-u4-X12']::text[],false,'{"seq":10,"concept":"K6-2-u4-C9","difficulty":2,"kind":"mc","stem":"시우네가 「한아름」의 뜻을 국어사전에서 확인한 것이 좋은 까닭은 어느 것인가요?","options":[{"t":"짐작이 아니라 확인한 뜻을 전할 수 있어서","correct":true},{"t":"사전 뜻은 꾸미기 좋아서","mis":"K6-2-u4-X13"},{"t":"다른 모둠보다 먼저 찾아서","mis":"K6-2-u4-X14"},{"t":"글자 모양을 보니 맞는 것 같아서","mis":"K6-2-u4-X12"}],"explanation":["확인한 뜻은 믿을 수 있어요.","출처도 함께 밝혔어요.","듣는 사람이 다시 확인할 수 있어요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#11','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C12',2,'ox','auto','외할머니가 연필을 서윤이 쪽으로 밀어 주신 것은 아무 뜻이 없어요.',ARRAY['K6-2-u4-X17']::text[],false,'{"seq":11,"concept":"K6-2-u4-C12","difficulty":2,"kind":"ox","stem":"외할머니가 연필을 서윤이 쪽으로 밀어 주신 것은 아무 뜻이 없어요.","answer":"X","reason_options":[{"t":"「다음은 누가?」라는 끝 장과 이어 보면 서윤이가 이어 적기를 바라셨다고 추론할 수 있기 때문에","correct":true},{"t":"글에 그렇게 적혀 있지 않으면 아무것도 알 수 없기 때문에","mis":"K6-2-u4-X17"}],"mis":"K6-2-u4-X17","explanation":["글쓴이는 모든 것을 다 적지 않아요.","끝 장의 물음과 연필을 이어 봐요.","적히지 않은 마음을 단서로 메워요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#12','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C12',2,'mc','auto','서윤이가 「정구지」의 뜻을 짐작할 수 있었던 단서는 어느 것인가요?',ARRAY['K6-2-u4-X18','K6-2-u4-X16']::text[],false,'{"seq":12,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"서윤이가 「정구지」의 뜻을 짐작할 수 있었던 단서는 어느 것인가요?","options":[{"t":"「씻어 오너라」라는 말과 바구니에 담긴 초록 채소","correct":true},{"t":"「정구지」라는 글자의 모양","mis":"K6-2-u4-X18"},{"t":"그냥 그럴 것 같은 느낌","mis":"K6-2-u4-X16"},{"t":"외할머니의 옷차림","mis":"K6-2-u4-X16"}],"explanation":["씻어 오라는 말은 먹을 것을 가리켜요.","눈앞에는 초록 채소가 있었어요.","앞뒤 말과 장면이 단서예요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#13','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C15',2,'mc','auto','지후의 「다들 줄인 말을 쓰지 맙시다」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-2-u4-X23','K6-2-u4-X21']::text[],false,'{"seq":13,"concept":"K6-2-u4-C15","difficulty":2,"kind":"mc","stem":"지후의 「다들 줄인 말을 쓰지 맙시다」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「나는 모둠 활동에서 줄인 말을 쓰면 바로 풀어서 다시 말하겠습니다.」","correct":true},{"t":"「모두 줄인 말을 절대로 쓰지 맙시다.」","mis":"K6-2-u4-X23"},{"t":"「줄인 말을 쓰는 친구를 알려 주세요.」","mis":"K6-2-u4-X21"},{"t":"「줄인 말은 나쁜 말입니다.」","mis":"K6-2-u4-X23"}],"explanation":["실천 약속은 내가 할 일이에요.","언제 · 무엇을 할지 넣어요.","친구를 가려내는 일이 아니에요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#14','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C16',2,'mc','auto','하람이네의 「금요일에 붙이고 그날로 마침」을 고친 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X26']::text[],false,'{"seq":14,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"하람이네의 「금요일에 붙이고 그날로 마침」을 고친 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"붙인 뒤에도 한 주 동안 지킴이 도전을 이어 한다","correct":true},{"t":"붙이는 날을 더 크게 꾸민다","mis":"K6-2-u4-X26"},{"t":"붙인 날 사진을 찍어 남기고 마친다","mis":"K6-2-u4-X26"},{"t":"붙인 홍보물을 다음 날 떼어 낸다","mis":"K6-2-u4-X26"}],"explanation":["하루로 끝나면 행사예요.","이어서 해야 실천이에요.","지킴이 도전처럼 이어 해요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#15','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C5',2,'ox','auto','「비 그친 아침」은 고유어를 써서 느낌과 장면을 살렸어요.',ARRAY['K6-2-u4-X07']::text[],false,'{"seq":15,"concept":"K6-2-u4-C5","difficulty":2,"kind":"ox","stem":"「비 그친 아침」은 고유어를 써서 느낌과 장면을 살렸어요.","answer":"O","reason_options":[{"t":"여울 · 오솔길 · 조롱조롱처럼 장면과 느낌을 그대로 담은 낱말을 썼기 때문에","correct":true},{"t":"고유어만 쓴 글이 가장 훌륭한 글이기 때문에","mis":"K6-2-u4-X07"}],"mis":"K6-2-u4-X07","explanation":["조롱조롱은 이슬 맺힌 모습을 그려요.","여울 · 오솔길은 장면을 담아요.","훌륭함의 등수를 말하는 것은 아니에요."],"asset":{"type":"passage","lines":["밤새 내린 비에 / 개울이 불었다.","어제는 없던 여울이 / 돌 사이로 소리를 낸다.","오솔길 풀잎마다 / 이슬이 조롱조롱.","어스름에 잠겼던 마을이 / 천천히 깨어난다.","바람 한 줄기에 / 잔물결이 반짝인다.","이름을 알고 보니 / 모두 다르게 보인다."],"title":"시 「비 그친 아침」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#16','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C17',2,'sa','auto','「자연 현상을 살펴 재거나 헤아리는 일」을 뜻하는 낱말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"K6-2-u4-C17","difficulty":2,"kind":"sa","stem":"「자연 현상을 살펴 재거나 헤아리는 일」을 뜻하는 낱말을 두 글자로 쓰세요.","answer":["관측"],"explanation":["하늘이나 날씨를 살펴 재는 일이에요.","과학 시간에 자주 나와요.","그 낱말이 관측이에요."],"mis":"K6-2-u4-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#17','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C9',3,'mc','auto','시우네가 「다온 마을」 칸을 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X12','K6-2-u4-X11']::text[],false,'{"seq":17,"concept":"K6-2-u4-C9","difficulty":3,"kind":"mc","stem":"시우네가 「다온 마을」 칸을 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사전에서 찾고 동네 어른께 여쭈어 확인하고, 그래도 모르면 「아직 확인하지 못했습니다」라고 밝힌다","correct":true},{"t":"더 그럴듯한 뜻으로 바꾸어 쓴다","mis":"K6-2-u4-X12"},{"t":"출처 칸에 「국어사전」이라고 적어 둔다","mis":"K6-2-u4-X12"},{"t":"동네 이름은 너무 많으니 조사하지 않는다","mis":"K6-2-u4-X11"}],"explanation":["짐작은 확인으로 이어 가요.","확인하지 못하면 그렇게 말해요.","찾지 않은 출처를 적지 않아요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#18','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C12',3,'match','auto','서윤이 이야기의 단서와 추론한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":18,"concept":"K6-2-u4-C12","difficulty":3,"kind":"match","stem":"서윤이 이야기의 단서와 추론한 내용을 알맞게 이으세요.","pairs":[{"l":"「씻어 오너라」와 바구니의 초록 채소","r":"정구지는 채소 이름일 것이다"},{"l":"「서랍에 있다」와 서랍 속 가위","r":"가새는 가위를 가리킬 것이다"},{"l":"끝 장의 「다음은 누가?」와 밀어 준 연필","r":"이어 적기를 바라셨을 것이다"}],"mis":"K6-2-u4-X16","explanation":["말과 장면을 함께 봐요.","단서마다 알 수 있는 것이 달라요.","까닭은 늘 글 안에 있어요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#19','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C2',3,'mc','auto','지후의 셋째 줄 「오늘부터 외래어를 하나도 쓰지 않겠습니다」를 고쳐야 하는 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X24','K6-2-u4-X07']::text[],false,'{"seq":19,"concept":"K6-2-u4-C2","difficulty":3,"kind":"mc","stem":"지후의 셋째 줄 「오늘부터 외래어를 하나도 쓰지 않겠습니다」를 고쳐야 하는 까닭은 어느 것인가요?","options":[{"t":"외래어를 몰아내는 것은 단원의 약속과 맞지 않고 지킬 수도 없어서","correct":true},{"t":"외래어 대신 한자어만 쓰면 되어서","mis":"K6-2-u4-X02"},{"t":"줄이 너무 길어서","mis":"K6-2-u4-X24"},{"t":"외래어는 나쁜 말이라 더 세게 다짐해야 해서","mis":"K6-2-u4-X07"}],"explanation":["바르게 쓰기는 몰아내기가 아니에요.","바꿀 수 있는 말만 쉬운 말로 바꿔요.","버스 · 컴퓨터는 그대로 써요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#20','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C16',3,'mc','auto','하람이네 계획에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":20,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"하람이네 계획에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 · 내용 · 시간은 정했지만 역할은 정하지 않았다","correct":true},{"t":"주제만 정하고 나머지는 정하지 않았다","mis":"K6-2-u4-X25"},{"t":"네 가지를 모두 빠짐없이 정했다","mis":"K6-2-u4-X25"},{"t":"역할만 정하고 나머지는 정하지 않았다","mis":"K6-2-u4-X25"}],"explanation":["주제 · 내용 · 시간 줄이 있어요.","역할은 「아직 정하지 않음」이에요.","역할을 먼저 정해야 해요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#21','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C11',3,'mc','auto','우리말을 지키기 위해 할 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X19','K6-2-u4-X15']::text[],false,'{"seq":21,"concept":"K6-2-u4-C11","difficulty":3,"kind":"mc","stem":"우리말을 지키기 위해 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"뜻을 모르는 낱말은 사전에서 확인하고, 고장 말은 어른께 여쭈어 적어 둔다","correct":true},{"t":"외래어를 모두 고유어로 바꾼다","mis":"K6-2-u4-X02"},{"t":"고장 말을 모두 표준어로 고쳐 쓴다","mis":"K6-2-u4-X19"},{"t":"말은 저절로 남으니 그대로 둔다","mis":"K6-2-u4-X15"}],"explanation":["사전에서 확인하기는 지키는 일이에요.","고장 말을 여쭈어 적는 것도 그래요.","몰아내거나 내버려 두는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#22','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C14',3,'mc','auto','언어생활을 바꾸어 가는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X21','K6-2-u4-X23','K6-2-u4-X26']::text[],false,'{"seq":22,"concept":"K6-2-u4-C14","difficulty":3,"kind":"mc","stem":"언어생활을 바꾸어 가는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"내가 쓴 말 점검 → 지킬 수 있는 다짐 → 실천 뒤 변화한 점과 노력할 점 되돌아보기","correct":true},{"t":"친구 말 세기 → 가장 많이 쓴 친구 발표 → 끝","mis":"K6-2-u4-X21"},{"t":"크게 말하는 다짐 → 바로 끝","mis":"K6-2-u4-X23"},{"t":"홍보물 하루 붙이기 → 끝","mis":"K6-2-u4-X26"}],"explanation":["먼저 내 말을 살펴요.","지킬 수 있는 다짐을 해요.","되돌아보고 다시 해 보는 것까지가 실천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#23','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C16',4,'mc','auto','하람이네 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X27','K6-2-u4-X26']::text[],false,'{"seq":23,"concept":"K6-2-u4-C16","difficulty":4,"kind":"mc","stem":"하람이네 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"문구를 쉬운 우리말로 바꾸고, 꾸미기 전에 역할을 나누고, 붙인 뒤 한 주 동안 지킴이 도전을 이어 한다","correct":true},{"t":"문구는 그대로 두고 꾸밈을 더 화려하게 한다","mis":"K6-2-u4-X25"},{"t":"인쇄물 대신 한 번 틀고 마는 영상으로 바꾼다","mis":"K6-2-u4-X27"},{"t":"붙이는 날 하루만 우리말을 쓰기로 한다","mis":"K6-2-u4-X26"}],"explanation":["문구 · 역할 · 시간을 고쳐요.","내용과 방법은 그대로 살려요.","하루로 끝내지 않아요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#24','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C16',4,'essay','teacher','하람이네 홍보물 계획에서 잘된 점 하나와 고칠 점 세 가지를 쓰고, 고칠 점을 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C16","difficulty":4,"kind":"essay","stem":"하람이네 홍보물 계획에서 잘된 점 하나와 고칠 점 세 가지를 쓰고, 고칠 점을 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 잘된 점 — 바꾸면 좋은 말을 알리려고 오래 붙여 두고 여러 번 보게 하는 인쇄물을 골라 내용과 방법이 잘 맞는다. 고칠 점 — 홍보 문구가 외국어라 알리려는 내용과 앞뒤가 맞지 않는다. 역할을 정하지 않고 꾸미기부터 시작했다. 붙인 날로 끝나 하루 행사가 된다. 고칠 방법 — 문구를 「쉬운 우리말로 한 번 바꾸어 말해 볼까요?」로 바꾸고, 낱말 찾기 · 글씨 쓰기 역할을 먼저 나누고, 붙인 뒤 한 주 동안 지킴이 도전을 이어 한다.","scoring_points":["잘된 점을 먼저 썼는가","문구 · 역할 · 시간의 고칠 점을 썼는가","고칠 방법을 구체적으로 썼는가"]},"explanation":["내용과 방법은 잘 맞아요.","문구 · 역할 · 시간을 고쳐요.","하루로 끝내지 않아요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#25','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C17',4,'essay','teacher','「관측」과 「증발」의 뜻을 쓰고, 두 낱말을 모두 넣어 과학 시간에 있을 법한 일을 두 문장으로 쓰세요. 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C17","difficulty":4,"kind":"essay","stem":"「관측」과 「증발」의 뜻을 쓰고, 두 낱말을 모두 넣어 과학 시간에 있을 법한 일을 두 문장으로 쓰세요. 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 관측 — 자연 현상을 살펴 재거나 헤아리는 일. 증발 — 액체가 그 표면에서 기체로 변하는 현상. 문장 — 「우리 모둠은 창가에 둔 물그릇을 날마다 같은 시각에 관측했다. 날이 갈수록 물이 증발해서 그릇 속 물이 줄어들었다.」","scoring_points":["두 낱말의 뜻을 바르게 썼는가","두 낱말을 뜻에 맞게 넣어 문장을 썼는가","숫자 없이 있을 법한 일로 썼는가"]},"explanation":["뜻을 정확히 알아 둬요.","문장으로 써 보면 오래 남아요.","교과서에서 다시 만나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
